-- =====================================================================
-- VENDORS, ORDER GUIDES, PRICE HISTORY and the INVENTORY LEDGER
-- =====================================================================

create table public.vendors (
  id                 uuid primary key default gen_random_uuid(),
  organization_id    uuid not null references public.organizations(id) on delete cascade,
  name               text not null check (length(btrim(name)) > 0),
  vendor_number      text,
  account_number     text,
  sales_rep          text,
  phone              text,
  email              text,
  ordering_email     text,
  edi_enabled        boolean not null default false,
  einvoice_enabled   boolean not null default false,
  order_website      text,
  delivery_days      smallint[] not null default '{}' check (delivery_days <@ array[0,1,2,3,4,5,6]::smallint[]), -- 0 = Sunday
  lead_time_days     integer not null default 1 check (lead_time_days >= 0),
  order_cutoff       time,
  minimum_order      numeric(12,2) not null default 0 check (minimum_order >= 0),
  freight_rules      text,
  payment_terms      text,
  notes              text,
  active             boolean not null default true,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  unique (organization_id, name)
);
create trigger trg_vendors_touch before update on public.vendors for each row execute function app.touch_updated_at();
create trigger trg_vendors_audit after insert or update on public.vendors for each row execute function app.audit_row();

alter table public.products add constraint products_default_vendor_fk foreign key (default_vendor_id) references public.vendors(id);
alter table public.location_products add constraint location_products_local_vendor_fk foreign key (local_vendor_id) references public.vendors(id);
alter table public.product_barcodes add constraint product_barcodes_vendor_fk foreign key (vendor_id) references public.vendors(id);

-- Local vendor settings per restaurant (account number, schedule overrides)
create table public.location_vendors (
  id               uuid primary key default gen_random_uuid(),
  organization_id  uuid not null references public.organizations(id) on delete cascade,
  location_id      uuid not null references public.locations(id) on delete cascade,
  vendor_id        uuid not null references public.vendors(id) on delete cascade,
  account_number   text,
  delivery_days    smallint[] check (delivery_days is null or delivery_days <@ array[0,1,2,3,4,5,6]::smallint[]),
  lead_time_days   integer check (lead_time_days is null or lead_time_days >= 0),
  order_cutoff     time,
  active           boolean not null default true,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (location_id, vendor_id)
);
create trigger trg_location_vendors_touch before update on public.location_vendors for each row execute function app.touch_updated_at();

-- Vendor order guide: what a vendor sells us and at what price.
create table public.vendor_products (
  id                   uuid primary key default gen_random_uuid(),
  organization_id      uuid not null references public.organizations(id) on delete cascade,
  vendor_id            uuid not null references public.vendors(id) on delete cascade,
  product_id           uuid not null references public.products(id) on delete cascade,
  vendor_item_number   text not null,
  description          text,
  purchase_unit_id     uuid not null references public.units(id),
  pack_size            text,
  current_price        numeric(18,4) not null default 0 check (current_price >= 0),  -- per purchase unit
  contract_price       numeric(18,4) check (contract_price is null or contract_price >= 0),
  contract_start       date,
  contract_end         date,
  order_multiple       numeric(12,4) not null default 1 check (order_multiple > 0),
  min_order_qty        numeric(12,4) not null default 0 check (min_order_qty >= 0),
  is_preferred         boolean not null default false,
  guide_sort           integer not null default 0,
  active               boolean not null default true,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  unique (vendor_id, vendor_item_number),
  check (contract_start is null or contract_end is null or contract_start <= contract_end)
);
create index on public.vendor_products (product_id);
create index on public.vendor_products (vendor_id, guide_sort);
create trigger trg_vendor_products_touch before update on public.vendor_products for each row execute function app.touch_updated_at();
create trigger trg_vendor_products_audit after insert or update on public.vendor_products for each row execute function app.audit_row();

create or replace function app.vendor_products_guard() returns trigger
language plpgsql as $$
begin
  if app.unit_factor(new.product_id, new.purchase_unit_id) is null then
    raise exception 'Purchase unit % has no conversion for this product. Add the conversion on the product first.',
      (select code from public.units where id = new.purchase_unit_id) using errcode = '22023';
  end if;
  return new;
end $$;
create trigger trg_vendor_products_guard before insert or update on public.vendor_products for each row execute function app.vendor_products_guard();

-- Effective purchase price for a vendor item on a date (contract price when in force).
create or replace function app.vendor_item_price(p_vendor_product uuid, p_on date default current_date) returns numeric
language sql stable security definer set search_path = public as $$
  select case
           when vp.contract_price is not null
                and (vp.contract_start is null or vp.contract_start <= p_on)
                and (vp.contract_end is null or vp.contract_end >= p_on)
           then vp.contract_price else vp.current_price end
  from public.vendor_products vp where vp.id = p_vendor_product
$$;

create table public.price_history (
  id                 bigint generated always as identity primary key,
  organization_id    uuid not null references public.organizations(id) on delete cascade,
  location_id        uuid references public.locations(id) on delete cascade,
  product_id         uuid not null references public.products(id) on delete cascade,
  vendor_id          uuid references public.vendors(id),
  vendor_product_id  uuid references public.vendor_products(id),
  purchase_unit_id   uuid references public.units(id),
  unit_price         numeric(18,4) not null check (unit_price >= 0),     -- per purchase unit
  base_unit_price    numeric(18,6) not null check (base_unit_price >= 0), -- per inventory unit
  effective_at       timestamptz not null,
  source_type        text not null check (source_type in ('invoice','contract','manual','order_guide')),
  source_id          uuid,
  created_by         uuid references public.profiles(id),
  created_at         timestamptz not null default now()
);
create index on public.price_history (product_id, effective_at desc);
create index on public.price_history (location_id, effective_at desc);
create trigger trg_price_history_immutable before update or delete on public.price_history for each row execute function app.prevent_mutation();

-- ---------------------------------------------------------------------
-- INVENTORY TRANSACTION LEDGER (immutable source of truth)
-- ---------------------------------------------------------------------
create type public.inv_txn_type as enum (
  'BEGINNING', 'RECEIPT', 'POS_CONSUMPTION', 'RECIPE_CONSUMPTION', 'PRODUCTION', 'WASTE',
  'TRANSFER_IN', 'TRANSFER_OUT', 'MANUAL_ADJUSTMENT', 'PHYSICAL_VARIANCE', 'RETURN_TO_VENDOR', 'CORRECTION'
);

create table public.inventory_transactions (
  id                  bigint generated always as identity primary key,
  txn_uid             uuid not null unique default gen_random_uuid(),
  organization_id     uuid not null references public.organizations(id),
  location_id         uuid not null references public.locations(id),
  product_id          uuid not null references public.products(id),
  storage_location_id uuid references public.storage_locations(id),
  txn_type            public.inv_txn_type not null,
  quantity            numeric(18,4) not null check (quantity <> 0),   -- inventory units, signed
  unit_cost           numeric(18,6) not null default 0 check (unit_cost >= 0),
  extended_cost       numeric(18,4) generated always as (round(quantity * unit_cost, 4)) stored,
  txn_at              timestamptz not null,                           -- when it happened (business time)
  business_date       date not null,
  source_type         text,                                           -- e.g. receipt, count_session, waste
  source_id           uuid,
  source_line_id      uuid,
  reason_code         text,
  reference           text,
  notes               text,
  lot_id              uuid,
  created_by          uuid references public.profiles(id),
  created_at          timestamptz not null default now(),
  check (case txn_type
           when 'RECEIPT'          then quantity > 0
           when 'TRANSFER_IN'      then quantity > 0
           when 'PRODUCTION'       then quantity > 0
           when 'TRANSFER_OUT'     then quantity < 0
           when 'WASTE'            then quantity < 0
           when 'RETURN_TO_VENDOR' then quantity < 0
           else true end)
);
create index inv_txn_loc_prod_at on public.inventory_transactions (location_id, product_id, txn_at);
create index inv_txn_loc_date on public.inventory_transactions (location_id, business_date, txn_type);
create index inv_txn_source on public.inventory_transactions (source_type, source_id);
create trigger trg_inv_txn_immutable before update or delete on public.inventory_transactions
  for each row execute function app.prevent_mutation();

-- Cached perpetual balance (derived from the ledger; never edited directly).
create table public.inventory_balances (
  location_id  uuid not null references public.locations(id) on delete cascade,
  product_id   uuid not null references public.products(id) on delete cascade,
  organization_id uuid not null references public.organizations(id) on delete cascade,
  on_hand      numeric(18,4) not null default 0,
  last_txn_at  timestamptz,
  updated_at   timestamptz not null default now(),
  primary key (location_id, product_id)
);

create or replace function app.inventory_txn_apply() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.inventory_balances as b (location_id, product_id, organization_id, on_hand, last_txn_at)
  values (new.location_id, new.product_id, new.organization_id, new.quantity, new.txn_at)
  on conflict (location_id, product_id) do update
    set on_hand = b.on_hand + excluded.on_hand,
        last_txn_at = greatest(b.last_txn_at, excluded.last_txn_at),
        updated_at = now();
  return null;
end $$;
create trigger trg_inv_txn_apply after insert on public.inventory_transactions
  for each row execute function app.inventory_txn_apply();

-- The only way rows enter the ledger.
create or replace function app.post_inventory_txn(
  p_location uuid, p_product uuid, p_type public.inv_txn_type, p_qty numeric, p_unit_cost numeric,
  p_txn_at timestamptz, p_source_type text, p_source_id uuid, p_source_line_id uuid default null,
  p_storage uuid default null, p_reason text default null, p_reference text default null,
  p_notes text default null, p_lot uuid default null
) returns bigint
language plpgsql security definer set search_path = public as $$
declare
  v_id bigint;
  v_org uuid := app.location_org(p_location);
begin
  if p_qty is null or p_qty = 0 then return null; end if;
  if not exists (select 1 from public.products where id = p_product and organization_id = v_org) then
    raise exception 'Product does not belong to this organization';
  end if;
  insert into public.inventory_transactions (organization_id, location_id, product_id, storage_location_id, txn_type,
    quantity, unit_cost, txn_at, business_date, source_type, source_id, source_line_id, reason_code, reference, notes, lot_id, created_by)
  values (v_org, p_location, p_product, p_storage, p_type, round(p_qty, 4), round(greatest(coalesce(p_unit_cost, 0), 0), 6),
    p_txn_at, app.business_date(p_location, p_txn_at), p_source_type, p_source_id, p_source_line_id, p_reason, p_reference, p_notes, p_lot, auth.uid())
  returning id into v_id;
  return v_id;
end $$;

-- Book (perpetual) quantity at a point in time, computed from the ledger.
create or replace function app.book_qty(p_location uuid, p_product uuid, p_at timestamptz) returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce(sum(quantity), 0) from public.inventory_transactions
  where location_id = p_location and product_id = p_product and txn_at <= p_at
$$;

-- Current cost per inventory unit (weighted average, falling back to last / standard cost).
create or replace function app.current_unit_cost(p_location uuid, p_product uuid) returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce(nullif(lp.avg_cost, 0), lp.last_cost, p.standard_cost, 0)
  from public.products p
  left join public.location_products lp on lp.product_id = p.id and lp.location_id = p_location
  where p.id = p_product
$$;

-- ---------------------------------------------------------------------
-- Adjustment reasons & manual adjustments
-- ---------------------------------------------------------------------
create table public.adjustment_reasons (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  code            text not null,
  name            text not null,
  kind            text not null check (kind in ('waste', 'adjustment')),
  requires_comment boolean not null default false,
  sort            integer not null default 0,
  active          boolean not null default true,
  created_at      timestamptz not null default now(),
  unique (organization_id, kind, code)
);

create or replace function app.provision_organization(p_org uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  insert into public.adjustment_reasons (organization_id, code, name, kind, requires_comment, sort) values
    (p_org, 'SPOILAGE',        'Spoilage',              'waste', false, 1),
    (p_org, 'EXPIRED',         'Expired',               'waste', false, 2),
    (p_org, 'DROPPED',         'Dropped',               'waste', false, 3),
    (p_org, 'OVERCOOKED',      'Overcooked',            'waste', false, 4),
    (p_org, 'INCORRECT_PREP',  'Incorrect Preparation', 'waste', false, 5),
    (p_org, 'CUSTOMER_RETURN', 'Customer Return',       'waste', false, 6),
    (p_org, 'DAMAGED',         'Damaged',               'waste', false, 7),
    (p_org, 'QUALITY',         'Quality Failure',       'waste', false, 8),
    (p_org, 'PREP_WASTE',      'Prep Waste',            'waste', false, 9),
    (p_org, 'EQUIPMENT',       'Equipment Failure',     'waste', false, 10),
    (p_org, 'UNKNOWN',         'Unknown',               'waste', false, 11),
    (p_org, 'OTHER',           'Other',                 'waste', true,  12),
    (p_org, 'BREAKAGE',        'Breakage',              'adjustment', false, 1),
    (p_org, 'SPOILAGE',        'Spoilage',              'adjustment', false, 2),
    (p_org, 'CORRECTION',      'Correction',            'adjustment', true,  3),
    (p_org, 'MISSING',         'Missing',               'adjustment', true,  4),
    (p_org, 'DONATION',        'Donation',              'adjustment', false, 5),
    (p_org, 'MANAGER_MEAL',    'Manager Meal',          'adjustment', false, 6),
    (p_org, 'EMPLOYEE_MEAL',   'Employee Meal',         'adjustment', false, 7),
    (p_org, 'PROMOTION',       'Promotion',             'adjustment', false, 8),
    (p_org, 'TRANSFER_ERROR',  'Transfer Error',        'adjustment', true,  9),
    (p_org, 'PRODUCTION_DIFF', 'Production Difference', 'adjustment', false, 10),
    (p_org, 'OTHER',           'Other',                 'adjustment', true,  11)
  on conflict do nothing;
end $$;

-- Manual adjustment: records original qty, adjustment, new qty; never silent.
create or replace function public.adjust_inventory(
  p_location uuid, p_product uuid, p_qty numeric, p_unit uuid, p_reason_code text,
  p_comment text default null, p_storage uuid default null, p_idempotency_key uuid default null
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_org uuid := app.location_org(p_location);
  v_reason public.adjustment_reasons;
  v_base numeric;
  v_before numeric;
  v_cost numeric;
  v_txn bigint;
begin
  perform app.require_permission('inventory.adjust', p_location);
  if p_idempotency_key is not null and exists (select 1 from public.inventory_transactions where source_type = 'adjustment' and source_id = p_idempotency_key) then
    return jsonb_build_object('duplicate', true);
  end if;
  select * into v_reason from public.adjustment_reasons where organization_id = v_org and kind = 'adjustment' and code = p_reason_code and active;
  if v_reason.id is null then raise exception 'Unknown adjustment reason %', p_reason_code; end if;
  if v_reason.requires_comment and coalesce(btrim(p_comment), '') = '' then
    raise exception 'A comment is required for reason "%"', v_reason.name;
  end if;
  v_base := app.to_base_qty(p_product, p_qty, p_unit);
  if v_base = 0 then raise exception 'Adjustment quantity cannot be zero'; end if;
  perform 1 from public.location_products where location_id = p_location and product_id = p_product for update;
  select coalesce(on_hand, 0) into v_before from public.inventory_balances where location_id = p_location and product_id = p_product;
  v_before := coalesce(v_before, 0);
  v_cost := app.current_unit_cost(p_location, p_product);
  v_txn := app.post_inventory_txn(p_location, p_product, 'MANUAL_ADJUSTMENT', v_base, v_cost, now(), 'adjustment',
                                  coalesce(p_idempotency_key, gen_random_uuid()), null, p_storage, p_reason_code, null, p_comment);
  perform app.audit(v_org, p_location, 'adjust', 'inventory', p_product::text,
    format('Adjusted %s by %s (%s)', (select name from public.products where id = p_product), v_base, v_reason.name),
    jsonb_build_object('on_hand', v_before),
    jsonb_build_object('on_hand', v_before + v_base, 'adjustment', v_base, 'reason', p_reason_code, 'comment', p_comment, 'txn_id', v_txn));
  return jsonb_build_object('txn_id', v_txn, 'original_qty', v_before, 'adjustment', v_base, 'new_qty', v_before + v_base);
end $$;

-- ---------------------------------------------------------------------
-- RLS
-- ---------------------------------------------------------------------
alter table public.vendors                enable row level security;
alter table public.location_vendors       enable row level security;
alter table public.vendor_products        enable row level security;
alter table public.price_history          enable row level security;
alter table public.inventory_transactions enable row level security;
alter table public.inventory_balances     enable row level security;
alter table public.adjustment_reasons     enable row level security;

create policy vendors_select on public.vendors for select to authenticated
  using (organization_id in (select app.user_org_ids()));
create policy vendors_insert on public.vendors for insert to authenticated
  with check (app.has_org_permission('vendors.edit', organization_id));
create policy vendors_update on public.vendors for update to authenticated
  using (app.has_org_permission('vendors.edit', organization_id))
  with check (app.has_org_permission('vendors.edit', organization_id));

create policy location_vendors_select on public.location_vendors for select to authenticated
  using (location_id in (select app.user_location_ids()));
create policy location_vendors_write on public.location_vendors for all to authenticated
  using (app.has_permission('products.local_edit', location_id))
  with check (app.has_permission('products.local_edit', location_id) and organization_id = app.location_org(location_id));

create policy vendor_products_select on public.vendor_products for select to authenticated
  using (organization_id in (select app.user_org_ids()));
create policy vendor_products_insert on public.vendor_products for insert to authenticated
  with check (app.has_org_permission('vendors.edit', organization_id)
              and organization_id = (select organization_id from public.vendors where id = vendor_id)
              and organization_id = (select organization_id from public.products where id = product_id));
create policy vendor_products_update on public.vendor_products for update to authenticated
  using (app.has_org_permission('vendors.edit', organization_id))
  with check (app.has_org_permission('vendors.edit', organization_id));

create policy price_history_select on public.price_history for select to authenticated
  using (organization_id in (select app.user_org_ids())
         and (location_id is null or location_id in (select app.user_location_ids())));

create policy inv_txn_select on public.inventory_transactions for select to authenticated
  using (location_id in (select app.user_location_ids()));
create policy inv_bal_select on public.inventory_balances for select to authenticated
  using (location_id in (select app.user_location_ids()));

create policy reasons_select on public.adjustment_reasons for select to authenticated
  using (organization_id in (select app.user_org_ids()));
create policy reasons_write on public.adjustment_reasons for all to authenticated
  using (app.has_org_permission('settings.manage', organization_id))
  with check (app.has_org_permission('settings.manage', organization_id));

-- Ledger, balances and price history are written only by SECURITY DEFINER functions.
insert into app.write_protected_tables values ('inventory_transactions'), ('inventory_balances'), ('price_history');

-- ---------------------------------------------------------------------
-- Current inventory view (what do we have, what is it worth)
-- ---------------------------------------------------------------------
create or replace view public.current_inventory with (security_invoker = true) as
select
  lp.location_id, lp.organization_id, p.id as product_id, p.product_number, p.name as product_name,
  p.category_id, c.name as category_name, u.code as inventory_unit,
  coalesce(b.on_hand, 0) as on_hand,
  app.current_unit_cost(lp.location_id, p.id) as unit_cost,
  round(coalesce(b.on_hand, 0) * app.current_unit_cost(lp.location_id, p.id), 2) as extended_value,
  lp.par_mode, lp.par_qty, lp.min_qty, lp.reorder_point, lp.dynamic_par_qty,
  case when lp.par_mode = 'dynamic' then coalesce(lp.dynamic_par_qty, lp.par_qty) when lp.par_mode = 'static' then lp.par_qty end as effective_par,
  lp.avg_cost, lp.last_cost, lp.last_counted_at, b.last_txn_at,
  case
    when coalesce(b.on_hand, 0) < 0 then 'negative'
    when coalesce(b.on_hand, 0) = 0 then 'out'
    when lp.min_qty is not null and b.on_hand <= lp.min_qty then 'critical'
    when coalesce(lp.reorder_point, case when lp.par_mode = 'dynamic' then coalesce(lp.dynamic_par_qty, lp.par_qty) else lp.par_qty end * 0.5) is not null
         and b.on_hand <= coalesce(lp.reorder_point, case when lp.par_mode = 'dynamic' then coalesce(lp.dynamic_par_qty, lp.par_qty) else lp.par_qty end * 0.5) then 'low'
    else 'ok' end as stock_status,
  p.active and lp.active as active,
  p.category_id is not null as categorized
from public.location_products lp
join public.products p on p.id = lp.product_id and p.deleted_at is null
join public.units u on u.id = p.inventory_unit_id
left join public.categories c on c.id = p.category_id
left join public.inventory_balances b on b.location_id = lp.location_id and b.product_id = lp.product_id;

-- Grants (see app.apply_grants in the foundation migration)
select app.apply_grants();

-- ============================================================================
-- 20260930000400_counts.sql
-- ============================================================================
-- =====================================================================
-- PHYSICAL INVENTORY: count sessions, shelf-to-sheet snapshots,
-- multi-counter entries with revision history, review, recount, posting.
-- =====================================================================

-- Immutable, human-readable document numbers (PO-000123, CNT-000045 ...)
create table public.doc_sequences (
  organization_id uuid not null references public.organizations(id) on delete cascade,
  doc_type        text not null,
  last_value      bigint not null default 0,
  primary key (organization_id, doc_type)
);
insert into app.write_protected_tables values ('doc_sequences');

create or replace function app.next_doc_number(p_org uuid, p_doc_type text) returns text
language plpgsql security definer set search_path = public as $$
declare v bigint;
begin
  insert into public.doc_sequences as d (organization_id, doc_type, last_value) values (p_org, p_doc_type, 1)
  on conflict (organization_id, doc_type) do update set last_value = d.last_value + 1
  returning last_value into v;
  return p_doc_type || '-' || lpad(v::text, 6, '0');
end $$;

create type public.count_type as enum ('daily', 'weekly', 'month_end', 'cycle', 'custom', 'storage', 'category', 'full');
create type public.count_status as enum ('not_started', 'in_progress', 'awaiting_review', 'reviewed', 'posted', 'cancelled');

create table public.count_sessions (
  id                   uuid primary key default gen_random_uuid(),
  organization_id      uuid not null references public.organizations(id),
  location_id          uuid not null references public.locations(id),
  count_number         text not null,
  name                 text not null,
  count_type           public.count_type not null,
  status               public.count_status not null default 'not_started',
  count_at             timestamptz not null,   -- book inventory is compared as of this moment
  business_date        date not null,
  storage_location_ids uuid[],
  category_ids         uuid[],
  zero_uncounted       boolean not null default false, -- uncounted sheet items post as zero
  client_key           uuid unique,                     -- idempotent creation
  notes                text,
  created_by           uuid references public.profiles(id),
  created_at           timestamptz not null default now(),
  started_at           timestamptz,
  submitted_at         timestamptz,
  submitted_by         uuid references public.profiles(id),
  reviewed_at          timestamptz,
  reviewed_by          uuid references public.profiles(id),
  posted_at            timestamptz,
  posted_by            uuid references public.profiles(id),
  cancelled_at         timestamptz,
  cancelled_by         uuid references public.profiles(id),
  cancel_reason        text,
  updated_at           timestamptz not null default now(),
  unique (organization_id, count_number)
);
create index on public.count_sessions (location_id, status, count_at desc);
create trigger trg_count_sessions_touch before update on public.count_sessions for each row execute function app.touch_updated_at();

-- Frozen count sheet (shelf-to-sheet order at the time the count was created).
create table public.count_session_items (
  id                  uuid primary key default gen_random_uuid(),
  session_id          uuid not null references public.count_sessions(id) on delete cascade,
  product_id          uuid not null references public.products(id),
  storage_location_id uuid references public.storage_locations(id),
  shelf               text,
  sort_order          integer not null default 0,
  added_during_count  boolean not null default false,
  unique nulls not distinct (session_id, product_id, storage_location_id)
);
create index on public.count_session_items (session_id, storage_location_id, sort_order);

create table public.count_assignments (
  id                  uuid primary key default gen_random_uuid(),
  session_id          uuid not null references public.count_sessions(id) on delete cascade,
  user_id             uuid not null references public.profiles(id),
  storage_location_id uuid references public.storage_locations(id),
  created_at          timestamptz not null default now(),
  unique nulls not distinct (session_id, user_id, storage_location_id)
);

create table public.count_entries (
  id                   uuid primary key default gen_random_uuid(),
  organization_id      uuid not null references public.organizations(id),
  location_id          uuid not null references public.locations(id),
  session_id           uuid not null references public.count_sessions(id) on delete cascade,
  product_id           uuid not null references public.products(id),
  storage_location_id  uuid references public.storage_locations(id),
  quantity             numeric(18,4) not null check (quantity >= 0),  -- inventory units, computed server-side
  breakdown            jsonb not null default '[]'::jsonb,            -- [{unit_id, unit_code, qty}]
  method               text not null default 'keypad' check (method in ('keypad','plus_minus','barcode','voice','calculator','manual','import')),
  voice_transcript     text,
  voice_confidence     numeric(5,4) check (voice_confidence is null or voice_confidence between 0 and 1),
  counted_by           uuid references public.profiles(id),
  counted_at           timestamptz not null default now(),
  device_id            text,
  revision             integer not null default 1,
  has_conflict         boolean not null default false,
  recount_requested    boolean not null default false,
  recount_requested_by uuid references public.profiles(id),
  recount_requested_at timestamptz,
  recounted            boolean not null default false,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  unique nulls not distinct (session_id, product_id, storage_location_id)
);
create index on public.count_entries (session_id);
create index on public.count_entries (location_id, product_id);

-- Every value ever submitted, including rejected conflicting writes. Append-only.
create table public.count_entry_revisions (
  id                  bigint generated always as identity primary key,
  entry_id            uuid not null,
  session_id          uuid not null references public.count_sessions(id) on delete cascade,
  product_id          uuid not null references public.products(id),
  storage_location_id uuid references public.storage_locations(id),
  revision            integer not null,
  status              text not null check (status in ('applied', 'conflict', 'resolution', 'cleared')),
  quantity            numeric(18,4),
  breakdown           jsonb,
  method              text,
  voice_transcript    text,
  voice_confidence    numeric(5,4),
  counted_by          uuid references public.profiles(id),
  counted_at          timestamptz,
  device_id           text,
  client_entry_id     uuid unique,
  note                text,
  created_at          timestamptz not null default now()
);
create index on public.count_entry_revisions (entry_id, id);
create index on public.count_entry_revisions (session_id);
create trigger trg_count_rev_immutable before update or delete on public.count_entry_revisions
  for each row execute function app.prevent_mutation();

-- Snapshot of the review at posting time (reproducible variance history). Append-only.
create table public.count_posting_lines (
  session_id        uuid not null references public.count_sessions(id),
  product_id        uuid not null references public.products(id),
  counted           boolean not null,
  begin_qty         numeric(18,4) not null,
  received_qty      numeric(18,4) not null,
  transfer_in_qty   numeric(18,4) not null,
  transfer_out_qty  numeric(18,4) not null,
  produced_qty      numeric(18,4) not null,
  consumed_qty      numeric(18,4) not null,
  waste_qty         numeric(18,4) not null,
  adjusted_qty      numeric(18,4) not null,
  book_qty          numeric(18,4) not null,
  physical_qty      numeric(18,4) not null,
  variance_qty      numeric(18,4) not null,
  unit_cost         numeric(18,6) not null,
  variance_value    numeric(18,4) not null,
  txn_id            bigint references public.inventory_transactions(id),
  created_at        timestamptz not null default now(),
  primary key (session_id, product_id)
);
create trigger trg_count_posting_immutable before update or delete on public.count_posting_lines
  for each row execute function app.prevent_mutation();

insert into app.write_protected_tables values
  ('count_sessions'), ('count_session_items'), ('count_entries'), ('count_entry_revisions'), ('count_posting_lines');

-- ---------------------------------------------------------------------
-- RLS (all writes go through the functions below)
-- ---------------------------------------------------------------------
alter table public.count_sessions        enable row level security;
alter table public.count_session_items   enable row level security;
alter table public.count_assignments     enable row level security;
alter table public.count_entries         enable row level security;
alter table public.count_entry_revisions enable row level security;
alter table public.count_posting_lines   enable row level security;
alter table public.doc_sequences         enable row level security;

create policy cs_select on public.count_sessions for select to authenticated
  using (location_id in (select app.user_location_ids()));
create policy csi_select on public.count_session_items for select to authenticated
  using (session_id in (select id from public.count_sessions));
create policy ca_select on public.count_assignments for select to authenticated
  using (session_id in (select id from public.count_sessions));
create policy ca_write on public.count_assignments for all to authenticated
  using (exists (select 1 from public.count_sessions s where s.id = session_id and app.has_permission('inventory.review', s.location_id)))
  with check (exists (select 1 from public.count_sessions s where s.id = session_id and app.has_permission('inventory.review', s.location_id)));
create policy ce_select on public.count_entries for select to authenticated
  using (location_id in (select app.user_location_ids()));
create policy cer_select on public.count_entry_revisions for select to authenticated
  using (session_id in (select id from public.count_sessions));
create policy cpl_select on public.count_posting_lines for select to authenticated
  using (session_id in (select id from public.count_sessions));

-- ---------------------------------------------------------------------
-- Create a count (builds the frozen sheet in shelf-to-sheet order)
-- ---------------------------------------------------------------------
create or replace function public.create_count_session(
  p_location uuid, p_count_type public.count_type, p_name text default null,
  p_count_at timestamptz default null, p_storage_ids uuid[] default null, p_category_ids uuid[] default null,
  p_client_key uuid default null, p_notes text default null
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_org uuid := app.location_org(p_location);
  v_id uuid;
  v_at timestamptz := coalesce(p_count_at, now());
  v_items integer;
  v_all_items boolean := p_count_type in ('full', 'month_end', 'weekly', 'custom', 'category', 'storage', 'cycle');
begin
  perform app.require_permission('inventory.count', p_location);
  if p_client_key is not null then
    select id into v_id from public.count_sessions where client_key = p_client_key;
    if v_id is not null then return v_id; end if;
  end if;
  if p_count_type in ('storage') and coalesce(array_length(p_storage_ids, 1), 0) = 0 then
    raise exception 'Select at least one storage area for a location count';
  end if;
  if p_count_type in ('category') and coalesce(array_length(p_category_ids, 1), 0) = 0 then
    raise exception 'Select at least one category for a category count';
  end if;
  if v_at > now() + interval '1 day' then
    raise exception 'Count time cannot be in the future';
  end if;

  insert into public.count_sessions (organization_id, location_id, count_number, name, count_type, count_at, business_date,
                                     storage_location_ids, category_ids, zero_uncounted, client_key, notes, created_by)
  values (v_org, p_location, app.next_doc_number(v_org, 'CNT'),
          coalesce(nullif(btrim(p_name), ''), initcap(replace(p_count_type::text, '_', ' ')) || ' Count ' || to_char(app.business_date(p_location, v_at), 'Mon DD')),
          p_count_type, v_at, app.business_date(p_location, v_at), p_storage_ids, p_category_ids,
          p_count_type in ('full', 'month_end', 'weekly'), p_client_key, p_notes, auth.uid())
  returning id into v_id;

  -- Category filter matches the category or any of its descendants.
  with recursive cats as (
    select id from public.categories where id = any(coalesce(p_category_ids, '{}'))
    union all
    select c.id from public.categories c join cats on c.parent_id = cats.id
  ),
  eligible as (
    select lp.product_id
    from public.location_products lp
    join public.products p on p.id = lp.product_id and p.active and p.deleted_at is null
    where lp.location_id = p_location and lp.active
      and (p_count_type <> 'daily' or lp.count_daily)
      and (p_count_type <> 'weekly' or lp.count_weekly or lp.count_daily)
      and (p_category_ids is null or p.category_id in (select id from cats))
  )
  insert into public.count_session_items (session_id, product_id, storage_location_id, shelf, sort_order)
  select v_id, e.product_id, psl.storage_location_id, psl.shelf, psl.sort_order
  from eligible e
  join public.product_storage_locations psl on psl.product_id = e.product_id and psl.location_id = p_location and psl.active
  join public.storage_locations s on s.id = psl.storage_location_id and s.active
  where p_storage_ids is null or psl.storage_location_id = any(p_storage_ids);

  -- Products without a storage assignment still get counted (grouped as "Unassigned").
  if p_storage_ids is null then
    insert into public.count_session_items (session_id, product_id, storage_location_id, sort_order)
    select v_id, e.product_id, null, 0
    from (
      select lp.product_id from public.location_products lp
      join public.products p on p.id = lp.product_id and p.active and p.deleted_at is null
      where lp.location_id = p_location and lp.active
        and (p_count_type <> 'daily' or lp.count_daily)
        and (p_count_type <> 'weekly' or lp.count_weekly or lp.count_daily)
        and (p_category_ids is null or p.category_id in (
              with recursive c2 as (select id from public.categories where id = any(p_category_ids)
                                    union all select c.id from public.categories c join c2 on c.parent_id = c2.id)
              select id from c2))
    ) e
    where not exists (select 1 from public.count_session_items i where i.session_id = v_id and i.product_id = e.product_id);
  end if;

  select count(*) into v_items from public.count_session_items where session_id = v_id;
  if v_items = 0 then
    raise exception 'No items match this count. Check storage areas, categories and which items are on the % count list.', p_count_type;
  end if;

  perform app.audit(v_org, p_location, 'create', 'count_session', v_id::text,
                    format('Created %s count with %s lines', p_count_type, v_items), null,
                    jsonb_build_object('count_type', p_count_type, 'count_at', v_at, 'items', v_items));
  return v_id;
end $$;

-- ---------------------------------------------------------------------
-- Count sheet for the counting screen / offline download (one round trip)
-- Book quantities are intentionally NOT included (blind count).
-- ---------------------------------------------------------------------
create or replace function public.get_count_sheet(p_session uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_s public.count_sessions;
begin
  select * into v_s from public.count_sessions where id = p_session;
  if v_s.id is null or not (v_s.location_id in (select app.user_location_ids())) then
    raise exception 'Count not found' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'session', to_jsonb(v_s) || jsonb_build_object('location_name', (select name from public.locations where id = v_s.location_id)),
    'storages', coalesce((
      select jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name, 'kind', s.kind, 'sort_order', s.sort_order) order by s.sort_order, s.name)
      from public.storage_locations s
      where s.id in (select storage_location_id from public.count_session_items where session_id = p_session)), '[]'::jsonb),
    'lines', coalesce((
      select jsonb_agg(jsonb_build_object(
        'item_id', i.id, 'product_id', p.id, 'product_number', p.product_number, 'name', p.name,
        'category', c.name, 'storage_location_id', i.storage_location_id, 'shelf', i.shelf, 'sort_order', i.sort_order,
        'inventory_unit_id', p.inventory_unit_id,
        'units', (select jsonb_agg(jsonb_build_object('unit_id', o.unit_id, 'code', o.unit_code, 'name', o.unit_name, 'factor', o.factor)
                                   order by o.factor desc)
                  from public.product_unit_options o
                  where o.product_id = p.id and (o.is_inventory_unit or o.use_for_count)),
        'barcodes', (select coalesce(jsonb_agg(jsonb_build_object('barcode', b.barcode, 'unit_id', b.unit_id)), '[]'::jsonb)
                     from public.product_barcodes b where b.product_id = p.id)
      ) order by coalesce(st.sort_order, 999999), st.name, i.sort_order, p.name)
      from public.count_session_items i
      join public.products p on p.id = i.product_id
      left join public.categories c on c.id = p.category_id
      left join public.storage_locations st on st.id = i.storage_location_id
      where i.session_id = p_session), '[]'::jsonb),
    'entries', coalesce((
      select jsonb_agg(to_jsonb(e) || jsonb_build_object('counted_by_name', pr.full_name))
      from public.count_entries e left join public.profiles pr on pr.id = e.counted_by
      where e.session_id = p_session), '[]'::jsonb),
    'server_time', now()
  );
end $$;

-- ---------------------------------------------------------------------
-- Save count entries (batch, idempotent, conflict-safe; used by offline sync)
-- p_entries: [{client_entry_id, product_id, storage_location_id, breakdown:[{unit_id, qty}],
--              base_revision, method, voice_transcript, voice_confidence, counted_at, device_id, clear}]
-- ---------------------------------------------------------------------
create or replace function public.save_count_entries(p_session uuid, p_entries jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_s public.count_sessions;
  v_uid uuid := auth.uid();
  v_can_review boolean;
  r jsonb;
  b jsonb;
  v_client uuid;
  v_product uuid;
  v_storage uuid;
  v_qty numeric;
  v_factor numeric;
  v_breakdown jsonb;
  v_entry public.count_entries;
  v_base_rev integer;
  v_status text;
  v_results jsonb := '[]'::jsonb;
  v_counted_at timestamptz;
begin
  select * into v_s from public.count_sessions where id = p_session for update;
  if v_s.id is null then raise exception 'Count not found'; end if;
  perform app.require_permission('inventory.count', v_s.location_id);
  if v_s.status in ('posted', 'cancelled', 'reviewed') then
    raise exception 'This count is % and can no longer be changed', v_s.status using errcode = 'P0002';
  end if;
  v_can_review := app.has_permission('inventory.review', v_s.location_id);
  if v_s.status = 'not_started' then
    update public.count_sessions set status = 'in_progress', started_at = now() where id = p_session;
  end if;

  for r in select * from jsonb_array_elements(p_entries) loop
    v_client := (r ->> 'client_entry_id')::uuid;
    v_product := (r ->> 'product_id')::uuid;
    v_storage := nullif(r ->> 'storage_location_id', '')::uuid;
    v_base_rev := nullif(r ->> 'base_revision', '')::integer;
    v_counted_at := least(coalesce(nullif(r ->> 'counted_at', '')::timestamptz, now()), now());

    -- Idempotency: this exact submission was already processed.
    if v_client is not null and exists (select 1 from public.count_entry_revisions where client_entry_id = v_client) then
      select * into v_entry from public.count_entries where session_id = p_session and product_id = v_product and storage_location_id is not distinct from v_storage;
      v_results := v_results || jsonb_build_object('client_entry_id', v_client, 'status', 'duplicate', 'entry', to_jsonb(v_entry));
      continue;
    end if;

    -- Product must be active at this location. Items found during the count are added to the sheet.
    if not exists (select 1 from public.location_products lp where lp.location_id = v_s.location_id and lp.product_id = v_product) then
      raise exception 'Product is not carried at this location';
    end if;
    if v_storage is not null and not exists (select 1 from public.storage_locations where id = v_storage and location_id = v_s.location_id) then
      raise exception 'Storage area does not belong to this location';
    end if;
    insert into public.count_session_items (session_id, product_id, storage_location_id, sort_order, added_during_count)
    values (p_session, v_product, v_storage, 100000, true)
    on conflict (session_id, product_id, storage_location_id) do nothing;

    select * into v_entry from public.count_entries
     where session_id = p_session and product_id = v_product and storage_location_id is not distinct from v_storage
     for update;

    if v_s.status = 'awaiting_review' and not v_can_review and not coalesce(v_entry.recount_requested, false) then
      raise exception 'The count was submitted for review. Only items marked for recount can be changed.' using errcode = 'P0002';
    end if;

    -- Clearing an entry
    if coalesce((r ->> 'clear')::boolean, false) then
      if v_entry.id is not null then
        if v_base_rev is not null and v_base_rev <> v_entry.revision and v_entry.counted_by is distinct from v_uid then
          insert into public.count_entry_revisions (entry_id, session_id, product_id, storage_location_id, revision, status, quantity, breakdown,
                                                    counted_by, counted_at, device_id, client_entry_id, note)
          values (v_entry.id, p_session, v_product, v_storage, v_entry.revision, 'conflict', null, '[]', v_uid, v_counted_at, r ->> 'device_id', v_client,
                  'Clear rejected: another counter changed this item');
          update public.count_entries set has_conflict = true where id = v_entry.id returning * into v_entry;
          v_results := v_results || jsonb_build_object('client_entry_id', v_client, 'status', 'conflict', 'entry', to_jsonb(v_entry));
        else
          insert into public.count_entry_revisions (entry_id, session_id, product_id, storage_location_id, revision, status, quantity, breakdown,
                                                    counted_by, counted_at, device_id, client_entry_id)
          values (v_entry.id, p_session, v_product, v_storage, v_entry.revision + 1, 'cleared', null, '[]', v_uid, v_counted_at, r ->> 'device_id', v_client);
          delete from public.count_entries where id = v_entry.id;
          v_results := v_results || jsonb_build_object('client_entry_id', v_client, 'status', 'cleared', 'entry', null);
        end if;
      else
        v_results := v_results || jsonb_build_object('client_entry_id', v_client, 'status', 'cleared', 'entry', null);
      end if;
      continue;
    end if;

    -- Quantity is always computed on the server from the unit breakdown.
    v_qty := 0;
    v_breakdown := '[]'::jsonb;
    for b in select * from jsonb_array_elements(coalesce(r -> 'breakdown', '[]'::jsonb)) loop
      continue when nullif(b ->> 'qty', '') is null;
      if (b ->> 'qty')::numeric < 0 then raise exception 'Counts cannot be negative'; end if;
      v_factor := app.unit_factor(v_product, (b ->> 'unit_id')::uuid);
      if v_factor is null then raise exception 'Unit has no conversion for this product' using errcode = '22023'; end if;
      v_qty := v_qty + (b ->> 'qty')::numeric * v_factor;
      v_breakdown := v_breakdown || jsonb_build_object('unit_id', b ->> 'unit_id',
                                                       'unit_code', (select code from public.units where id = (b ->> 'unit_id')::uuid),
                                                       'qty', (b ->> 'qty')::numeric);
    end loop;
    v_qty := round(v_qty, 4);
    if jsonb_array_length(v_breakdown) = 0 then raise exception 'Enter a quantity (0 is allowed)'; end if;

    if v_entry.id is null then
      insert into public.count_entries (organization_id, location_id, session_id, product_id, storage_location_id, quantity, breakdown,
                                        method, voice_transcript, voice_confidence, counted_by, counted_at, device_id, revision)
      values (v_s.organization_id, v_s.location_id, p_session, v_product, v_storage, v_qty, v_breakdown,
              coalesce(r ->> 'method', 'keypad'), r ->> 'voice_transcript', nullif(r ->> 'voice_confidence', '')::numeric,
              v_uid, v_counted_at, r ->> 'device_id', 1)
      returning * into v_entry;
      v_status := 'applied';
    elsif v_base_rev is not null and v_base_rev <> v_entry.revision and v_entry.counted_by is distinct from v_uid then
      -- Someone else changed this line since this device last saw it: keep both, flag for review.
      v_status := 'conflict';
    else
      update public.count_entries set
        quantity = v_qty, breakdown = v_breakdown, method = coalesce(r ->> 'method', 'keypad'),
        voice_transcript = r ->> 'voice_transcript', voice_confidence = nullif(r ->> 'voice_confidence', '')::numeric,
        counted_by = v_uid, counted_at = v_counted_at, device_id = r ->> 'device_id',
        revision = v_entry.revision + 1,
        recounted = v_entry.recounted or v_entry.recount_requested,
        recount_requested = false,
        updated_at = now()
      where id = v_entry.id
      returning * into v_entry;
      v_status := 'applied';
    end if;

    insert into public.count_entry_revisions (entry_id, session_id, product_id, storage_location_id, revision, status, quantity, breakdown,
                                              method, voice_transcript, voice_confidence, counted_by, counted_at, device_id, client_entry_id)
    values (v_entry.id, p_session, v_product, v_storage,
            case when v_status = 'applied' then v_entry.revision else v_entry.revision end,
            v_status, v_qty, v_breakdown, coalesce(r ->> 'method', 'keypad'), r ->> 'voice_transcript',
            nullif(r ->> 'voice_confidence', '')::numeric, v_uid, v_counted_at, r ->> 'device_id', v_client);

    if v_status = 'conflict' then
      update public.count_entries set has_conflict = true where id = v_entry.id returning * into v_entry;
    end if;

    v_results := v_results || jsonb_build_object('client_entry_id', v_client, 'status', v_status,
      'entry', to_jsonb(v_entry) || jsonb_build_object('counted_by_name', (select full_name from public.profiles where id = v_entry.counted_by)));
  end loop;

  return jsonb_build_object('results', v_results, 'session_status', (select status from public.count_sessions where id = p_session));
end $$;

-- Reviewer picks which submitted value wins for a conflicted line.
create or replace function public.resolve_count_conflict(p_entry uuid, p_revision_id bigint) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_e public.count_entries;
  v_r public.count_entry_revisions;
  v_status public.count_status;
begin
  select * into v_e from public.count_entries where id = p_entry for update;
  if v_e.id is null then raise exception 'Count line not found'; end if;
  perform app.require_permission('inventory.review', v_e.location_id);
  select status into v_status from public.count_sessions where id = v_e.session_id;
  if v_status in ('posted', 'cancelled') then raise exception 'Count is %', v_status; end if;
  select * into v_r from public.count_entry_revisions where id = p_revision_id and entry_id = p_entry;
  if v_r.id is null or v_r.quantity is null then raise exception 'Revision not found'; end if;
  update public.count_entries set quantity = v_r.quantity, breakdown = v_r.breakdown, method = v_r.method,
    voice_transcript = v_r.voice_transcript, voice_confidence = v_r.voice_confidence,
    counted_by = v_r.counted_by, counted_at = v_r.counted_at, revision = revision + 1, has_conflict = false, updated_at = now()
  where id = p_entry returning * into v_e;
  insert into public.count_entry_revisions (entry_id, session_id, product_id, storage_location_id, revision, status, quantity, breakdown, method,
                                            counted_by, counted_at, note)
  values (p_entry, v_e.session_id, v_e.product_id, v_e.storage_location_id, v_e.revision, 'resolution', v_e.quantity, v_e.breakdown, v_e.method,
          auth.uid(), now(), format('Conflict resolved using revision %s', p_revision_id));
  perform app.audit(v_e.organization_id, v_e.location_id, 'resolve_conflict', 'count_entry', p_entry::text,
                    'Count conflict resolved', null, jsonb_build_object('quantity', v_e.quantity, 'revision_id', p_revision_id));
end $$;

-- ---------------------------------------------------------------------
-- Review: BEGIN + movements = BOOK; PHYSICAL - BOOK = VARIANCE
-- ---------------------------------------------------------------------
create or replace function public.count_review_lines(p_session uuid)
returns table (
  product_id uuid, product_number text, product_name text, category_id uuid, category_name text,
  inventory_unit text, storage_names text,
  counted boolean, entry_count integer, counted_by_names text, has_conflict boolean, recount_requested boolean, recounted boolean,
  begin_qty numeric, received_qty numeric, transfer_in_qty numeric, transfer_out_qty numeric, produced_qty numeric,
  consumed_qty numeric, waste_qty numeric, adjusted_qty numeric, in_transit_qty numeric,
  book_qty numeric, physical_qty numeric, variance_qty numeric, unit_cost numeric, variance_value numeric,
  variance_pct numeric, exceeds_tolerance boolean
)
language plpgsql stable security definer set search_path = public as $$
declare
  v_s public.count_sessions;
  v_loc public.locations;
begin
  select * into v_s from public.count_sessions where id = p_session;
  if v_s.id is null or not (v_s.location_id in (select app.user_location_ids())) then
    raise exception 'Count not found' using errcode = '42501';
  end if;
  select * into v_loc from public.locations where id = v_s.location_id;

  -- Posted counts are reported from their immutable snapshot.
  if v_s.status = 'posted' then
    return query
    select pl.product_id, p.product_number, p.name, p.category_id, c.name, u.code,
           (select string_agg(distinct st.name, ', ') from public.count_entries e join public.storage_locations st on st.id = e.storage_location_id
             where e.session_id = p_session and e.product_id = pl.product_id),
           pl.counted,
           (select count(*)::int from public.count_entries e where e.session_id = p_session and e.product_id = pl.product_id),
           (select string_agg(distinct pr.full_name, ', ') from public.count_entries e join public.profiles pr on pr.id = e.counted_by
             where e.session_id = p_session and e.product_id = pl.product_id),
           false, false,
           coalesce((select bool_or(e.recounted) from public.count_entries e where e.session_id = p_session and e.product_id = pl.product_id), false),
           pl.begin_qty, pl.received_qty, pl.transfer_in_qty, pl.transfer_out_qty, pl.produced_qty, pl.consumed_qty, pl.waste_qty, pl.adjusted_qty,
           0::numeric, pl.book_qty, pl.physical_qty, pl.variance_qty, pl.unit_cost, pl.variance_value,
           case when pl.book_qty <> 0 then round(pl.variance_qty / abs(pl.book_qty) * 100, 2) end,
           (abs(pl.variance_value) > v_loc.count_variance_value_tolerance
             or (pl.book_qty <> 0 and abs(pl.variance_qty / pl.book_qty * 100) > v_loc.count_variance_pct_tolerance))
    from public.count_posting_lines pl
    join public.products p on p.id = pl.product_id
    join public.units u on u.id = p.inventory_unit_id
    left join public.categories c on c.id = p.category_id
    where pl.session_id = p_session;
    return;
  end if;

  return query
  with prods as (
    select i.product_id from public.count_session_items i where i.session_id = p_session
    union
    select e.product_id from public.count_entries e where e.session_id = p_session
  ),
  phys as (
    select e.product_id, sum(e.quantity) as qty, count(*)::int as n,
           bool_or(e.has_conflict) as conflict, bool_or(e.recount_requested) as recount, bool_or(e.recounted) as recounted,
           string_agg(distinct pr.full_name, ', ') as who,
           string_agg(distinct st.name, ', ') as storages
    from public.count_entries e
    left join public.profiles pr on pr.id = e.counted_by
    left join public.storage_locations st on st.id = e.storage_location_id
    where e.session_id = p_session
    group by e.product_id
  ),
  prev as (
    select pl.product_id, max(cs.count_at) as prev_at
    from public.count_posting_lines pl
    join public.count_sessions cs on cs.id = pl.session_id
    where cs.location_id = v_s.location_id and cs.status = 'posted' and pl.counted and cs.count_at < v_s.count_at
    group by pl.product_id
  ),
  mv as (
    select t.product_id,
      coalesce(sum(t.quantity) filter (where t.txn_at <= coalesce(pv.prev_at, '-infinity')), 0) as begin_qty,
      coalesce(sum(t.quantity) filter (where t.txn_at > coalesce(pv.prev_at, '-infinity') and t.txn_type in ('RECEIPT', 'RETURN_TO_VENDOR')), 0) as received,
      coalesce(sum(t.quantity) filter (where t.txn_at > coalesce(pv.prev_at, '-infinity') and t.txn_type = 'TRANSFER_IN'), 0) as t_in,
      coalesce(sum(t.quantity) filter (where t.txn_at > coalesce(pv.prev_at, '-infinity') and t.txn_type = 'TRANSFER_OUT'), 0) as t_out,
      coalesce(sum(t.quantity) filter (where t.txn_at > coalesce(pv.prev_at, '-infinity') and t.txn_type = 'PRODUCTION'), 0) as produced,
      coalesce(sum(t.quantity) filter (where t.txn_at > coalesce(pv.prev_at, '-infinity') and t.txn_type in ('POS_CONSUMPTION', 'RECIPE_CONSUMPTION')), 0) as consumed,
      coalesce(sum(t.quantity) filter (where t.txn_at > coalesce(pv.prev_at, '-infinity') and t.txn_type = 'WASTE'), 0) as waste,
      coalesce(sum(t.quantity) filter (where t.txn_at > coalesce(pv.prev_at, '-infinity') and t.txn_type in ('MANUAL_ADJUSTMENT', 'PHYSICAL_VARIANCE', 'CORRECTION', 'BEGINNING')), 0) as adjusted,
      coalesce(sum(t.quantity), 0) as book
    from public.inventory_transactions t
    join prods using (product_id)
    left join prev pv on pv.product_id = t.product_id
    where t.location_id = v_s.location_id and t.txn_at <= v_s.count_at
    group by t.product_id
  ),
  lines as (
    select pr.product_id,
           (ph.product_id is not null) as counted,
           coalesce(ph.n, 0) as n, ph.who, coalesce(ph.conflict, false) as conflict, coalesce(ph.recount, false) as recount,
           coalesce(ph.recounted, false) as recounted, ph.storages,
           coalesce(mv.begin_qty, 0) as begin_qty, coalesce(mv.received, 0) as received, coalesce(mv.t_in, 0) as t_in,
           coalesce(mv.t_out, 0) as t_out, coalesce(mv.produced, 0) as produced, coalesce(mv.consumed, 0) as consumed,
           coalesce(mv.waste, 0) as waste, coalesce(mv.adjusted, 0) as adjusted, coalesce(mv.book, 0) as book,
           case when ph.product_id is not null then ph.qty when v_s.zero_uncounted then 0 end as physical,
           app.current_unit_cost(v_s.location_id, pr.product_id) as cost
    from prods pr
    left join phys ph on ph.product_id = pr.product_id
    left join mv on mv.product_id = pr.product_id
  )
  select l.product_id, p.product_number, p.name, p.category_id, c.name, u.code, l.storages,
         l.counted, l.n, l.who, l.conflict, l.recount, l.recounted,
         l.begin_qty, l.received, l.t_in, l.t_out, l.produced, l.consumed, l.waste, l.adjusted,
         app.in_transit_qty(v_s.location_id, l.product_id),
         l.book, l.physical,
         case when l.physical is not null then l.physical - l.book end,
         round(l.cost, 6),
         case when l.physical is not null then round((l.physical - l.book) * l.cost, 2) end,
         case when l.physical is not null and l.book <> 0 then round((l.physical - l.book) / abs(l.book) * 100, 2)
              when l.physical is not null and l.book = 0 and l.physical <> 0 then 100 end,
         coalesce(l.physical is not null and (
              abs((l.physical - l.book) * l.cost) > v_loc.count_variance_value_tolerance
           or (l.book <> 0 and abs((l.physical - l.book) / l.book * 100) > v_loc.count_variance_pct_tolerance)
           or (l.book = 0 and l.physical > 0 and l.physical * l.cost > v_loc.count_variance_value_tolerance)), false)
  from lines l
  join public.products p on p.id = l.product_id
  join public.units u on u.id = p.inventory_unit_id
  left join public.categories c on c.id = p.category_id;
end $$;

-- In-transit quantity (inbound location transfers). Redefined once transfers exist.
create or replace function app.in_transit_qty(p_location uuid, p_product uuid) returns numeric
language sql stable as $$ select 0::numeric $$;

-- ---------------------------------------------------------------------
-- Session state transitions
-- ---------------------------------------------------------------------
create or replace function public.submit_count_session(p_session uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_s public.count_sessions;
begin
  select * into v_s from public.count_sessions where id = p_session for update;
  if v_s.id is null then raise exception 'Count not found'; end if;
  perform app.require_permission('inventory.count', v_s.location_id);
  if v_s.status not in ('not_started', 'in_progress') then
    raise exception 'Only a count in progress can be submitted (current status: %)', v_s.status;
  end if;
  if not exists (select 1 from public.count_entries where session_id = p_session) then
    raise exception 'Nothing has been counted yet';
  end if;
  update public.count_sessions set status = 'awaiting_review', submitted_at = now(), submitted_by = auth.uid() where id = p_session;
  perform app.audit(v_s.organization_id, v_s.location_id, 'submit', 'count_session', p_session::text, 'Count submitted for review', null, null);
end $$;

create or replace function public.reopen_count_session(p_session uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_s public.count_sessions;
begin
  select * into v_s from public.count_sessions where id = p_session for update;
  if v_s.id is null then raise exception 'Count not found'; end if;
  perform app.require_permission('inventory.review', v_s.location_id);
  if v_s.status not in ('awaiting_review', 'reviewed') then
    raise exception 'Only a submitted count can be reopened (current status: %)', v_s.status;
  end if;
  update public.count_sessions set status = 'in_progress', reviewed_at = null, reviewed_by = null where id = p_session;
  perform app.audit(v_s.organization_id, v_s.location_id, 'reopen', 'count_session', p_session::text, 'Count reopened for counting', null, null);
end $$;

create or replace function public.request_recount(p_session uuid, p_product_ids uuid[]) returns integer
language plpgsql security definer set search_path = public as $$
declare v_s public.count_sessions; v_n integer;
begin
  select * into v_s from public.count_sessions where id = p_session for update;
  if v_s.id is null then raise exception 'Count not found'; end if;
  perform app.require_permission('inventory.review', v_s.location_id);
  if v_s.status not in ('in_progress', 'awaiting_review', 'reviewed') then
    raise exception 'Recounts can only be requested before posting';
  end if;
  update public.count_entries set recount_requested = true, recount_requested_by = auth.uid(), recount_requested_at = now()
  where session_id = p_session and product_id = any(p_product_ids);
  get diagnostics v_n = row_count;
  if v_s.status = 'reviewed' then
    update public.count_sessions set status = 'awaiting_review', reviewed_at = null, reviewed_by = null where id = p_session;
  end if;
  perform app.audit(v_s.organization_id, v_s.location_id, 'request_recount', 'count_session', p_session::text,
                    format('Recount requested for %s line(s)', v_n), null, to_jsonb(p_product_ids));
  return v_n;
end $$;

create or replace function public.mark_count_reviewed(p_session uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_s public.count_sessions;
begin
  select * into v_s from public.count_sessions where id = p_session for update;
  if v_s.id is null then raise exception 'Count not found'; end if;
  perform app.require_permission('inventory.review', v_s.location_id);
  if v_s.status <> 'awaiting_review' then raise exception 'Count must be awaiting review (current status: %)', v_s.status; end if;
  if exists (select 1 from public.count_entries where session_id = p_session and (has_conflict or recount_requested)) then
    raise exception 'Resolve conflicts and outstanding recounts before marking the count reviewed';
  end if;
  update public.count_sessions set status = 'reviewed', reviewed_at = now(), reviewed_by = auth.uid() where id = p_session;
  perform app.audit(v_s.organization_id, v_s.location_id, 'review', 'count_session', p_session::text, 'Count reviewed', null, null);
end $$;

create or replace function public.cancel_count_session(p_session uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare v_s public.count_sessions;
begin
  select * into v_s from public.count_sessions where id = p_session for update;
  if v_s.id is null then raise exception 'Count not found'; end if;
  perform app.require_permission('inventory.review', v_s.location_id);
  if v_s.status in ('posted', 'cancelled') then raise exception 'Count is already %', v_s.status; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'A reason is required to cancel a count'; end if;
  update public.count_sessions set status = 'cancelled', cancelled_at = now(), cancelled_by = auth.uid(), cancel_reason = p_reason where id = p_session;
  perform app.audit(v_s.organization_id, v_s.location_id, 'cancel', 'count_session', p_session::text, 'Count cancelled: ' || p_reason, null, null);
end $$;

-- ---------------------------------------------------------------------
-- POST: creates PHYSICAL_VARIANCE ledger rows at count_at, snapshots the
-- review, locks the event. Atomic: all or nothing.
-- ---------------------------------------------------------------------
create or replace function public.post_count_session(p_session uuid, p_acknowledge_flags boolean default false) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_s public.count_sessions;
  v_flagged integer;
  v_uncounted integer;
  l record;
  v_txn bigint;
  v_lines integer := 0;
  v_total numeric := 0;
begin
  select * into v_s from public.count_sessions where id = p_session for update;
  if v_s.id is null then raise exception 'Count not found'; end if;
  perform app.require_permission('inventory.post', v_s.location_id);
  if v_s.status = 'posted' then raise exception 'This count has already been posted' using errcode = 'P0003'; end if;
  if v_s.status not in ('awaiting_review', 'reviewed') then
    raise exception 'Submit the count for review before posting (current status: %)', v_s.status;
  end if;
  if exists (select 1 from public.count_entries where session_id = p_session and has_conflict) then
    raise exception 'Resolve conflicting counts before posting';
  end if;
  if exists (select 1 from public.count_entries where session_id = p_session and recount_requested) then
    raise exception 'Recounts are still outstanding';
  end if;
  if exists (select 1 from public.count_sessions where location_id = v_s.location_id and status = 'posted' and count_at >= v_s.count_at and id <> p_session) then
    raise exception 'A later count has already been posted for this location. Counts must be posted in time order.';
  end if;

  drop table if exists tmp_review;
  create temporary table tmp_review on commit drop as select * from public.count_review_lines(p_session);
  select count(*) into v_flagged from tmp_review where exceeds_tolerance;
  if v_flagged > 0 and not p_acknowledge_flags then
    raise exception '% item(s) exceed the variance tolerance. Recount them or confirm the variances to post.', v_flagged using errcode = 'P0004';
  end if;
  select count(*) into v_uncounted from tmp_review where not counted;

  for l in select * from tmp_review where physical_qty is not null loop
    v_txn := null;
    if l.variance_qty <> 0 then
      v_txn := app.post_inventory_txn(v_s.location_id, l.product_id, 'PHYSICAL_VARIANCE', l.variance_qty, l.unit_cost,
                                      v_s.count_at, 'count_session', p_session, null, null, null, v_s.count_number,
                                      case when not l.counted then 'Not counted; posted as zero' end);
    end if;
    insert into public.count_posting_lines (session_id, product_id, counted, begin_qty, received_qty, transfer_in_qty, transfer_out_qty,
                                            produced_qty, consumed_qty, waste_qty, adjusted_qty, book_qty, physical_qty, variance_qty,
                                            unit_cost, variance_value, txn_id)
    values (p_session, l.product_id, l.counted, l.begin_qty, l.received_qty, l.transfer_in_qty, l.transfer_out_qty,
            l.produced_qty, l.consumed_qty, l.waste_qty, l.adjusted_qty, l.book_qty, l.physical_qty, l.variance_qty,
            l.unit_cost, coalesce(l.variance_value, 0), v_txn);
    update public.location_products set last_counted_at = v_s.count_at
      where location_id = v_s.location_id and product_id = l.product_id
        and (last_counted_at is null or last_counted_at < v_s.count_at);
    v_lines := v_lines + 1;
    v_total := v_total + coalesce(l.variance_value, 0);
  end loop;

  update public.count_sessions set status = 'posted', posted_at = now(), posted_by = auth.uid(),
         reviewed_at = coalesce(reviewed_at, now()), reviewed_by = coalesce(reviewed_by, auth.uid())
  where id = p_session;

  perform app.audit(v_s.organization_id, v_s.location_id, 'post', 'count_session', p_session::text,
                    format('Posted %s (%s lines, variance %s)', v_s.count_number, v_lines, round(v_total, 2)), null,
                    jsonb_build_object('lines', v_lines, 'variance_value', round(v_total, 2), 'flagged', v_flagged,
                                       'acknowledged_flags', p_acknowledge_flags, 'uncounted', v_uncounted));
  return jsonb_build_object('lines', v_lines, 'variance_value', round(v_total, 2), 'flagged', v_flagged, 'uncounted', v_uncounted);
end $$;

-- Posted/cancelled counts are locked.
create or replace function app.count_entries_lock() returns trigger
language plpgsql as $$
declare v_status public.count_status;
begin
  select status into v_status from public.count_sessions where id = coalesce(new.session_id, old.session_id);
  if v_status in ('posted', 'cancelled') then
    raise exception 'Count is % and locked', v_status;
  end if;
  return coalesce(new, old);
end $$;
create trigger trg_count_entries_lock before insert or update or delete on public.count_entries
  for each row execute function app.count_entries_lock();

create or replace function app.count_sessions_lock() returns trigger
language plpgsql as $$
begin
  if old.status in ('posted', 'cancelled') then
    raise exception 'Count % is % and locked', old.count_number, old.status;
  end if;
  if new.count_number <> old.count_number then raise exception 'Count numbers are immutable'; end if;
  return new;
end $$;
create trigger trg_count_sessions_lock before update on public.count_sessions
  for each row execute function app.count_sessions_lock();

select app.apply_grants();

-- ============================================================================
-- 20260930000500_alerts_tasks.sql
-- ============================================================================
-- =====================================================================
-- ALERT ENGINE and OPERATIONAL TASKS
-- =====================================================================

create type public.alert_type as enum (
  'low_stock', 'out_of_stock', 'critical_stock', 'negative_inventory', 'high_variance', 'high_waste', 'price_increase',
  'invoice_difference', 'late_delivery', 'order_not_submitted', 'inventory_due', 'inventory_not_posted',
  'unexpected_consumption', 'expiring_product', 'temperature_failure', 'short_delivery'
);

create table public.alerts (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  location_id     uuid references public.locations(id) on delete cascade,
  alert_type      public.alert_type not null,
  severity        text not null default 'warning' check (severity in ('info', 'warning', 'critical')),
  title           text not null,
  message         text,
  product_id      uuid references public.products(id),
  entity_type     text,
  entity_id       uuid,
  dedupe_key      text not null,
  data            jsonb not null default '{}'::jsonb,
  status          text not null default 'open' check (status in ('open', 'acknowledged', 'resolved')),
  acknowledged_by uuid references public.profiles(id),
  acknowledged_at timestamptz,
  resolved_by     uuid references public.profiles(id),
  resolved_at     timestamptz,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create unique index alerts_open_dedupe on public.alerts (location_id, dedupe_key) where status <> 'resolved';
create index on public.alerts (location_id, status, created_at desc);
create trigger trg_alerts_touch before update on public.alerts for each row execute function app.touch_updated_at();
insert into app.write_protected_tables values ('alerts');

create or replace function app.raise_alert(
  p_location uuid, p_type public.alert_type, p_severity text, p_title text, p_message text,
  p_dedupe text, p_product uuid default null, p_entity_type text default null, p_entity_id uuid default null,
  p_data jsonb default '{}'::jsonb
) returns void
language plpgsql security definer set search_path = public as $$
begin
  insert into public.alerts (organization_id, location_id, alert_type, severity, title, message, product_id, entity_type, entity_id, dedupe_key, data)
  values (app.location_org(p_location), p_location, p_type, p_severity, p_title, p_message, p_product, p_entity_type, p_entity_id, p_dedupe, p_data)
  on conflict (location_id, dedupe_key) where status <> 'resolved'
  do update set title = excluded.title, message = excluded.message, severity = excluded.severity, data = excluded.data;
end $$;

create or replace function app.resolve_alerts(p_location uuid, p_dedupe_prefix text, p_keep text[]) returns void
language plpgsql security definer set search_path = public as $$
begin
  update public.alerts set status = 'resolved', resolved_at = now()
  where location_id = p_location and status <> 'resolved'
    and dedupe_key like p_dedupe_prefix || '%'
    and not (dedupe_key = any(coalesce(p_keep, '{}')));
end $$;

-- ---------------------------------------------------------------------
-- Tasks
-- ---------------------------------------------------------------------
create table public.tasks (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  location_id     uuid not null references public.locations(id) on delete cascade,
  title           text not null check (length(btrim(title)) > 0),
  description     text,
  task_type       text not null default 'custom' check (task_type in ('count', 'order', 'receive', 'review_variance', 'review_waste', 'invoice', 'custom')),
  due_at          timestamptz not null,
  assigned_to     uuid references public.profiles(id),
  entity_type     text,
  entity_id       uuid,
  dedupe_key      text,
  recurrence      text check (recurrence in ('daily', 'weekly', 'monthly')),
  status          text not null default 'open' check (status in ('open', 'complete', 'cancelled')),
  completed_by    uuid references public.profiles(id),
  completed_at    timestamptz,
  created_by      uuid references public.profiles(id),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index on public.tasks (location_id, status, due_at);
create unique index tasks_open_dedupe on public.tasks (location_id, dedupe_key) where status = 'open' and dedupe_key is not null;
create trigger trg_tasks_touch before update on public.tasks for each row execute function app.touch_updated_at();

create or replace function app.create_task(p_location uuid, p_title text, p_type text, p_due timestamptz, p_description text,
                                           p_entity_type text, p_entity_id uuid, p_dedupe text) returns void
language plpgsql security definer set search_path = public as $$
begin
  insert into public.tasks (organization_id, location_id, title, description, task_type, due_at, entity_type, entity_id, dedupe_key, created_by)
  values (app.location_org(p_location), p_location, p_title, p_description, p_type, p_due, p_entity_type, p_entity_id, p_dedupe, auth.uid())
  on conflict (location_id, dedupe_key) where status = 'open' and dedupe_key is not null do nothing;
end $$;

create or replace function app.complete_tasks_for(p_entity_id uuid, p_type text) returns void
language plpgsql security definer set search_path = public as $$
begin
  update public.tasks set status = 'complete', completed_at = now(), completed_by = auth.uid()
  where entity_id = p_entity_id and task_type = p_type and status = 'open';
end $$;

create or replace function public.complete_task(p_task uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_t public.tasks;
begin
  select * into v_t from public.tasks where id = p_task for update;
  if v_t.id is null or not (v_t.location_id in (select app.user_location_ids())) then raise exception 'Task not found'; end if;
  if not (v_t.assigned_to = auth.uid() or v_t.assigned_to is null or app.has_permission('tasks.manage', v_t.location_id)) then
    raise exception 'Only the assignee or a manager can complete this task' using errcode = '42501';
  end if;
  if v_t.status <> 'open' then return; end if;
  update public.tasks set status = 'complete', completed_at = now(), completed_by = auth.uid() where id = p_task;
  if v_t.recurrence is not null then
    insert into public.tasks (organization_id, location_id, title, description, task_type, due_at, assigned_to, recurrence, created_by)
    values (v_t.organization_id, v_t.location_id, v_t.title, v_t.description, v_t.task_type,
            v_t.due_at + case v_t.recurrence when 'daily' then interval '1 day' when 'weekly' then interval '7 days' else interval '1 month' end,
            v_t.assigned_to, v_t.recurrence, auth.uid());
  end if;
  perform app.audit(v_t.organization_id, v_t.location_id, 'complete', 'task', p_task::text, v_t.title, null, null);
end $$;

create or replace function public.acknowledge_alert(p_alert uuid, p_resolve boolean default false) returns void
language plpgsql security definer set search_path = public as $$
declare v_a public.alerts;
begin
  select * into v_a from public.alerts where id = p_alert for update;
  if v_a.id is null or not (v_a.location_id in (select app.user_location_ids())) then raise exception 'Alert not found'; end if;
  update public.alerts set
    status = case when p_resolve then 'resolved' else 'acknowledged' end,
    acknowledged_by = coalesce(acknowledged_by, auth.uid()), acknowledged_at = coalesce(acknowledged_at, now()),
    resolved_by = case when p_resolve then auth.uid() end, resolved_at = case when p_resolve then now() end
  where id = p_alert;
end $$;

alter table public.alerts enable row level security;
alter table public.tasks enable row level security;

create policy alerts_select on public.alerts for select to authenticated
  using (location_id in (select app.user_location_ids()));
create policy tasks_select on public.tasks for select to authenticated
  using (location_id in (select app.user_location_ids()));
create policy tasks_insert on public.tasks for insert to authenticated
  with check (app.has_permission('tasks.manage', location_id) and organization_id = app.location_org(location_id));
create policy tasks_update on public.tasks for update to authenticated
  using (app.has_permission('tasks.manage', location_id))
  with check (app.has_permission('tasks.manage', location_id));

-- Stock alerts are recomputed from current balances (called by the dashboard and after posting).
create or replace function public.refresh_stock_alerts(p_location uuid) returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_keep text[];
  v_n integer;
begin
  if not (p_location in (select app.user_location_ids())) then raise exception 'Location not found' using errcode = '42501'; end if;

  with st as (
    select ci.* from public.current_inventory ci where ci.location_id = p_location and ci.active
  ),
  raised as (
    select app.raise_alert(p_location,
             case st.stock_status when 'negative' then 'negative_inventory'::public.alert_type
                                  when 'out' then 'out_of_stock'::public.alert_type
                                  when 'critical' then 'critical_stock'::public.alert_type
                                  else 'low_stock'::public.alert_type end,
             case when st.stock_status in ('negative', 'out', 'critical') then 'critical' else 'warning' end,
             case st.stock_status when 'negative' then 'Negative inventory: ' || st.product_name
                                  when 'out' then 'Out of stock: ' || st.product_name
                                  when 'critical' then 'Critical stock: ' || st.product_name
                                  else 'Low stock: ' || st.product_name end,
             case when st.stock_status = 'negative'
                  then format('Book inventory is %s %s. Possible causes: missing receipt, incorrect recipe, missing production, wrong unit conversion, unrecorded transfer or a bad count.', st.on_hand, st.inventory_unit)
                  else format('On hand %s %s (par %s)', st.on_hand, st.inventory_unit, coalesce(st.effective_par::text, 'not set')) end,
             'stock:' || st.product_id || ':' || st.stock_status, st.product_id, 'product', st.product_id,
             jsonb_build_object('on_hand', st.on_hand, 'par', st.effective_par)) as x,
           'stock:' || st.product_id || ':' || st.stock_status as k
    from st
    where st.stock_status <> 'ok'
      and (st.stock_status = 'negative' or st.effective_par is not null or st.min_qty is not null or st.last_txn_at is not null)
  )
  select array_agg(k) into v_keep from raised;
  perform app.resolve_alerts(p_location, 'stock:', v_keep);

  -- Inventory due: no posted count in 7 days
  if not exists (select 1 from public.count_sessions where location_id = p_location and status = 'posted' and count_at > now() - interval '7 days') then
    perform app.raise_alert(p_location, 'inventory_due', 'warning', 'Weekly inventory is due',
      'No inventory count has been posted in the last 7 days.', 'inventory_due');
  else
    perform app.resolve_alerts(p_location, 'inventory_due', null);
  end if;

  -- Counts waiting too long for posting
  select array_agg('count_unposted:' || id) into v_keep from public.count_sessions
   where location_id = p_location and status in ('awaiting_review', 'reviewed') and submitted_at < now() - interval '24 hours';
  perform app.raise_alert(p_location, 'inventory_not_posted', 'warning', 'Inventory not posted: ' || s.name,
    'Submitted ' || to_char(s.submitted_at, 'Mon DD HH24:MI') || ' and still not posted.', 'count_unposted:' || s.id, null, 'count_session', s.id)
  from public.count_sessions s
  where s.location_id = p_location and s.status in ('awaiting_review', 'reviewed') and s.submitted_at < now() - interval '24 hours';
  perform app.resolve_alerts(p_location, 'count_unposted:', v_keep);

  select count(*) into v_n from public.alerts where location_id = p_location and status <> 'resolved';
  return v_n;
end $$;

select app.apply_grants();

-- ============================================================================
-- 20260930000600_purchasing.sql
-- ============================================================================
-- =====================================================================
-- PURCHASING: suggested ordering engine, purchase orders, receiving,
-- invoice reconciliation, lots/traceability, price history & alerts.
-- =====================================================================

create type public.po_status as enum (
  'draft', 'ready_to_submit', 'submitted', 'confirmed', 'partially_received', 'invoice_received',
  'ready_to_reconcile', 'reconciled', 'posted', 'back_ordered', 'cancelled'
);

create table public.purchase_orders (
  id                     uuid primary key default gen_random_uuid(),
  organization_id        uuid not null references public.organizations(id),
  location_id            uuid not null references public.locations(id),
  vendor_id              uuid not null references public.vendors(id),
  po_number              text not null,
  status                 public.po_status not null default 'draft',
  order_date             date not null default current_date,
  expected_delivery_date date not null,
  next_delivery_date     date,
  delivery_window        text,
  notes                  text,
  confirmation_number    text,
  client_key             uuid unique,
  created_by             uuid references public.profiles(id),
  submitted_by           uuid references public.profiles(id),
  submitted_at           timestamptz,
  confirmed_at           timestamptz,
  cancelled_by           uuid references public.profiles(id),
  cancelled_at           timestamptz,
  cancel_reason          text,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  unique (organization_id, po_number),
  check (next_delivery_date is null or next_delivery_date > expected_delivery_date)
);
create index on public.purchase_orders (location_id, status, expected_delivery_date);
create index on public.purchase_orders (vendor_id);
create trigger trg_po_touch before update on public.purchase_orders for each row execute function app.touch_updated_at();

create table public.purchase_order_items (
  id                 uuid primary key default gen_random_uuid(),
  po_id              uuid not null references public.purchase_orders(id) on delete cascade,
  product_id         uuid not null references public.products(id),
  vendor_product_id  uuid references public.vendor_products(id),
  unit_id            uuid not null references public.units(id),
  unit_factor        numeric(24,10) not null check (unit_factor > 0),   -- inventory units per order unit (snapshot)
  suggested_qty      numeric(12,4) check (suggested_qty is null or suggested_qty >= 0),  -- SYSTEM SUGGESTION
  order_qty          numeric(12,4) not null check (order_qty >= 0),    -- MANAGER ORDER
  unit_price         numeric(18,4) not null default 0 check (unit_price >= 0),
  extended_price     numeric(18,2) generated always as (round(order_qty * unit_price, 2)) stored,
  suggestion         jsonb,        -- explanation snapshot ("why 4 cases?")
  received_qty       numeric(12,4) not null default 0,   -- posted receipts, in order units
  back_ordered_qty   numeric(12,4) not null default 0 check (back_ordered_qty >= 0),
  notes              text,
  sort               integer not null default 0,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  unique (po_id, product_id, unit_id)
);
create index on public.purchase_order_items (product_id);
create trigger trg_poi_touch before update on public.purchase_order_items for each row execute function app.touch_updated_at();

-- ---------------------------------------------------------------------
-- Receiving + invoice (one document per delivery)
-- ---------------------------------------------------------------------
create type public.receipt_status as enum ('draft', 'received', 'posted', 'cancelled');

create table public.receipts (
  id                 uuid primary key default gen_random_uuid(),
  organization_id    uuid not null references public.organizations(id),
  location_id        uuid not null references public.locations(id),
  vendor_id          uuid not null references public.vendors(id),
  purchase_order_id  uuid references public.purchase_orders(id),
  receipt_number     text not null,
  status             public.receipt_status not null default 'draft',
  delivery_date      date not null default current_date,
  received_at        timestamptz,
  received_by        uuid references public.profiles(id),
  invoice_number     text,
  invoice_date       date,
  invoice_total      numeric(12,2) check (invoice_total is null or invoice_total >= 0),
  tax                numeric(12,2) not null default 0 check (tax >= 0),
  freight            numeric(12,2) not null default 0 check (freight >= 0),
  fuel_surcharge     numeric(12,2) not null default 0 check (fuel_surcharge >= 0),
  misc_fees          numeric(12,2) not null default 0 check (misc_fees >= 0),
  credits            numeric(12,2) not null default 0 check (credits >= 0),
  notes              text,
  client_key         uuid unique,
  document_id        uuid,
  override_reason    text,
  override_by        uuid references public.profiles(id),
  posted_at          timestamptz,
  posted_by          uuid references public.profiles(id),
  cancelled_at       timestamptz,
  cancelled_by       uuid references public.profiles(id),
  created_by         uuid references public.profiles(id),
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  unique (organization_id, receipt_number)
);
-- Duplicate invoice protection
create unique index receipts_invoice_uniq on public.receipts (vendor_id, lower(invoice_number))
  where status <> 'cancelled' and invoice_number is not null;
create index on public.receipts (location_id, status, delivery_date desc);
create index on public.receipts (purchase_order_id);
create trigger trg_receipts_touch before update on public.receipts for each row execute function app.touch_updated_at();

create table public.receipt_items (
  id                  uuid primary key default gen_random_uuid(),
  receipt_id          uuid not null references public.receipts(id) on delete cascade,
  po_item_id          uuid references public.purchase_order_items(id),
  product_id          uuid not null references public.products(id),
  vendor_product_id   uuid references public.vendor_products(id),
  unit_id             uuid not null references public.units(id),
  unit_factor         numeric(24,10) not null check (unit_factor > 0),
  line_type           text not null default 'ordered' check (line_type in ('ordered', 'substitution', 'forced', 'wrong_item', 'unordered')),
  substitute_for_id   uuid references public.receipt_items(id),
  ordered_qty         numeric(12,4) not null default 0 check (ordered_qty >= 0),
  received_qty        numeric(12,4) check (received_qty is null or received_qty >= 0),   -- physically accepted
  invoiced_qty        numeric(12,4) check (invoiced_qty is null or invoiced_qty >= 0),
  rejected_qty        numeric(12,4) not null default 0 check (rejected_qty >= 0),
  damaged_qty         numeric(12,4) not null default 0 check (damaged_qty >= 0),
  contract_price      numeric(18,4),
  invoice_price       numeric(18,4) check (invoice_price is null or invoice_price >= 0),
  invoice_extended    numeric(18,2) check (invoice_extended is null or invoice_extended >= 0),
  catch_weight_qty    numeric(18,4) check (catch_weight_qty is null or catch_weight_qty > 0),  -- actual inventory units (e.g. LB)
  back_order          boolean not null default false,
  exception_codes     text[] not null default '{}',
  temperature         numeric(6,2),
  temp_max            numeric(6,2),
  temp_min            numeric(6,2),
  temp_decision       text check (temp_decision in ('accept', 'reject', 'override')),
  lot_number          text,
  lot_tlc             text,
  lot_production_date date,
  expiration_date     date,
  best_by_date        date,
  storage_allocations jsonb not null default '[]'::jsonb,   -- [{storage_location_id, qty}] in order units
  notes               text,
  sort                integer not null default 0,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create index on public.receipt_items (receipt_id, sort);
create trigger trg_receipt_items_touch before update on public.receipt_items for each row execute function app.touch_updated_at();

-- Lots & traceability
create table public.lots (
  id                    uuid primary key default gen_random_uuid(),
  organization_id       uuid not null references public.organizations(id),
  product_id            uuid not null references public.products(id),
  lot_number            text not null,
  traceability_lot_code text,
  lot_source            text,
  vendor_id             uuid references public.vendors(id),
  production_date       date,
  expiration_date       date,
  best_by_date          date,
  created_at            timestamptz not null default now(),
  unique (organization_id, product_id, lot_number)
);
create table public.lot_receipts (
  id                  uuid primary key default gen_random_uuid(),
  organization_id     uuid not null references public.organizations(id),
  location_id         uuid not null references public.locations(id),
  lot_id              uuid not null references public.lots(id),
  receipt_id          uuid references public.receipts(id),
  receipt_item_id     uuid references public.receipt_items(id),
  storage_location_id uuid references public.storage_locations(id),
  quantity            numeric(18,4) not null,
  received_at         timestamptz not null,
  created_at          timestamptz not null default now()
);
create index on public.lot_receipts (lot_id);
create index lots_number_trgm on public.lots using gin (lot_number extensions.gin_trgm_ops);

alter table public.inventory_transactions add constraint inv_txn_lot_fk foreign key (lot_id) references public.lots(id);

insert into app.write_protected_tables values
  ('purchase_orders'), ('purchase_order_items'), ('receipts'), ('receipt_items'), ('lots'), ('lot_receipts');

-- Audit every quantity/price change on POs and receipts (who changed invoice qty 5 -> 4)
create trigger trg_po_audit after insert or update on public.purchase_orders for each row execute function app.audit_row();
create or replace function app.audit_child_row() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_old jsonb := case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end;
  v_new jsonb := case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) end;
  v_row jsonb := coalesce(v_new, v_old);
  v_parent_table text := tg_argv[0];
  v_parent_col text := tg_argv[1];
  v_parent_id uuid := (v_row ->> v_parent_col)::uuid;
  v_org uuid; v_loc uuid;
  v_od jsonb := '{}'; v_nd jsonb := '{}'; k text;
begin
  execute format('select organization_id, location_id from public.%I where id = $1', v_parent_table) into v_org, v_loc using v_parent_id;
  if tg_op = 'UPDATE' then
    for k in select jsonb_object_keys(v_new) loop
      if k not in ('updated_at') and (v_old -> k) is distinct from (v_new -> k) then
        v_od := v_od || jsonb_build_object(k, v_old -> k); v_nd := v_nd || jsonb_build_object(k, v_new -> k);
      end if;
    end loop;
    if v_nd = '{}'::jsonb then return new; end if;
  else
    v_od := v_old; v_nd := v_new;
  end if;
  perform app.audit(v_org, v_loc, lower(tg_op), tg_table_name, v_row ->> 'id',
    (select name from public.products where id = (v_row ->> 'product_id')::uuid), v_od, v_nd);
  return coalesce(new, old);
end $$;
create trigger trg_poi_audit after insert or update or delete on public.purchase_order_items
  for each row execute function app.audit_child_row('purchase_orders', 'po_id');
create trigger trg_receipts_audit after insert or update on public.receipts for each row execute function app.audit_row();
create trigger trg_receipt_items_audit after insert or update or delete on public.receipt_items
  for each row execute function app.audit_child_row('receipts', 'receipt_id');

-- ---------------------------------------------------------------------
-- RLS (reads by location; writes through functions)
-- ---------------------------------------------------------------------
alter table public.purchase_orders      enable row level security;
alter table public.purchase_order_items enable row level security;
alter table public.receipts             enable row level security;
alter table public.receipt_items        enable row level security;
alter table public.lots                 enable row level security;
alter table public.lot_receipts         enable row level security;

create policy po_select on public.purchase_orders for select to authenticated
  using (location_id in (select app.user_location_ids()));
create policy poi_select on public.purchase_order_items for select to authenticated
  using (po_id in (select id from public.purchase_orders));
create policy receipts_select on public.receipts for select to authenticated
  using (location_id in (select app.user_location_ids()));
create policy receipt_items_select on public.receipt_items for select to authenticated
  using (receipt_id in (select id from public.receipts));
create policy lots_select on public.lots for select to authenticated
  using (organization_id in (select app.user_org_ids()));
create policy lot_receipts_select on public.lot_receipts for select to authenticated
  using (location_id in (select app.user_location_ids()));

-- ---------------------------------------------------------------------
-- Usage & forecasting hooks
-- ---------------------------------------------------------------------
-- Average daily usage from the ledger: consumption + waste + count variance
-- + adjustments (i.e. actual usage), over the trailing window.
create or replace function app.avg_daily_usage(p_location uuid, p_product uuid, p_days integer default 28) returns numeric
language sql stable security definer set search_path = public as $$
  select greatest(0, -coalesce(sum(quantity), 0)) / greatest(p_days, 1)
  from public.inventory_transactions
  where location_id = p_location and product_id = p_product
    and txn_type in ('POS_CONSUMPTION', 'RECIPE_CONSUMPTION', 'WASTE', 'PHYSICAL_VARIANCE', 'MANUAL_ADJUSTMENT')
    and txn_at > now() - make_interval(days => p_days) and txn_at <= now()
$$;

-- Forecast usage between two dates. Returns {qty, method, daily}. Replaced by the
-- forecasting migration with a day-of-week / sales-driven model.
create or replace function app.forecast_usage(p_location uuid, p_product uuid, p_from date, p_to date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_daily numeric := app.avg_daily_usage(p_location, p_product, 28);
begin
  return jsonb_build_object('qty', round(v_daily * greatest(p_to - p_from, 0), 4), 'daily', round(v_daily, 4),
                            'method', '28-day average daily usage');
end $$;

-- Quantity on open purchase orders not yet received (inventory units).
create or replace function app.on_order_qty(p_location uuid, p_product uuid, p_exclude_po uuid default null) returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce(sum(greatest(i.order_qty - i.received_qty, 0) * i.unit_factor), 0)
  from public.purchase_order_items i join public.purchase_orders po on po.id = i.po_id
  where po.location_id = p_location and i.product_id = p_product
    and (p_exclude_po is null or po.id <> p_exclude_po)
    and po.status in ('submitted', 'confirmed', 'partially_received', 'back_ordered', 'invoice_received', 'ready_to_reconcile')
$$;

-- Next delivery day for a vendor after a date (uses local overrides).
create or replace function app.next_vendor_delivery(p_location uuid, p_vendor uuid, p_after date) returns date
language plpgsql stable security definer set search_path = public as $$
declare
  v_days smallint[];
  d date;
begin
  select coalesce(lv.delivery_days, v.delivery_days) into v_days
  from public.vendors v left join public.location_vendors lv on lv.vendor_id = v.id and lv.location_id = p_location
  where v.id = p_vendor;
  if coalesce(array_length(v_days, 1), 0) = 0 then return p_after + 7; end if;
  for i in 1..7 loop
    d := p_after + i;
    if extract(dow from d)::smallint = any(v_days) then return d; end if;
  end loop;
  return p_after + 7;
end $$;

-- ---------------------------------------------------------------------
-- SUGGESTED ORDER ENGINE:  NEED - HAVE = SUGGESTED ORDER
-- ---------------------------------------------------------------------
create or replace function public.suggest_order(
  p_location uuid, p_vendor uuid, p_delivery_date date, p_next_delivery_date date default null, p_exclude_po uuid default null
)
returns table (
  vendor_product_id uuid, product_id uuid, product_number text, product_name text, category_name text,
  vendor_item_number text, pack_size text, purchase_unit_id uuid, purchase_unit text, unit_factor numeric,
  inventory_unit text, unit_price numeric, on_hand numeric, on_order numeric, par numeric, par_mode public.par_mode,
  forecast_usage numeric, suggested_qty numeric, is_primary_vendor boolean, explanation jsonb
)
language plpgsql stable security definer set search_path = public as $$
declare
  v_next date;
  v_days_until integer;
  v_cover integer;
begin
  perform app.require_permission('orders.view', p_location);
  if p_delivery_date < current_date then raise exception 'Delivery date cannot be in the past'; end if;
  v_next := coalesce(p_next_delivery_date, app.next_vendor_delivery(p_location, p_vendor, p_delivery_date));
  if v_next <= p_delivery_date then raise exception 'Next delivery must be after this delivery'; end if;
  v_days_until := p_delivery_date - current_date;
  v_cover := v_next - p_delivery_date;

  return query
  with items as (
    select vp.id as vp_id, vp.product_id, p.product_number, p.name, c.name as cat, vp.vendor_item_number, vp.pack_size,
           vp.purchase_unit_id, pu.code as pu_code, app.unit_factor(vp.product_id, vp.purchase_unit_id) as factor,
           iu.code as iu_code, app.vendor_item_price(vp.id, p_delivery_date) as price,
           vp.order_multiple, vp.min_order_qty,
           coalesce(b.on_hand, 0) as on_hand,
           app.on_order_qty(p_location, vp.product_id, p_exclude_po) as on_order,
           lp.par_mode, case when lp.par_mode = 'dynamic' then coalesce(lp.dynamic_par_qty, lp.par_qty) when lp.par_mode = 'static' then lp.par_qty end as par,
           lp.safety_stock_qty, lp.safety_stock_days,
           (coalesce(lp.local_vendor_id, p.default_vendor_id,
                     (select v2.vendor_id from public.vendor_products v2 where v2.product_id = vp.product_id and v2.active
                      order by v2.is_preferred desc, v2.created_at limit 1)) = p_vendor) as is_primary,
           app.forecast_usage(p_location, vp.product_id, current_date, p_delivery_date) as f_until,
           app.forecast_usage(p_location, vp.product_id, p_delivery_date, v_next) as f_cover,
           vp.guide_sort
    from public.vendor_products vp
    join public.products p on p.id = vp.product_id and p.active and p.deleted_at is null
    join public.location_products lp on lp.product_id = vp.product_id and lp.location_id = p_location and lp.active
    join public.units pu on pu.id = vp.purchase_unit_id
    join public.units iu on iu.id = p.inventory_unit_id
    left join public.categories c on c.id = p.category_id
    left join public.inventory_balances b on b.location_id = p_location and b.product_id = vp.product_id
    where vp.vendor_id = p_vendor and vp.active
  ),
  calc as (
    select i.*,
      (i.f_until ->> 'qty')::numeric as usage_until,
      (i.f_cover ->> 'qty')::numeric as usage_cover,
      coalesce(i.safety_stock_qty, (i.f_cover ->> 'daily')::numeric * i.safety_stock_days, 0) as safety
    from items i
  ),
  need as (
    select c.*,
      c.usage_until + greatest(c.usage_cover + c.safety, case when c.par_mode <> 'none' then coalesce(c.par, 0) else 0 end) as need_qty,
      greatest(c.on_hand, 0) + c.on_order as have_qty
    from calc c
  ),
  sug as (
    select n.*,
      greatest(n.need_qty - n.have_qty, 0) as shortage,
      case when n.is_primary and n.need_qty - n.have_qty > 0 then
        greatest(ceil(((n.need_qty - n.have_qty) / n.factor) / n.order_multiple) * n.order_multiple, n.min_order_qty)
      else 0 end as sug_units
    from need n
  )
  select s.vp_id, s.product_id, s.product_number, s.name, s.cat, s.vendor_item_number, s.pack_size,
         s.purchase_unit_id, s.pu_code, s.factor, s.iu_code, s.price, s.on_hand, s.on_order, s.par, s.par_mode,
         round(s.usage_until + s.usage_cover, 4), s.sug_units, s.is_primary,
         jsonb_build_object(
           'delivery_date', p_delivery_date, 'next_delivery_date', v_next,
           'days_until_delivery', v_days_until, 'coverage_days', v_cover,
           'forecast_method', s.f_cover ->> 'method', 'avg_daily_usage', (s.f_cover ->> 'daily')::numeric,
           'usage_until_delivery', round(s.usage_until, 4), 'usage_during_coverage', round(s.usage_cover, 4),
           'safety_stock', round(s.safety, 4), 'par', s.par, 'par_mode', s.par_mode,
           'need', round(s.need_qty, 4), 'on_hand', s.on_hand, 'on_hand_used', greatest(s.on_hand, 0), 'incoming', s.on_order,
           'have', round(s.have_qty, 4), 'shortage', round(s.shortage, 4),
           'unit', s.iu_code, 'purchase_unit', s.pu_code, 'unit_factor', s.factor,
           'raw_purchase_units', round(s.shortage / s.factor, 4), 'order_multiple', s.order_multiple,
           'min_order_qty', s.min_order_qty, 'recommended', s.sug_units, 'is_primary_vendor', s.is_primary,
           'negative_on_hand', s.on_hand < 0)
  from sug s
  order by s.guide_sort, s.name;
end $$;

-- ---------------------------------------------------------------------
-- Purchase orders
-- ---------------------------------------------------------------------
-- p_lines: [{product_id, vendor_product_id, unit_id, order_qty, suggested_qty, suggestion}]
create or replace function app.write_po_lines(p_po uuid, p_lines jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_po public.purchase_orders;
  r jsonb; v_factor numeric; v_price numeric; v_vp public.vendor_products; v_sort int := 0;
begin
  select * into v_po from public.purchase_orders where id = p_po;
  delete from public.purchase_order_items where po_id = p_po;
  for r in select * from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) loop
    v_sort := v_sort + 1;
    continue when coalesce((r ->> 'order_qty')::numeric, 0) = 0 and nullif(r ->> 'suggested_qty', '') is null;
    v_vp := null;
    if nullif(r ->> 'vendor_product_id', '') is not null then
      select * into v_vp from public.vendor_products where id = (r ->> 'vendor_product_id')::uuid and vendor_id = v_po.vendor_id;
      if v_vp.id is null then raise exception 'Item is not on this vendor''s order guide'; end if;
    end if;
    v_factor := app.unit_factor((r ->> 'product_id')::uuid, coalesce(nullif(r ->> 'unit_id', '')::uuid, v_vp.purchase_unit_id));
    if v_factor is null then raise exception 'Order unit has no conversion for this product' using errcode = '22023'; end if;
    v_price := coalesce(nullif(r ->> 'unit_price', '')::numeric, case when v_vp.id is not null then app.vendor_item_price(v_vp.id, v_po.expected_delivery_date) end, 0);
    if (r ->> 'order_qty')::numeric < 0 then raise exception 'Order quantity cannot be negative'; end if;
    insert into public.purchase_order_items (po_id, product_id, vendor_product_id, unit_id, unit_factor, suggested_qty, order_qty, unit_price, suggestion, notes, sort)
    values (p_po, (r ->> 'product_id')::uuid, v_vp.id, coalesce(nullif(r ->> 'unit_id', '')::uuid, v_vp.purchase_unit_id), v_factor,
            nullif(r ->> 'suggested_qty', '')::numeric, coalesce((r ->> 'order_qty')::numeric, 0), v_price, r -> 'suggestion', r ->> 'notes', v_sort);
  end loop;
end $$;

create or replace function public.create_purchase_order(
  p_location uuid, p_vendor uuid, p_delivery_date date, p_lines jsonb,
  p_next_delivery_date date default null, p_notes text default null, p_client_key uuid default null, p_delivery_window text default null
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_org uuid := app.location_org(p_location);
  v_id uuid;
begin
  perform app.require_permission('orders.create', p_location);
  if p_client_key is not null then
    select id into v_id from public.purchase_orders where client_key = p_client_key;
    if v_id is not null then return v_id; end if;
  end if;
  if not exists (select 1 from public.vendors where id = p_vendor and organization_id = v_org and active) then
    raise exception 'Vendor not found';
  end if;
  insert into public.purchase_orders (organization_id, location_id, vendor_id, po_number, expected_delivery_date, next_delivery_date,
                                      delivery_window, notes, client_key, created_by)
  values (v_org, p_location, p_vendor, app.next_doc_number(v_org, 'PO'), p_delivery_date, p_next_delivery_date,
          p_delivery_window, p_notes, p_client_key, auth.uid())
  returning id into v_id;
  perform app.write_po_lines(v_id, p_lines);
  return v_id;
end $$;

create or replace function public.update_purchase_order(
  p_po uuid, p_lines jsonb, p_delivery_date date default null, p_next_delivery_date date default null,
  p_notes text default null, p_delivery_window text default null
) returns void
language plpgsql security definer set search_path = public as $$
declare v_po public.purchase_orders;
begin
  select * into v_po from public.purchase_orders where id = p_po for update;
  if v_po.id is null then raise exception 'Order not found'; end if;
  perform app.require_permission('orders.create', v_po.location_id);
  if v_po.status not in ('draft', 'ready_to_submit') then
    raise exception 'Order % is % and can no longer be edited', v_po.po_number, v_po.status;
  end if;
  update public.purchase_orders set
    expected_delivery_date = coalesce(p_delivery_date, expected_delivery_date),
    next_delivery_date = coalesce(p_next_delivery_date, next_delivery_date),
    notes = coalesce(p_notes, notes), delivery_window = coalesce(p_delivery_window, delivery_window)
  where id = p_po;
  if p_lines is not null then perform app.write_po_lines(p_po, p_lines); end if;
end $$;

create or replace function public.set_purchase_order_status(
  p_po uuid, p_status public.po_status, p_reason text default null, p_confirmation text default null, p_confirm_below_minimum boolean default false
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_po public.purchase_orders;
  v_total numeric;
  v_min numeric;
begin
  select * into v_po from public.purchase_orders where id = p_po for update;
  if v_po.id is null then raise exception 'Order not found'; end if;
  if v_po.status = p_status then return jsonb_build_object('status', p_status, 'unchanged', true); end if;

  if p_status = 'ready_to_submit' then
    perform app.require_permission('orders.create', v_po.location_id);
    if v_po.status <> 'draft' then raise exception 'Only draft orders can be marked ready'; end if;
    update public.purchase_orders set status = 'ready_to_submit' where id = p_po;
  elsif p_status = 'draft' then
    perform app.require_permission('orders.create', v_po.location_id);
    if v_po.status <> 'ready_to_submit' then raise exception 'Only a ready order can go back to draft'; end if;
    update public.purchase_orders set status = 'draft' where id = p_po;
  elsif p_status = 'submitted' then
    perform app.require_permission('orders.submit', v_po.location_id);
    if v_po.status not in ('draft', 'ready_to_submit') then
      raise exception 'Order % was already submitted (status %)', v_po.po_number, v_po.status using errcode = 'P0003';
    end if;
    select coalesce(sum(extended_price), 0) into v_total from public.purchase_order_items where po_id = p_po and order_qty > 0;
    if v_total = 0 and not exists (select 1 from public.purchase_order_items where po_id = p_po and order_qty > 0) then
      raise exception 'The order has no quantities';
    end if;
    select minimum_order into v_min from public.vendors where id = v_po.vendor_id;
    if v_total < v_min and not p_confirm_below_minimum then
      raise exception 'Order total % is below the vendor minimum of %. Confirm to submit anyway.', v_total, v_min using errcode = 'P0005';
    end if;
    delete from public.purchase_order_items where po_id = p_po and order_qty = 0;
    update public.purchase_orders set status = 'submitted', submitted_at = now(), submitted_by = auth.uid() where id = p_po;
  elsif p_status = 'confirmed' then
    perform app.require_permission('orders.submit', v_po.location_id);
    if v_po.status <> 'submitted' then raise exception 'Only submitted orders can be confirmed'; end if;
    update public.purchase_orders set status = 'confirmed', confirmed_at = now(), confirmation_number = p_confirmation where id = p_po;
  elsif p_status = 'cancelled' then
    perform app.require_permission('orders.create', v_po.location_id);
    if v_po.status not in ('draft', 'ready_to_submit', 'submitted', 'confirmed', 'back_ordered') then
      raise exception 'Order % cannot be cancelled in status %', v_po.po_number, v_po.status;
    end if;
    if exists (select 1 from public.receipts where purchase_order_id = p_po and status in ('draft', 'received')) then
      raise exception 'Cancel or post the open receipt for this order first';
    end if;
    if coalesce(btrim(p_reason), '') = '' then raise exception 'A reason is required to cancel an order'; end if;
    update public.purchase_orders set status = 'cancelled', cancelled_at = now(), cancelled_by = auth.uid(), cancel_reason = p_reason where id = p_po;
  else
    raise exception 'Status % is set by receiving and reconciliation, not manually', p_status;
  end if;
  perform app.audit(v_po.organization_id, v_po.location_id, 'status', 'purchase_order', p_po::text,
                    format('%s: %s -> %s', v_po.po_number, v_po.status, p_status), null, null);
  return jsonb_build_object('status', p_status);
end $$;

-- ---------------------------------------------------------------------
-- Receiving
-- ---------------------------------------------------------------------
create or replace function public.create_receipt(p_location uuid, p_vendor uuid, p_po uuid default null, p_client_key uuid default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_org uuid := app.location_org(p_location);
  v_po public.purchase_orders;
  v_id uuid;
begin
  perform app.require_permission('orders.receive', p_location);
  if p_client_key is not null then
    select id into v_id from public.receipts where client_key = p_client_key;
    if v_id is not null then return v_id; end if;
  end if;
  if p_po is not null then
    select * into v_po from public.purchase_orders where id = p_po and location_id = p_location for update;
    if v_po.id is null then raise exception 'Order not found'; end if;
    -- Duplicate receiving protection: reuse the open receipt for this order.
    select id into v_id from public.receipts where purchase_order_id = p_po and status in ('draft', 'received');
    if v_id is not null then return v_id; end if;
    if v_po.status not in ('submitted', 'confirmed', 'partially_received', 'back_ordered', 'invoice_received', 'ready_to_reconcile') then
      raise exception 'Order % is % and cannot be received', v_po.po_number, v_po.status;
    end if;
    p_vendor := v_po.vendor_id;
  end if;
  if not exists (select 1 from public.vendors where id = p_vendor and organization_id = v_org) then raise exception 'Vendor not found'; end if;

  insert into public.receipts (organization_id, location_id, vendor_id, purchase_order_id, receipt_number, client_key, created_by)
  values (v_org, p_location, p_vendor, p_po, app.next_doc_number(v_org, 'RCV'), p_client_key, auth.uid())
  returning id into v_id;

  if p_po is not null then
    insert into public.receipt_items (receipt_id, po_item_id, product_id, vendor_product_id, unit_id, unit_factor, line_type,
                                      ordered_qty, invoiced_qty, contract_price, invoice_price, temp_min, temp_max, sort)
    select v_id, i.id, i.product_id, i.vendor_product_id, i.unit_id, i.unit_factor, 'ordered',
           greatest(i.order_qty - i.received_qty, 0), greatest(i.order_qty - i.received_qty, 0), i.unit_price, i.unit_price,
           p.receiving_temp_min, p.receiving_temp_max, i.sort
    from public.purchase_order_items i join public.products p on p.id = i.product_id
    where i.po_id = p_po and i.order_qty - i.received_qty > 0;
  end if;
  return v_id;
end $$;

-- Exception codes are derived from the numbers so nothing is missed.
create or replace function app.receipt_item_exceptions(ri public.receipt_items) returns text[]
language sql immutable as $$
  select array_remove(array[
    case when ri.received_qty is not null and ri.received_qty < ri.ordered_qty and ri.line_type = 'ordered' then 'short' end,
    case when ri.received_qty is not null and ri.received_qty > ri.ordered_qty and ri.line_type = 'ordered' then 'over' end,
    case when ri.received_qty = 0 and ri.ordered_qty > 0 then 'missing' end,
    case when ri.invoiced_qty is not null and ri.received_qty is not null and ri.invoiced_qty <> ri.received_qty then 'invoice_qty_mismatch' end,
    case when ri.contract_price is not null and ri.invoice_price is not null and ri.invoice_price <> ri.contract_price then 'price_variance' end,
    case when ri.temperature is not null and ((ri.temp_max is not null and ri.temperature > ri.temp_max) or (ri.temp_min is not null and ri.temperature < ri.temp_min)) then 'temp_out_of_range' end,
    case when ri.back_order then 'back_order' end,
    case when ri.rejected_qty > 0 then 'rejected' end,
    case when ri.damaged_qty > 0 then 'damaged' end,
    case when ri.line_type = 'substitution' then 'substitution' end,
    case when ri.line_type = 'forced' then 'forced_ship' end,
    case when ri.line_type = 'wrong_item' then 'wrong_item' end,
    case when ri.catch_weight_qty is not null then 'catch_weight' end
  ], null)
$$;

-- p_header: {delivery_date, invoice_number, invoice_date, invoice_total, tax, freight, fuel_surcharge, misc_fees, credits, notes}
-- p_lines:  [{id?, product_id, vendor_product_id, unit_id, line_type, substitute_for_id, received_qty, invoiced_qty, invoice_price,
--             invoice_extended, rejected_qty, damaged_qty, catch_weight_qty, back_order, temperature, temp_decision,
--             lot_number, lot_tlc, lot_production_date, expiration_date, best_by_date, storage_allocations, notes, remove}]
create or replace function public.save_receipt(p_receipt uuid, p_header jsonb, p_lines jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_r public.receipts;
  r jsonb;
  v_item public.receipt_items;
  v_factor numeric;
  v_unit uuid;
  v_vp public.vendor_products;
  v_product public.products;
begin
  select * into v_r from public.receipts where id = p_receipt for update;
  if v_r.id is null then raise exception 'Receipt not found'; end if;
  perform app.require_permission('orders.receive', v_r.location_id);
  if v_r.status not in ('draft', 'received') then raise exception 'Receipt % is % and locked', v_r.receipt_number, v_r.status; end if;

  if p_header is not null then
    if nullif(p_header ->> 'invoice_number', '') is not null and exists (
         select 1 from public.receipts where vendor_id = v_r.vendor_id and lower(invoice_number) = lower(btrim(p_header ->> 'invoice_number'))
           and status <> 'cancelled' and id <> p_receipt) then
      raise exception 'Invoice % from this vendor was already entered on another receipt', p_header ->> 'invoice_number' using errcode = '23505';
    end if;
    update public.receipts set
      delivery_date  = coalesce(nullif(p_header ->> 'delivery_date', '')::date, delivery_date),
      invoice_number = case when p_header ? 'invoice_number' then nullif(btrim(p_header ->> 'invoice_number'), '') else invoice_number end,
      invoice_date   = case when p_header ? 'invoice_date' then nullif(p_header ->> 'invoice_date', '')::date else invoice_date end,
      invoice_total  = case when p_header ? 'invoice_total' then nullif(p_header ->> 'invoice_total', '')::numeric else invoice_total end,
      tax            = coalesce(nullif(p_header ->> 'tax', '')::numeric, tax),
      freight        = coalesce(nullif(p_header ->> 'freight', '')::numeric, freight),
      fuel_surcharge = coalesce(nullif(p_header ->> 'fuel_surcharge', '')::numeric, fuel_surcharge),
      misc_fees      = coalesce(nullif(p_header ->> 'misc_fees', '')::numeric, misc_fees),
      credits        = coalesce(nullif(p_header ->> 'credits', '')::numeric, credits),
      notes          = case when p_header ? 'notes' then p_header ->> 'notes' else notes end
    where id = p_receipt;
  end if;

  for r in select * from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) loop
    if nullif(r ->> 'id', '') is not null then
      select * into v_item from public.receipt_items where id = (r ->> 'id')::uuid and receipt_id = p_receipt for update;
      if v_item.id is null then raise exception 'Receipt line not found'; end if;
      if coalesce((r ->> 'remove')::boolean, false) then
        if v_item.line_type = 'ordered' then raise exception 'Ordered lines cannot be removed; set received quantity to 0 instead'; end if;
        delete from public.receipt_items where id = v_item.id;
        continue;
      end if;
    else
      -- New line: substitution / forced ship / wrong item / unordered
      select * into v_product from public.products where id = (r ->> 'product_id')::uuid and organization_id = v_r.organization_id;
      if v_product.id is null then raise exception 'Product not found'; end if;
      v_vp := null;
      if nullif(r ->> 'vendor_product_id', '') is not null then
        select * into v_vp from public.vendor_products where id = (r ->> 'vendor_product_id')::uuid;
      end if;
      v_unit := coalesce(nullif(r ->> 'unit_id', '')::uuid, v_vp.purchase_unit_id, v_product.purchase_unit_id, v_product.inventory_unit_id);
      v_factor := app.unit_factor(v_product.id, v_unit);
      if v_factor is null then raise exception 'Unit has no conversion for %', v_product.name using errcode = '22023'; end if;
      insert into public.receipt_items (receipt_id, product_id, vendor_product_id, unit_id, unit_factor, line_type, substitute_for_id,
                                        ordered_qty, contract_price, temp_min, temp_max, sort)
      values (p_receipt, v_product.id, v_vp.id, v_unit, v_factor, coalesce(nullif(r ->> 'line_type', ''), 'unordered'),
              nullif(r ->> 'substitute_for_id', '')::uuid, 0,
              case when v_vp.id is not null then app.vendor_item_price(v_vp.id, v_r.delivery_date) end,
              v_product.receiving_temp_min, v_product.receiving_temp_max, 1000)
      returning * into v_item;
    end if;

    update public.receipt_items set
      received_qty     = case when r ? 'received_qty' then nullif(r ->> 'received_qty', '')::numeric else received_qty end,
      invoiced_qty     = case when r ? 'invoiced_qty' then nullif(r ->> 'invoiced_qty', '')::numeric else invoiced_qty end,
      invoice_price    = case when r ? 'invoice_price' then nullif(r ->> 'invoice_price', '')::numeric else invoice_price end,
      invoice_extended = case when r ? 'invoice_extended' then nullif(r ->> 'invoice_extended', '')::numeric else invoice_extended end,
      rejected_qty     = coalesce(nullif(r ->> 'rejected_qty', '')::numeric, rejected_qty),
      damaged_qty      = coalesce(nullif(r ->> 'damaged_qty', '')::numeric, damaged_qty),
      catch_weight_qty = case when r ? 'catch_weight_qty' then nullif(r ->> 'catch_weight_qty', '')::numeric else catch_weight_qty end,
      back_order       = coalesce((r ->> 'back_order')::boolean, back_order),
      temperature      = case when r ? 'temperature' then nullif(r ->> 'temperature', '')::numeric else temperature end,
      temp_decision    = case when r ? 'temp_decision' then nullif(r ->> 'temp_decision', '') else temp_decision end,
      lot_number       = case when r ? 'lot_number' then nullif(btrim(r ->> 'lot_number'), '') else lot_number end,
      lot_tlc          = case when r ? 'lot_tlc' then nullif(btrim(r ->> 'lot_tlc'), '') else lot_tlc end,
      lot_production_date = case when r ? 'lot_production_date' then nullif(r ->> 'lot_production_date', '')::date else lot_production_date end,
      expiration_date  = case when r ? 'expiration_date' then nullif(r ->> 'expiration_date', '')::date else expiration_date end,
      best_by_date     = case when r ? 'best_by_date' then nullif(r ->> 'best_by_date', '')::date else best_by_date end,
      storage_allocations = coalesce(r -> 'storage_allocations', storage_allocations),
      notes            = case when r ? 'notes' then r ->> 'notes' else notes end
    where id = v_item.id
    returning * into v_item;

    if v_item.back_order and v_item.po_item_id is null then
      raise exception 'Only ordered items can be back ordered';
    end if;
    update public.receipt_items set exception_codes = app.receipt_item_exceptions(v_item) where id = v_item.id;
  end loop;

  -- Receipt already completed and the invoice has now arrived
  if v_r.status = 'received' and v_r.purchase_order_id is not null then
    update public.purchase_orders set status = 'ready_to_reconcile'
    where id = v_r.purchase_order_id and status in ('partially_received', 'invoice_received')
      and (select invoice_number from public.receipts where id = p_receipt) is not null;
  end if;

  return public.receipt_totals(p_receipt);
end $$;

-- Financial summary used by the UI and by posting (single source of the math).
create or replace function public.receipt_totals(p_receipt uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_r public.receipts;
  v_lines numeric; v_calc numeric; v_received_value numeric; v_tol numeric;
begin
  select * into v_r from public.receipts where id = p_receipt;
  if v_r.id is null or not (v_r.location_id in (select app.user_location_ids())) then raise exception 'Receipt not found'; end if;
  select coalesce(sum(coalesce(invoice_extended, round(coalesce(invoiced_qty, 0) * coalesce(invoice_price, 0), 2))), 0),
         coalesce(sum(round(coalesce(received_qty, 0) * coalesce(invoice_price, contract_price, 0), 2)), 0)
    into v_lines, v_received_value
  from public.receipt_items where receipt_id = p_receipt;
  v_calc := v_lines + v_r.tax + v_r.freight + v_r.fuel_surcharge + v_r.misc_fees - v_r.credits;
  select invoice_tolerance into v_tol from public.locations where id = v_r.location_id;
  return jsonb_build_object(
    'lines_total', v_lines, 'tax', v_r.tax, 'freight', v_r.freight, 'fuel_surcharge', v_r.fuel_surcharge,
    'misc_fees', v_r.misc_fees, 'credits', v_r.credits, 'calculated_total', v_calc,
    'invoice_total', v_r.invoice_total,
    'over_short', case when v_r.invoice_total is not null then v_r.invoice_total - v_calc end,
    'received_value', v_received_value, 'tolerance', v_tol,
    'within_tolerance', v_r.invoice_total is not null and abs(v_r.invoice_total - v_calc) <= v_tol,
    'exceptions', (select count(*) from public.receipt_items where receipt_id = p_receipt and exception_codes <> '{}'),
    'unreceived_lines', (select count(*) from public.receipt_items where receipt_id = p_receipt and received_qty is null)
  );
end $$;

-- Physical receiving finished (invoice may follow later).
create or replace function public.complete_receiving(p_receipt uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_r public.receipts;
begin
  select * into v_r from public.receipts where id = p_receipt for update;
  if v_r.id is null then raise exception 'Receipt not found'; end if;
  perform app.require_permission('orders.receive', v_r.location_id);
  if v_r.status <> 'draft' then raise exception 'Receipt is already %', v_r.status; end if;
  if exists (select 1 from public.receipt_items where receipt_id = p_receipt and received_qty is null) then
    raise exception 'Enter the received quantity for every line (0 if nothing arrived)';
  end if;
  update public.receipts set status = 'received', received_at = coalesce(received_at, now()), received_by = auth.uid() where id = p_receipt;
  if v_r.purchase_order_id is not null then
    update public.purchase_orders set status = case when v_r.invoice_number is not null then 'ready_to_reconcile'::public.po_status
                                                    else 'invoice_received'::public.po_status end
    where id = v_r.purchase_order_id;
  end if;
  -- Shortages / invoice differences create a reconciliation task.
  if exists (select 1 from public.receipt_items where receipt_id = p_receipt and exception_codes && array['short','missing','invoice_qty_mismatch','price_variance','over']) then
    perform app.create_task(v_r.location_id, 'Resolve delivery discrepancies: ' || v_r.receipt_number, 'invoice', now() + interval '1 day',
      'Receiving found differences between the order, the delivery and the invoice.', 'receipt', p_receipt, 'receipt:' || p_receipt);
    perform app.raise_alert(v_r.location_id, 'short_delivery', 'warning', 'Delivery discrepancies on ' || v_r.receipt_number,
      'Ordered, received and invoiced quantities do not all match.', 'receipt_exc:' || p_receipt, null, 'receipt', p_receipt);
  end if;
  perform app.audit(v_r.organization_id, v_r.location_id, 'receive', 'receipt', p_receipt::text, 'Delivery received ' || v_r.receipt_number, null, null);
end $$;

-- ---------------------------------------------------------------------
-- RECONCILE & POST (atomic): receipt txns, weighted average cost, latest
-- cost, price history, price alerts, PO status, lots, audit.
-- ---------------------------------------------------------------------
create or replace function public.post_receipt(p_receipt uuid, p_override_reason text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_r public.receipts;
  v_loc public.locations;
  v_totals jsonb;
  v_override boolean := false;
  ri public.receipt_items;
  v_base numeric; v_unit_cost numeric; v_line_value numeric;
  v_on_hand numeric; v_lp public.location_products;
  v_new_avg numeric; v_prev_cost numeric;
  v_at timestamptz;
  alloc jsonb; v_alloc_total numeric; v_alloc_base numeric; v_remaining numeric;
  v_lot uuid;
  v_value numeric := 0;
  v_lines integer := 0;
  v_price_alerts integer := 0;
  v_po_open boolean;
begin
  select * into v_r from public.receipts where id = p_receipt for update;
  if v_r.id is null then raise exception 'Receipt not found'; end if;
  perform app.require_permission('orders.reconcile', v_r.location_id);
  if v_r.status = 'posted' then raise exception 'Receipt % was already posted', v_r.receipt_number using errcode = 'P0003'; end if;
  if v_r.status = 'cancelled' then raise exception 'Receipt is cancelled'; end if;
  if v_r.invoice_number is null or v_r.invoice_total is null then
    raise exception 'Enter the invoice number and invoice total before reconciling';
  end if;
  if exists (select 1 from public.receipt_items where receipt_id = p_receipt and received_qty is null) then
    raise exception 'Every line needs a received quantity';
  end if;
  select * into v_loc from public.locations where id = v_r.location_id;

  -- Temperature failures need an explicit decision; overriding needs permission.
  if exists (select 1 from public.receipt_items where receipt_id = p_receipt and 'temp_out_of_range' = any(exception_codes) and temp_decision is null) then
    raise exception 'A received temperature is out of range. Choose Accept, Reject or Manager Override for it.';
  end if;
  if exists (select 1 from public.receipt_items where receipt_id = p_receipt and 'temp_out_of_range' = any(exception_codes) and temp_decision in ('override', 'accept'))
     and not app.has_permission('orders.reconcile_override', v_r.location_id) then
    raise exception 'Accepting product received out of temperature range requires manager override permission' using errcode = '42501';
  end if;

  v_totals := public.receipt_totals(p_receipt);
  if not (v_totals ->> 'within_tolerance')::boolean then
    if not app.has_permission('orders.reconcile_override', v_r.location_id) then
      raise exception 'Invoice is out of balance by % (tolerance %). A manager with override permission must post it.',
        v_totals ->> 'over_short', v_totals ->> 'tolerance' using errcode = '42501';
    end if;
    if coalesce(btrim(p_override_reason), '') = '' then
      raise exception 'Invoice is out of balance by %. Enter an override reason to post.', v_totals ->> 'over_short' using errcode = 'P0006';
    end if;
    v_override := true;
  end if;

  v_at := coalesce(v_r.received_at, now());

  for ri in select * from public.receipt_items where receipt_id = p_receipt order by sort loop
    -- product sent back for temperature is not received into inventory
    if ri.temp_decision = 'reject' then
      update public.receipt_items set rejected_qty = rejected_qty + coalesce(received_qty, 0), received_qty = 0 where id = ri.id returning * into ri;
      perform app.raise_alert(v_r.location_id, 'temperature_failure', 'critical',
        'Temperature failure rejected: ' || (select name from public.products where id = ri.product_id),
        format('Received at %s°F (allowed %s to %s).', ri.temperature, coalesce(ri.temp_min::text, '-'), coalesce(ri.temp_max::text, '-')),
        'temp:' || ri.id, ri.product_id, 'receipt', p_receipt);
    elsif 'temp_out_of_range' = any(ri.exception_codes) then
      perform app.raise_alert(v_r.location_id, 'temperature_failure', 'critical',
        'Temperature override: ' || (select name from public.products where id = ri.product_id),
        format('Accepted at %s°F (allowed %s to %s) by manager decision "%s".', ri.temperature, coalesce(ri.temp_min::text, '-'), coalesce(ri.temp_max::text, '-'), ri.temp_decision),
        'temp:' || ri.id, ri.product_id, 'receipt', p_receipt);
    end if;

    if coalesce(ri.received_qty, 0) > 0 then
      v_base := coalesce(ri.catch_weight_qty, round(ri.received_qty * ri.unit_factor, 4));
      -- cost per inventory unit from the invoice price (catch weight: invoice extended / actual weight)
      v_line_value := case
        when ri.catch_weight_qty is not null and ri.invoice_extended is not null then ri.invoice_extended * least(1, ri.received_qty / nullif(coalesce(ri.invoiced_qty, ri.received_qty), 0))
        else round(ri.received_qty * coalesce(ri.invoice_price, ri.contract_price, 0), 2) end;
      v_unit_cost := round(v_line_value / v_base, 6);

      -- Lot
      v_lot := null;
      if ri.lot_number is not null then
        insert into public.lots (organization_id, product_id, lot_number, traceability_lot_code, lot_source, vendor_id, production_date, expiration_date, best_by_date)
        values (v_r.organization_id, ri.product_id, ri.lot_number, ri.lot_tlc, 'receipt ' || v_r.receipt_number, v_r.vendor_id,
                ri.lot_production_date, ri.expiration_date, ri.best_by_date)
        on conflict (organization_id, product_id, lot_number) do update
          set traceability_lot_code = coalesce(excluded.traceability_lot_code, lots.traceability_lot_code),
              expiration_date = coalesce(excluded.expiration_date, lots.expiration_date)
        returning id into v_lot;
      end if;

      -- Weighted average cost (uses usable on-hand before this receipt)
      select * into v_lp from public.location_products where location_id = v_r.location_id and product_id = ri.product_id for update;
      select coalesce(on_hand, 0) into v_on_hand from public.inventory_balances where location_id = v_r.location_id and product_id = ri.product_id;
      v_on_hand := greatest(coalesce(v_on_hand, 0), 0);
      v_prev_cost := coalesce(v_lp.last_cost, nullif(v_lp.avg_cost, 0));
      v_new_avg := case when v_on_hand + v_base > 0 and v_lp.avg_cost > 0
                        then round((v_on_hand * v_lp.avg_cost + v_base * v_unit_cost) / (v_on_hand + v_base), 6)
                        else v_unit_cost end;

      -- Ledger rows, split by storage allocation (remainder -> unassigned)
      v_alloc_total := 0;
      for alloc in select * from jsonb_array_elements(ri.storage_allocations) loop
        continue when coalesce((alloc ->> 'qty')::numeric, 0) <= 0;
        v_alloc_total := v_alloc_total + (alloc ->> 'qty')::numeric;
      end loop;
      if v_alloc_total > ri.received_qty then
        raise exception 'Storage split for % is more than the received quantity', (select name from public.products where id = ri.product_id);
      end if;
      v_remaining := v_base;
      for alloc in select * from jsonb_array_elements(ri.storage_allocations) loop
        continue when coalesce((alloc ->> 'qty')::numeric, 0) <= 0;
        v_alloc_base := round(v_base * (alloc ->> 'qty')::numeric / ri.received_qty, 4);
        perform app.post_inventory_txn(v_r.location_id, ri.product_id, 'RECEIPT', v_alloc_base, v_unit_cost, v_at, 'receipt', p_receipt, ri.id,
                                       (alloc ->> 'storage_location_id')::uuid, null, coalesce(v_r.invoice_number, v_r.receipt_number), null, v_lot);
        if v_lot is not null then
          insert into public.lot_receipts (organization_id, location_id, lot_id, receipt_id, receipt_item_id, storage_location_id, quantity, received_at)
          values (v_r.organization_id, v_r.location_id, v_lot, p_receipt, ri.id, (alloc ->> 'storage_location_id')::uuid, v_alloc_base, v_at);
        end if;
        v_remaining := v_remaining - v_alloc_base;
      end loop;
      if v_remaining > 0 then
        perform app.post_inventory_txn(v_r.location_id, ri.product_id, 'RECEIPT', v_remaining, v_unit_cost, v_at, 'receipt', p_receipt, ri.id,
                                       null, null, coalesce(v_r.invoice_number, v_r.receipt_number), null, v_lot);
        if v_lot is not null then
          insert into public.lot_receipts (organization_id, location_id, lot_id, receipt_id, receipt_item_id, quantity, received_at)
          values (v_r.organization_id, v_r.location_id, v_lot, p_receipt, ri.id, v_remaining, v_at);
        end if;
      end if;

      update public.location_products set avg_cost = v_new_avg, last_cost = v_unit_cost, last_cost_at = v_at
      where id = v_lp.id;

      insert into public.price_history (organization_id, location_id, product_id, vendor_id, vendor_product_id, purchase_unit_id,
                                        unit_price, base_unit_price, effective_at, source_type, source_id, created_by)
      values (v_r.organization_id, v_r.location_id, ri.product_id, v_r.vendor_id, ri.vendor_product_id, ri.unit_id,
              round(v_unit_cost * ri.unit_factor, 4), v_unit_cost, v_at, 'invoice', p_receipt, auth.uid());

      -- latest invoice price becomes the order-guide price (contract prices are left alone)
      if ri.vendor_product_id is not null and ri.invoice_price is not null then
        update public.vendor_products set current_price = ri.invoice_price where id = ri.vendor_product_id and current_price <> ri.invoice_price;
      end if;

      if v_prev_cost is not null and v_prev_cost > 0 and v_unit_cost > v_prev_cost * (1 + v_loc.price_alert_pct / 100) then
        perform app.raise_alert(v_r.location_id, 'price_increase', 'warning',
          'Price increase: ' || (select name from public.products where id = ri.product_id),
          format('%s → %s per %s (+%s%%)', round(v_prev_cost, 2), round(v_unit_cost, 2),
                 (select u.code from public.products p join public.units u on u.id = p.inventory_unit_id where p.id = ri.product_id),
                 round((v_unit_cost / v_prev_cost - 1) * 100, 2)),
          'price:' || ri.product_id || ':' || p_receipt, ri.product_id, 'receipt', p_receipt,
          jsonb_build_object('previous', v_prev_cost, 'current', v_unit_cost));
        v_price_alerts := v_price_alerts + 1;
      end if;

      v_value := v_value + v_line_value;
      v_lines := v_lines + 1;
    end if;

    -- PO line progress & back orders
    if ri.po_item_id is not null then
      update public.purchase_order_items i set
        received_qty = i.received_qty + coalesce(ri.received_qty, 0),
        back_ordered_qty = case when ri.back_order then greatest(ri.ordered_qty - coalesce(ri.received_qty, 0), 0) else 0 end
      where i.id = ri.po_item_id;
      -- short without back order closes the line at what was received
      if not ri.back_order and coalesce(ri.received_qty, 0) < ri.ordered_qty then
        update public.purchase_order_items i set order_qty = i.received_qty where i.id = ri.po_item_id and i.received_qty < i.order_qty;
      end if;
    end if;
  end loop;

  update public.receipts set status = 'posted', posted_at = now(), posted_by = auth.uid(),
         received_at = coalesce(received_at, v_at), received_by = coalesce(received_by, auth.uid()),
         override_reason = case when v_override then p_override_reason end,
         override_by = case when v_override then auth.uid() end
  where id = p_receipt;

  if v_r.purchase_order_id is not null then
    select exists (select 1 from public.purchase_order_items where po_id = v_r.purchase_order_id and back_ordered_qty > 0) into v_po_open;
    update public.purchase_orders set status = case when v_po_open then 'back_ordered'::public.po_status else 'posted'::public.po_status end
    where id = v_r.purchase_order_id;
  end if;

  if v_override then
    perform app.raise_alert(v_r.location_id, 'invoice_difference', 'warning', 'Invoice posted out of balance: ' || v_r.invoice_number,
      format('Over/short %s. Reason: %s', v_totals ->> 'over_short', p_override_reason), 'invoice:' || p_receipt, null, 'receipt', p_receipt, v_totals);
  end if;
  perform app.complete_tasks_for(p_receipt, 'invoice');
  update public.alerts set status = 'resolved', resolved_at = now(), resolved_by = auth.uid()
    where location_id = v_r.location_id and dedupe_key = 'receipt_exc:' || p_receipt and status <> 'resolved';

  perform app.audit(v_r.organization_id, v_r.location_id, 'post', 'receipt', p_receipt::text,
    format('Reconciled and posted %s / invoice %s (%s lines, %s)', v_r.receipt_number, v_r.invoice_number, v_lines, round(v_value, 2)),
    null, v_totals || jsonb_build_object('override', v_override, 'override_reason', p_override_reason));

  return jsonb_build_object('lines', v_lines, 'inventory_value', round(v_value, 2), 'price_alerts', v_price_alerts,
                            'override', v_override, 'totals', v_totals);
end $$;

create or replace function public.cancel_receipt(p_receipt uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare v_r public.receipts;
begin
  select * into v_r from public.receipts where id = p_receipt for update;
  if v_r.id is null then raise exception 'Receipt not found'; end if;
  perform app.require_permission('orders.receive', v_r.location_id);
  if v_r.status in ('posted', 'cancelled') then raise exception 'Receipt is %', v_r.status; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'A reason is required'; end if;
  update public.receipts set status = 'cancelled', cancelled_at = now(), cancelled_by = auth.uid(), notes = concat_ws(E'\n', notes, 'Cancelled: ' || p_reason)
  where id = p_receipt;
  if v_r.purchase_order_id is not null then
    update public.purchase_orders set status = case when confirmed_at is not null then 'confirmed'::public.po_status else 'submitted'::public.po_status end
    where id = v_r.purchase_order_id and status in ('invoice_received', 'ready_to_reconcile');
  end if;
  perform app.complete_tasks_for(p_receipt, 'invoice');
end $$;

-- Recall search: every location that received a lot.
create or replace function public.search_lots(p_query text)
returns table (lot_id uuid, lot_number text, traceability_lot_code text, product_name text, vendor_name text,
               location_id uuid, location_name text, receipt_number text, quantity numeric, received_at timestamptz,
               expiration_date date, storage_name text)
language sql stable security definer set search_path = public as $$
  select l.id, l.lot_number, l.traceability_lot_code, p.name, v.name, loc.id, loc.code || ' ' || loc.name, r.receipt_number,
         lr.quantity, lr.received_at, l.expiration_date, s.name
  from public.lots l
  join public.products p on p.id = l.product_id
  left join public.vendors v on v.id = l.vendor_id
  join public.lot_receipts lr on lr.lot_id = l.id
  join public.locations loc on loc.id = lr.location_id
  left join public.receipts r on r.id = lr.receipt_id
  left join public.storage_locations s on s.id = lr.storage_location_id
  where lr.location_id in (select app.user_location_ids())
    and (l.lot_number ilike '%' || p_query || '%' or l.traceability_lot_code ilike '%' || p_query || '%')
  order by lr.received_at desc
  limit 200
$$;

select app.apply_grants();

-- ============================================================================
-- 20260930000700_user_admin.sql
-- ============================================================================
-- =====================================================================
-- USERS & PERMISSIONS administration (role grants are scoped and ranked)
-- =====================================================================

insert into app.write_protected_tables values ('organization_members'), ('user_roles'), ('role_permissions'), ('roles'), ('permissions');

-- Highest role rank the caller holds that covers a scope.
create or replace function app.caller_rank_for_scope(p_org uuid, p_scope_type public.scope_type, p_scope_id uuid) returns integer
language sql stable security definer set search_path = public as $$
  select coalesce(max(r.rank), 0)
  from public.user_roles ur
  join public.roles r on r.id = ur.role_id
  join public.role_permissions rp on rp.role_id = r.id and rp.permission_key = 'users.manage'
  join public.organization_members m on m.organization_id = ur.organization_id and m.user_id = ur.user_id and m.active
  where ur.user_id = auth.uid() and ur.organization_id = p_org
    and (
      ur.scope_type = 'organization'
      or (p_scope_type = 'location' and (
            (ur.scope_type = 'location' and ur.scope_id = p_scope_id)
         or (ur.scope_type = 'district' and ur.scope_id = (select district_id from public.locations where id = p_scope_id))
         or (ur.scope_type = 'region' and ur.scope_id = (select region_id from public.locations where id = p_scope_id))))
      or (p_scope_type = 'district' and (
            (ur.scope_type = 'district' and ur.scope_id = p_scope_id)
         or (ur.scope_type = 'region' and ur.scope_id = (select region_id from public.districts where id = p_scope_id))))
      or (p_scope_type = 'region' and ur.scope_type = 'region' and ur.scope_id = p_scope_id)
    )
$$;

create or replace function public.assign_role(p_org uuid, p_user uuid, p_role_key text, p_scope_type public.scope_type, p_scope_id uuid)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_role public.roles;
  v_rank integer;
  v_id uuid;
  v_scope uuid := case when p_scope_type = 'organization' then p_org else p_scope_id end;
begin
  if auth.uid() is null then raise exception 'Not signed in' using errcode = '42501'; end if;
  select * into v_role from public.roles where key = p_role_key and (organization_id is null or organization_id = p_org)
  order by organization_id nulls last limit 1;
  if v_role.id is null then raise exception 'Unknown role %', p_role_key; end if;
  -- scope must belong to the organization
  if p_scope_type = 'location' and not exists (select 1 from public.locations where id = v_scope and organization_id = p_org) then
    raise exception 'Location not in organization';
  elsif p_scope_type = 'district' and not exists (select 1 from public.districts where id = v_scope and organization_id = p_org) then
    raise exception 'District not in organization';
  elsif p_scope_type = 'region' and not exists (select 1 from public.regions where id = v_scope and organization_id = p_org) then
    raise exception 'Region not in organization';
  end if;
  v_rank := app.caller_rank_for_scope(p_org, p_scope_type, v_scope);
  if v_rank = 0 then raise exception 'Permission denied: users.manage is required for this scope' using errcode = '42501'; end if;
  if v_role.rank >= v_rank and v_rank < 100 then
    raise exception 'You can only grant roles below your own (%)', v_role.name using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = p_user) then raise exception 'User not found'; end if;

  insert into public.organization_members (organization_id, user_id) values (p_org, p_user)
  on conflict (organization_id, user_id) do update set active = true;
  insert into public.user_roles (organization_id, user_id, role_id, scope_type, scope_id, created_by)
  values (p_org, p_user, v_role.id, p_scope_type, v_scope, auth.uid())
  on conflict (user_id, role_id, scope_type, scope_id) do nothing
  returning id into v_id;
  perform app.audit(p_org, case when p_scope_type = 'location' then v_scope end, 'grant_role', 'user', p_user::text,
    format('Granted %s (%s)', v_role.name, p_scope_type), null,
    jsonb_build_object('role', p_role_key, 'scope_type', p_scope_type, 'scope_id', v_scope));
  return v_id;
end $$;

create or replace function public.revoke_role(p_user_role uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_ur public.user_roles;
  v_role public.roles;
  v_rank integer;
begin
  select * into v_ur from public.user_roles where id = p_user_role;
  if v_ur.id is null then raise exception 'Role assignment not found'; end if;
  select * into v_role from public.roles where id = v_ur.role_id;
  v_rank := app.caller_rank_for_scope(v_ur.organization_id, v_ur.scope_type, v_ur.scope_id);
  if v_rank = 0 or (v_role.rank >= v_rank and v_rank < 100) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if v_role.key = 'system_owner' and (select count(*) from public.user_roles ur join public.roles r on r.id = ur.role_id
                                      where ur.organization_id = v_ur.organization_id and r.key = 'system_owner') <= 1 then
    raise exception 'The organization must keep at least one System Owner';
  end if;
  delete from public.user_roles where id = p_user_role;
  perform app.audit(v_ur.organization_id, case when v_ur.scope_type = 'location' then v_ur.scope_id end, 'revoke_role', 'user',
    v_ur.user_id::text, 'Revoked ' || v_role.name, jsonb_build_object('role', v_role.key, 'scope_type', v_ur.scope_type, 'scope_id', v_ur.scope_id), null);
end $$;

create or replace function public.set_member_active(p_org uuid, p_user uuid, p_active boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform app.require_org_permission('users.manage', p_org);
  if p_user = auth.uid() and not p_active then raise exception 'You cannot deactivate yourself'; end if;
  update public.organization_members set active = p_active where organization_id = p_org and user_id = p_user;
  perform app.audit(p_org, null, case when p_active then 'activate' else 'deactivate' end, 'user', p_user::text, null, null, null);
end $$;

-- Directory of people for the Users screen.
create or replace function public.list_org_users(p_org uuid)
returns table (user_id uuid, email text, full_name text, active boolean, employee_number text, roles jsonb)
language sql stable security definer set search_path = public as $$
  select m.user_id, p.email, p.full_name, m.active, m.employee_number,
         coalesce((select jsonb_agg(jsonb_build_object('id', ur.id, 'role', r.key, 'name', r.name, 'rank', r.rank, 'scope_type', ur.scope_type, 'scope_id', ur.scope_id,
                                                      'scope_name', case ur.scope_type when 'organization' then 'All locations'
                                                                     when 'location' then (select code || ' ' || name from public.locations where id = ur.scope_id)
                                                                     when 'district' then (select name from public.districts where id = ur.scope_id)
                                                                     when 'region' then (select name from public.regions where id = ur.scope_id) end)
                                   order by r.rank desc)
                   from public.user_roles ur join public.roles r on r.id = ur.role_id
                   where ur.user_id = m.user_id and ur.organization_id = p_org), '[]'::jsonb)
  from public.organization_members m join public.profiles p on p.id = m.user_id
  where m.organization_id = p_org and app.has_any_permission('users.manage', p_org)
  order by m.active desc, p.full_name
$$;

select app.apply_grants();

-- ============================================================================
-- 20260930000800_catalog_rpcs.sql
-- ============================================================================
-- =====================================================================
-- Catalog RPCs: atomic product creation, stock card, global search
-- =====================================================================

-- Creates a product with its purchase conversion, optional vendor item,
-- storage placement and local par in one transaction.
-- p: {product_number, name, description, category_id, inventory_unit_id, recipe_unit_id, purchase_unit_id,
--     purchase_factor, count_unit_id, count_factor, brand, sku, manufacturer_number, default_vendor_id,
--     vendor_item_number, vendor_price, pack_size, shelf_life_days, lot_tracked, expiration_tracked, catch_weight,
--     taxable, gl_account, receiving_temp_min, receiving_temp_max, notes, storage_location_id, shelf, par_qty,
--     location_id, standard_cost, upc}
create or replace function public.create_product(p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_loc uuid := (p ->> 'location_id')::uuid;
  v_org uuid := app.location_org((p ->> 'location_id')::uuid);
  v_id uuid;
  v_inv uuid := (p ->> 'inventory_unit_id')::uuid;
  v_pu uuid := nullif(p ->> 'purchase_unit_id', '')::uuid;
  v_cu uuid := nullif(p ->> 'count_unit_id', '')::uuid;
  v_vendor uuid := nullif(p ->> 'default_vendor_id', '')::uuid;
begin
  perform app.require_org_permission('products.edit', v_org);
  if coalesce(btrim(p ->> 'name'), '') = '' or coalesce(btrim(p ->> 'product_number'), '') = '' then
    raise exception 'Product number and name are required';
  end if;
  insert into public.products (organization_id, product_number, name, description, category_id, inventory_unit_id, recipe_unit_id,
      purchase_unit_id, sku, brand, manufacturer_number, default_vendor_id, standard_cost, shelf_life_days, lot_tracked, expiration_tracked,
      catch_weight, taxable, gl_account, receiving_temp_min, receiving_temp_max, notes, is_prepped, created_by)
  values (v_org, btrim(p ->> 'product_number'), btrim(p ->> 'name'), nullif(p ->> 'description', ''), nullif(p ->> 'category_id', '')::uuid,
      v_inv, nullif(p ->> 'recipe_unit_id', '')::uuid, v_pu, nullif(p ->> 'sku', ''), nullif(p ->> 'brand', ''),
      nullif(p ->> 'manufacturer_number', ''), v_vendor, nullif(p ->> 'standard_cost', '')::numeric, nullif(p ->> 'shelf_life_days', '')::int,
      coalesce((p ->> 'lot_tracked')::boolean, false), coalesce((p ->> 'expiration_tracked')::boolean, false),
      coalesce((p ->> 'catch_weight')::boolean, false), coalesce((p ->> 'taxable')::boolean, false), nullif(p ->> 'gl_account', ''),
      nullif(p ->> 'receiving_temp_min', '')::numeric, nullif(p ->> 'receiving_temp_max', '')::numeric, nullif(p ->> 'notes', ''),
      coalesce((p ->> 'is_prepped')::boolean, false), auth.uid())
  returning id into v_id;

  if v_pu is not null and v_pu <> v_inv and nullif(p ->> 'purchase_factor', '') is not null then
    insert into public.product_units (organization_id, product_id, unit_id, factor, use_for_count, use_for_purchase, label)
    values (v_org, v_id, v_pu, (p ->> 'purchase_factor')::numeric, true, true, nullif(p ->> 'pack_size', ''));
  end if;
  if v_cu is not null and v_cu <> v_inv and v_cu is distinct from v_pu and nullif(p ->> 'count_factor', '') is not null then
    insert into public.product_units (organization_id, product_id, unit_id, factor, use_for_count)
    values (v_org, v_id, v_cu, (p ->> 'count_factor')::numeric, true);
  end if;

  if v_vendor is not null and nullif(p ->> 'vendor_item_number', '') is not null then
    insert into public.vendor_products (organization_id, vendor_id, product_id, vendor_item_number, purchase_unit_id, pack_size, current_price, is_preferred)
    values (v_org, v_vendor, v_id, btrim(p ->> 'vendor_item_number'), coalesce(v_pu, v_inv), nullif(p ->> 'pack_size', ''),
            coalesce(nullif(p ->> 'vendor_price', '')::numeric, 0), true);
  end if;

  if nullif(p ->> 'upc', '') is not null then
    insert into public.product_barcodes (organization_id, product_id, barcode, unit_id, created_by)
    values (v_org, v_id, btrim(p ->> 'upc'), null, auth.uid());
  end if;

  if nullif(p ->> 'storage_location_id', '') is not null then
    if not exists (select 1 from public.storage_locations where id = (p ->> 'storage_location_id')::uuid and location_id = v_loc) then
      raise exception 'Storage area does not belong to this location';
    end if;
    insert into public.product_storage_locations (organization_id, location_id, product_id, storage_location_id, shelf, sort_order)
    values (v_org, v_loc, v_id, (p ->> 'storage_location_id')::uuid, nullif(p ->> 'shelf', ''),
            coalesce((select max(sort_order) + 1 from public.product_storage_locations where storage_location_id = (p ->> 'storage_location_id')::uuid), 1));
  end if;
  if nullif(p ->> 'par_qty', '') is not null then
    update public.location_products set par_qty = (p ->> 'par_qty')::numeric where location_id = v_loc and product_id = v_id;
  end if;
  return v_id;
end $$;

-- Stock card: every ledger movement with running quantity and value.
create or replace function public.stock_card(p_location uuid, p_product uuid, p_from timestamptz, p_to timestamptz)
returns table (
  id bigint, txn_at timestamptz, business_date date, txn_type public.inv_txn_type, quantity numeric, unit_cost numeric,
  extended_cost numeric, running_qty numeric, running_value numeric, reference text, source_type text, source_id uuid,
  storage_name text, reason_code text, notes text, created_by_name text, is_opening boolean
)
language sql stable security definer set search_path = public as $$
  with allowed as (select 1 where p_location in (select app.user_location_ids())),
  opening as (
    select coalesce(sum(t.quantity), 0) as qty, coalesce(sum(t.extended_cost), 0) as val
    from public.inventory_transactions t, allowed
    where t.location_id = p_location and t.product_id = p_product and t.txn_at < p_from
  ),
  mv as (
    select t.*, s.name as storage_name, pr.full_name
    from public.inventory_transactions t
    cross join allowed
    left join public.storage_locations s on s.id = t.storage_location_id
    left join public.profiles pr on pr.id = t.created_by
    where t.location_id = p_location and t.product_id = p_product and t.txn_at >= p_from and t.txn_at <= p_to
  )
  select null::bigint, p_from, null::date, 'BEGINNING'::public.inv_txn_type, o.qty, case when o.qty <> 0 then round(o.val / o.qty, 6) else 0 end,
         o.val, o.qty, o.val, 'Opening balance', null, null, null, null, null, null, true
  from opening o, allowed
  union all
  select m.id, m.txn_at, m.business_date, m.txn_type, m.quantity, m.unit_cost, m.extended_cost,
         (select qty from opening) + sum(m.quantity) over (order by m.txn_at, m.id),
         (select val from opening) + sum(m.extended_cost) over (order by m.txn_at, m.id),
         m.reference, m.source_type, m.source_id, m.storage_name, m.reason_code, m.notes, m.full_name, false
  from mv m
  order by 2, 1 nulls first
$$;

-- Global search across the operational records a user can see.
create or replace function public.global_search(p_q text, p_location uuid)
returns table (kind text, id uuid, title text, subtitle text, href text)
language plpgsql stable security definer set search_path = public as $$
declare v_q text := btrim(coalesce(p_q, ''));
begin
  if length(v_q) < 2 or not (p_location in (select app.user_location_ids())) then return; end if;
  return query
  (select 'Product', pr.id, pr.name, concat_ws(' · ', '#' || pr.product_number, pr.sku, pr.brand), '/inventory/items/' || pr.id
   from public.products pr
   where pr.organization_id = app.location_org(p_location) and pr.deleted_at is null
     and (pr.name ilike '%' || v_q || '%' or pr.product_number ilike v_q || '%' or pr.sku ilike '%' || v_q || '%' or pr.manufacturer_number ilike v_q
          or exists (select 1 from public.product_barcodes b where b.product_id = pr.id and b.barcode = v_q)
          or exists (select 1 from public.vendor_products vp where vp.product_id = pr.id and vp.vendor_item_number ilike v_q || '%'))
   order by extensions.similarity(pr.name, v_q) desc limit 15)
  union all
  (select 'Vendor', v.id, v.name, concat_ws(' · ', v.vendor_number, v.account_number), '/vendors/' || v.id
   from public.vendors v where v.organization_id = app.location_org(p_location) and (v.name ilike '%' || v_q || '%' or v.vendor_number ilike v_q || '%') limit 5)
  union all
  (select 'Purchase order', po.id, po.po_number, concat_ws(' · ', v.name, po.status::text, po.expected_delivery_date::text), '/purchasing/' || po.id
   from public.purchase_orders po join public.vendors v on v.id = po.vendor_id
   where po.location_id = p_location and (po.po_number ilike '%' || v_q || '%' or po.confirmation_number ilike v_q) limit 10)
  union all
  (select 'Invoice / receipt', r.id, coalesce(r.invoice_number, r.receipt_number), concat_ws(' · ', v.name, r.receipt_number, r.status::text), '/receiving/' || r.id
   from public.receipts r join public.vendors v on v.id = r.vendor_id
   where r.location_id = p_location and (r.invoice_number ilike '%' || v_q || '%' or r.receipt_number ilike '%' || v_q || '%') limit 10)
  union all
  (select 'Count', c.id, c.name, concat_ws(' · ', c.count_number, c.status::text), '/counts/' || c.id || '/review'
   from public.count_sessions c where c.location_id = p_location and (c.count_number ilike '%' || v_q || '%' or c.name ilike '%' || v_q || '%') limit 5)
  union all
  (select 'Lot', l.id, l.lot_number, concat_ws(' · ', pr.name, l.traceability_lot_code), '/reports?r=lots&q=' || l.lot_number
   from public.lots l join public.products pr on pr.id = l.product_id
   where l.organization_id = app.location_org(p_location) and (l.lot_number ilike '%' || v_q || '%' or l.traceability_lot_code ilike '%' || v_q || '%') limit 5)
  union all
  (select 'Location', loc.id, '#' || loc.code || ' ' || loc.name, concat_ws(', ', loc.city, loc.state), '/admin/locations/' || loc.id
   from public.locations loc where loc.id in (select app.user_location_ids()) and (loc.name ilike '%' || v_q || '%' or loc.code ilike v_q || '%') limit 5)
  union all
  (select 'Transaction', t.txn_uid, t.txn_type::text || ' ' || t.quantity::text, concat_ws(' · ', pr.name, t.reference, t.business_date::text), '/inventory/items/' || t.product_id || '?tab=stock'
   from public.inventory_transactions t join public.products pr on pr.id = t.product_id
   where t.location_id = p_location and (t.reference ilike v_q or (v_q ~ '^\d+$' and t.id = v_q::bigint)) limit 5);
end $$;

select app.apply_grants();

-- ============================================================================
-- 20260930001000_waste_transfers.sql
-- ============================================================================
-- =====================================================================
-- PHASE 4: WASTE and TRANSFERS (storage-to-storage and location-to-location)
-- (Recipe waste is added by the recipes migration, which redefines log_waste.)
-- =====================================================================

create table public.waste_logs (
  id               uuid primary key default gen_random_uuid(),
  organization_id  uuid not null references public.organizations(id),
  location_id      uuid not null references public.locations(id),
  product_id       uuid references public.products(id),
  recipe_id        uuid,   -- FK added with recipes
  quantity         numeric(18,4) not null check (quantity > 0),
  unit_id          uuid not null references public.units(id),
  storage_location_id uuid references public.storage_locations(id),
  reason_code      text not null,
  comment          text,
  photo_url        text,
  total_cost       numeric(18,4) not null default 0,
  wasted_at        timestamptz not null,
  business_date    date not null,
  logged_by        uuid references public.profiles(id),
  client_key       uuid unique,
  created_at       timestamptz not null default now(),
  check ((product_id is null) <> (recipe_id is null))
);
create index on public.waste_logs (location_id, business_date desc);
create trigger trg_waste_immutable before update or delete on public.waste_logs for each row execute function app.prevent_mutation();

create type public.transfer_type as enum ('storage', 'location');
create type public.transfer_status as enum ('draft', 'sent', 'in_transit', 'received', 'reconciled', 'cancelled');

create table public.inventory_transfers (
  id                uuid primary key default gen_random_uuid(),
  organization_id   uuid not null references public.organizations(id),
  transfer_number   text not null,
  transfer_type     public.transfer_type not null,
  status            public.transfer_status not null default 'draft',
  from_location_id  uuid not null references public.locations(id),
  to_location_id    uuid not null references public.locations(id),
  from_storage_id   uuid references public.storage_locations(id),
  to_storage_id     uuid references public.storage_locations(id),
  transfer_at       timestamptz,
  notes             text,
  client_key        uuid unique,
  created_by        uuid references public.profiles(id),
  sent_by           uuid references public.profiles(id),
  sent_at           timestamptz,
  received_by       uuid references public.profiles(id),
  received_at       timestamptz,
  reconciled_by     uuid references public.profiles(id),
  reconciled_at     timestamptz,
  cancelled_at      timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (organization_id, transfer_number),
  check (transfer_type <> 'storage' or (from_location_id = to_location_id and from_storage_id is not null and to_storage_id is not null and from_storage_id <> to_storage_id)),
  check (transfer_type <> 'location' or from_location_id <> to_location_id)
);
create index on public.inventory_transfers (from_location_id, status);
create index on public.inventory_transfers (to_location_id, status);
create trigger trg_transfers_touch before update on public.inventory_transfers for each row execute function app.touch_updated_at();

create table public.inventory_transfer_items (
  id            uuid primary key default gen_random_uuid(),
  transfer_id   uuid not null references public.inventory_transfers(id) on delete cascade,
  product_id    uuid not null references public.products(id),
  unit_id       uuid not null references public.units(id),
  unit_factor   numeric(24,10) not null,
  qty_sent      numeric(18,4) not null check (qty_sent > 0),
  qty_received  numeric(18,4) check (qty_received is null or qty_received >= 0),
  unit_cost     numeric(18,6),     -- per inventory unit, fixed when sent
  unique (transfer_id, product_id, unit_id)
);

insert into app.write_protected_tables values ('waste_logs'), ('inventory_transfers'), ('inventory_transfer_items');

alter table public.waste_logs enable row level security;
alter table public.inventory_transfers enable row level security;
alter table public.inventory_transfer_items enable row level security;
create policy waste_select on public.waste_logs for select to authenticated using (location_id in (select app.user_location_ids()));
create policy transfers_select on public.inventory_transfers for select to authenticated
  using (from_location_id in (select app.user_location_ids()) or to_location_id in (select app.user_location_ids()));
create policy transfer_items_select on public.inventory_transfer_items for select to authenticated
  using (transfer_id in (select id from public.inventory_transfers));

-- ---------------------------------------------------------------------
-- Product waste
-- ---------------------------------------------------------------------
create or replace function public.log_waste(
  p_location uuid, p_product uuid, p_qty numeric, p_unit uuid, p_reason text,
  p_storage uuid default null, p_comment text default null, p_photo text default null,
  p_at timestamptz default null, p_client_key uuid default null, p_recipe uuid default null
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_org uuid := app.location_org(p_location);
  v_id uuid; v_base numeric; v_cost numeric; v_at timestamptz := least(coalesce(p_at, now()), now());
  v_reason public.adjustment_reasons;
begin
  perform app.require_permission('waste.log', p_location);
  if p_client_key is not null then
    select id into v_id from public.waste_logs where client_key = p_client_key;
    if v_id is not null then return jsonb_build_object('id', v_id, 'duplicate', true); end if;
  end if;
  if p_recipe is not null then raise exception 'Recipe waste requires the recipes module'; end if;
  select * into v_reason from public.adjustment_reasons where organization_id = v_org and kind = 'waste' and code = p_reason and active;
  if v_reason.id is null then raise exception 'Unknown waste reason'; end if;
  if v_reason.requires_comment and coalesce(btrim(p_comment), '') = '' then raise exception 'A comment is required for "%"', v_reason.name; end if;
  if coalesce(p_qty, 0) <= 0 then raise exception 'Waste quantity must be greater than zero'; end if;
  if v_at < now() - interval '7 days' and not app.has_permission('inventory.adjust', p_location) then
    raise exception 'Waste older than 7 days must be entered by a manager';
  end if;
  v_base := app.to_base_qty(p_product, p_qty, p_unit);
  v_cost := app.current_unit_cost(p_location, p_product);
  insert into public.waste_logs (organization_id, location_id, product_id, quantity, unit_id, storage_location_id, reason_code, comment, photo_url,
                                 total_cost, wasted_at, business_date, logged_by, client_key)
  values (v_org, p_location, p_product, p_qty, p_unit, p_storage, p_reason, p_comment, p_photo, round(v_base * v_cost, 4), v_at,
          app.business_date(p_location, v_at), auth.uid(), p_client_key)
  returning id into v_id;
  perform app.post_inventory_txn(p_location, p_product, 'WASTE', -v_base, v_cost, v_at, 'waste', v_id, null, p_storage, p_reason, null, p_comment);
  perform app.audit(v_org, p_location, 'waste', 'product', p_product::text,
    format('Wasted %s %s %s (%s)', p_qty, (select code from public.units where id = p_unit), (select name from public.products where id = p_product), v_reason.name),
    null, jsonb_build_object('waste_id', v_id, 'base_qty', v_base, 'cost', round(v_base * v_cost, 2)));
  return jsonb_build_object('id', v_id, 'cost', round(v_base * v_cost, 2), 'base_qty', v_base);
end $$;

-- ---------------------------------------------------------------------
-- Storage transfer (immediate, same location): OUT of one area, IN to another
-- ---------------------------------------------------------------------
-- p_lines: [{product_id, unit_id, qty}]
create or replace function public.transfer_between_storage(p_location uuid, p_from uuid, p_to uuid, p_lines jsonb, p_notes text default null, p_client_key uuid default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_org uuid := app.location_org(p_location);
  v_id uuid; r jsonb; v_base numeric; v_cost numeric; v_factor numeric; v_at timestamptz := now();
begin
  perform app.require_permission('inventory.transfer', p_location);
  if p_client_key is not null then
    select id into v_id from public.inventory_transfers where client_key = p_client_key;
    if v_id is not null then return v_id; end if;
  end if;
  if not exists (select 1 from public.storage_locations where id = p_from and location_id = p_location)
     or not exists (select 1 from public.storage_locations where id = p_to and location_id = p_location) then
    raise exception 'Both storage areas must belong to this location';
  end if;
  insert into public.inventory_transfers (organization_id, transfer_number, transfer_type, status, from_location_id, to_location_id, from_storage_id, to_storage_id,
                                          transfer_at, notes, client_key, created_by, sent_by, sent_at, received_by, received_at, reconciled_by, reconciled_at)
  values (v_org, app.next_doc_number(v_org, 'TRF'), 'storage', 'reconciled', p_location, p_location, p_from, p_to, v_at, p_notes, p_client_key,
          auth.uid(), auth.uid(), v_at, auth.uid(), v_at, auth.uid(), v_at)
  returning id into v_id;
  for r in select * from jsonb_array_elements(p_lines) loop
    continue when coalesce((r ->> 'qty')::numeric, 0) <= 0;
    v_factor := app.unit_factor((r ->> 'product_id')::uuid, (r ->> 'unit_id')::uuid);
    if v_factor is null then raise exception 'No unit conversion' using errcode = '22023'; end if;
    v_base := round((r ->> 'qty')::numeric * v_factor, 4);
    v_cost := app.current_unit_cost(p_location, (r ->> 'product_id')::uuid);
    insert into public.inventory_transfer_items (transfer_id, product_id, unit_id, unit_factor, qty_sent, qty_received, unit_cost)
    values (v_id, (r ->> 'product_id')::uuid, (r ->> 'unit_id')::uuid, v_factor, (r ->> 'qty')::numeric, (r ->> 'qty')::numeric, v_cost);
    perform app.post_inventory_txn(p_location, (r ->> 'product_id')::uuid, 'TRANSFER_OUT', -v_base, v_cost, v_at, 'transfer', v_id, null, p_from);
    perform app.post_inventory_txn(p_location, (r ->> 'product_id')::uuid, 'TRANSFER_IN', v_base, v_cost, v_at, 'transfer', v_id, null, p_to);
  end loop;
  if not exists (select 1 from public.inventory_transfer_items where transfer_id = v_id) then raise exception 'Add at least one item'; end if;
  perform app.audit(v_org, p_location, 'transfer', 'inventory_transfer', v_id::text, 'Storage transfer', null, p_lines);
  return v_id;
end $$;

-- ---------------------------------------------------------------------
-- Location transfer: DRAFT -> SENT/IN TRANSIT (sender loses stock) ->
-- RECEIVED -> RECONCILED (receiver gains stock)
-- ---------------------------------------------------------------------
create or replace function public.create_location_transfer(p_from uuid, p_to uuid, p_lines jsonb, p_notes text default null, p_client_key uuid default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare v_org uuid := app.location_org(p_from); v_id uuid; r jsonb; v_factor numeric;
begin
  perform app.require_permission('inventory.transfer', p_from);
  if app.location_org(p_to) is distinct from v_org then raise exception 'Destination must be in the same organization'; end if;
  if p_client_key is not null then
    select id into v_id from public.inventory_transfers where client_key = p_client_key;
    if v_id is not null then return v_id; end if;
  end if;
  insert into public.inventory_transfers (organization_id, transfer_number, transfer_type, from_location_id, to_location_id, notes, client_key, created_by)
  values (v_org, app.next_doc_number(v_org, 'TRF'), 'location', p_from, p_to, p_notes, p_client_key, auth.uid()) returning id into v_id;
  for r in select * from jsonb_array_elements(p_lines) loop
    continue when coalesce((r ->> 'qty')::numeric, 0) <= 0;
    v_factor := app.unit_factor((r ->> 'product_id')::uuid, (r ->> 'unit_id')::uuid);
    if v_factor is null then raise exception 'No unit conversion' using errcode = '22023'; end if;
    insert into public.inventory_transfer_items (transfer_id, product_id, unit_id, unit_factor, qty_sent)
    values (v_id, (r ->> 'product_id')::uuid, (r ->> 'unit_id')::uuid, v_factor, (r ->> 'qty')::numeric);
  end loop;
  if not exists (select 1 from public.inventory_transfer_items where transfer_id = v_id) then raise exception 'Add at least one item'; end if;
  return v_id;
end $$;

create or replace function public.send_transfer(p_transfer uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_t public.inventory_transfers; i record; v_cost numeric; v_at timestamptz := now();
begin
  select * into v_t from public.inventory_transfers where id = p_transfer for update;
  if v_t.id is null then raise exception 'Transfer not found'; end if;
  perform app.require_permission('inventory.transfer', v_t.from_location_id);
  if v_t.status <> 'draft' then raise exception 'Transfer % was already %', v_t.transfer_number, v_t.status using errcode = 'P0003'; end if;
  for i in select * from public.inventory_transfer_items where transfer_id = p_transfer loop
    v_cost := app.current_unit_cost(v_t.from_location_id, i.product_id);
    update public.inventory_transfer_items set unit_cost = v_cost where id = i.id;
    perform app.post_inventory_txn(v_t.from_location_id, i.product_id, 'TRANSFER_OUT', -round(i.qty_sent * i.unit_factor, 4), v_cost, v_at,
                                   'transfer', p_transfer, i.id, null, null, v_t.transfer_number);
  end loop;
  update public.inventory_transfers set status = 'in_transit', sent_at = v_at, sent_by = auth.uid(), transfer_at = v_at where id = p_transfer;
  perform app.create_task(v_t.to_location_id, 'Receive transfer ' || v_t.transfer_number, 'receive', v_at + interval '1 day',
                          'Inventory is in transit from another location.', 'inventory_transfer', p_transfer, 'transfer:' || p_transfer);
  perform app.audit(v_t.organization_id, v_t.from_location_id, 'send', 'inventory_transfer', p_transfer::text, 'Transfer sent ' || v_t.transfer_number, null, null);
end $$;

-- p_lines: [{id, qty_received}]; reconciles (posts TRANSFER_IN) when p_reconcile
create or replace function public.receive_transfer(p_transfer uuid, p_lines jsonb, p_reconcile boolean default true) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_t public.inventory_transfers; r jsonb; i record; v_at timestamptz := now();
  v_base numeric; v_lp public.location_products; v_on numeric; v_short numeric := 0;
begin
  select * into v_t from public.inventory_transfers where id = p_transfer for update;
  if v_t.id is null then raise exception 'Transfer not found'; end if;
  perform app.require_permission('inventory.transfer', v_t.to_location_id);
  if v_t.status not in ('in_transit', 'sent', 'received') then raise exception 'Transfer % is %', v_t.transfer_number, v_t.status using errcode = 'P0003'; end if;
  for r in select * from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) loop
    update public.inventory_transfer_items set qty_received = (r ->> 'qty_received')::numeric
    where id = (r ->> 'id')::uuid and transfer_id = p_transfer;
  end loop;
  update public.inventory_transfers set status = 'received', received_at = v_at, received_by = auth.uid() where id = p_transfer;
  if not p_reconcile then return jsonb_build_object('status', 'received'); end if;
  if exists (select 1 from public.inventory_transfer_items where transfer_id = p_transfer and qty_received is null) then
    raise exception 'Enter the received quantity for every line';
  end if;
  for i in select * from public.inventory_transfer_items where transfer_id = p_transfer loop
    continue when i.qty_received = 0;
    v_base := round(i.qty_received * i.unit_factor, 4);
    -- weighted average cost at the receiving location
    select * into v_lp from public.location_products where location_id = v_t.to_location_id and product_id = i.product_id for update;
    select greatest(coalesce(on_hand, 0), 0) into v_on from public.inventory_balances where location_id = v_t.to_location_id and product_id = i.product_id;
    v_on := coalesce(v_on, 0);
    update public.location_products set
      avg_cost = case when v_on + v_base > 0 and avg_cost > 0 then round((v_on * avg_cost + v_base * i.unit_cost) / (v_on + v_base), 6) else i.unit_cost end
    where id = v_lp.id;
    perform app.post_inventory_txn(v_t.to_location_id, i.product_id, 'TRANSFER_IN', v_base, i.unit_cost, v_at, 'transfer', p_transfer, i.id, null, null, v_t.transfer_number);
    v_short := v_short + greatest(i.qty_sent - i.qty_received, 0) * i.unit_factor * i.unit_cost;
  end loop;
  update public.inventory_transfers set status = 'reconciled', reconciled_at = v_at, reconciled_by = auth.uid() where id = p_transfer;
  perform app.complete_tasks_for(p_transfer, 'receive');
  perform app.audit(v_t.organization_id, v_t.to_location_id, 'reconcile', 'inventory_transfer', p_transfer::text,
    format('Transfer %s received (shortage value %s)', v_t.transfer_number, round(v_short, 2)), null, null);
  return jsonb_build_object('status', 'reconciled', 'shortage_value', round(v_short, 2));
end $$;

create or replace function public.cancel_transfer(p_transfer uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_t public.inventory_transfers;
begin
  select * into v_t from public.inventory_transfers where id = p_transfer for update;
  perform app.require_permission('inventory.transfer', v_t.from_location_id);
  if v_t.status <> 'draft' then raise exception 'Only draft transfers can be cancelled'; end if;
  update public.inventory_transfers set status = 'cancelled', cancelled_at = now() where id = p_transfer;
end $$;

-- In-transit quantity for count review (inbound location transfers not yet reconciled)
create or replace function app.in_transit_qty(p_location uuid, p_product uuid) returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce(sum(i.qty_sent * i.unit_factor), 0)
  from public.inventory_transfer_items i join public.inventory_transfers t on t.id = i.transfer_id
  where t.to_location_id = p_location and i.product_id = p_product and t.status in ('sent', 'in_transit', 'received')
$$;

select app.apply_grants();

-- ============================================================================
-- 20260930001100_recipes_sales_foodcost.sql
-- ============================================================================
-- =====================================================================
-- PHASES 5-6: recipes (nested), production, recipe waste, menu items,
-- POS sales import (adapter-neutral), theoretical usage, food cost and
-- actual-vs-theoretical analysis.
-- =====================================================================

create type public.recipe_type as enum ('menu_item', 'prep', 'sub_recipe', 'batch');

create table public.recipes (
  id               uuid primary key default gen_random_uuid(),
  organization_id  uuid not null references public.organizations(id) on delete cascade,
  name             text not null check (length(btrim(name)) > 0),
  recipe_type      public.recipe_type not null default 'menu_item',
  yield_qty        numeric(18,4) not null default 1 check (yield_qty > 0),
  yield_unit_id    uuid not null references public.units(id),
  product_id       uuid unique references public.products(id),  -- output product for prepped/inventoried recipes
  serving_size     text,
  instructions     text,
  prep_loss_pct    numeric(6,2) not null default 0 check (prep_loss_pct >= 0 and prep_loss_pct < 100),
  shelf_life_hours integer,
  active           boolean not null default true,
  created_by       uuid references public.profiles(id),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (organization_id, name)
);
create trigger trg_recipes_touch before update on public.recipes for each row execute function app.touch_updated_at();
create trigger trg_recipes_audit after insert or update on public.recipes for each row execute function app.audit_row();

create table public.recipe_ingredients (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  recipe_id       uuid not null references public.recipes(id) on delete cascade,
  product_id      uuid references public.products(id),
  sub_recipe_id   uuid references public.recipes(id),
  quantity        numeric(18,4) not null check (quantity > 0),
  unit_id         uuid not null references public.units(id),
  yield_pct       numeric(6,2) not null default 100 check (yield_pct > 0 and yield_pct <= 100),  -- usable yield (trim loss)
  sort            integer not null default 0,
  notes           text,
  created_at      timestamptz not null default now(),
  check ((product_id is null) <> (sub_recipe_id is null)),
  check (sub_recipe_id is null or sub_recipe_id <> recipe_id)
);
create index on public.recipe_ingredients (recipe_id);
create index on public.recipe_ingredients (sub_recipe_id);
create index on public.recipe_ingredients (product_id);

-- Multiplier that converts p_qty of p_unit into the sub-recipe's yield units.
create or replace function app.recipe_unit_factor(p_recipe uuid, p_unit uuid) returns numeric
language plpgsql stable security definer set search_path = public as $$
declare v_r public.recipes; a numeric; b numeric; ua public.units; ub public.units;
begin
  select * into v_r from public.recipes where id = p_recipe;
  if p_unit = v_r.yield_unit_id then return 1; end if;
  if v_r.product_id is not null then
    a := app.unit_factor(v_r.product_id, p_unit); b := app.unit_factor(v_r.product_id, v_r.yield_unit_id);
    if a is not null and b is not null then return a / b; end if;
  end if;
  select * into ua from public.units where id = p_unit;
  select * into ub from public.units where id = v_r.yield_unit_id;
  if ua.dimension = ub.dimension and ua.std_factor is not null and ub.std_factor is not null then return ua.std_factor / ub.std_factor; end if;
  return null;
end $$;

create or replace function app.recipe_ingredients_guard() returns trigger
language plpgsql as $$
begin
  if new.product_id is not null and app.unit_factor(new.product_id, new.unit_id) is null then
    raise exception 'Unit % has no conversion for %', (select code from public.units where id = new.unit_id), (select name from public.products where id = new.product_id) using errcode = '22023';
  end if;
  if new.sub_recipe_id is not null then
    if app.recipe_unit_factor(new.sub_recipe_id, new.unit_id) is null then
      raise exception 'Unit has no conversion for sub-recipe %', (select name from public.recipes where id = new.sub_recipe_id) using errcode = '22023';
    end if;
    -- no cycles: the sub-recipe must not (transitively) use this recipe
    if exists (
      with recursive tree as (
        select sub_recipe_id as rid, 1 as depth from public.recipe_ingredients where recipe_id = new.sub_recipe_id and sub_recipe_id is not null
        union all
        select ri.sub_recipe_id, t.depth + 1 from public.recipe_ingredients ri join tree t on ri.recipe_id = t.rid where ri.sub_recipe_id is not null and t.depth < 20
      ) select 1 from tree where rid = new.recipe_id) or new.sub_recipe_id = new.recipe_id then
      raise exception 'A recipe cannot contain itself (directly or through a sub-recipe)';
    end if;
  end if;
  return new;
end $$;
create trigger trg_recipe_ingredients_guard before insert or update on public.recipe_ingredients for each row execute function app.recipe_ingredients_guard();

/*
  Explodes p_qty yield-units of a recipe into inventory products (inventory units).
  p_stop_at_prepped: sub-recipes that produce an inventoried product are depleted as
  that product (for theoretical usage) instead of being exploded into raw ingredients.
*/
create or replace function app.recipe_components(p_recipe uuid, p_qty numeric, p_stop_at_prepped boolean)
returns table (product_id uuid, base_qty numeric)
language sql stable security definer set search_path = public as $$
  with recursive walk as (
    select ri.product_id, ri.sub_recipe_id, ri.quantity, ri.unit_id, ri.yield_pct,
           (p_qty / r.yield_qty) * (1 / (1 - r.prep_loss_pct / 100)) as mult, 1 as depth
    from public.recipe_ingredients ri join public.recipes r on r.id = ri.recipe_id
    where ri.recipe_id = p_recipe
    union all
    select ri.product_id, ri.sub_recipe_id, ri.quantity, ri.unit_id, ri.yield_pct,
           w.mult * (w.quantity / (w.yield_pct / 100)) * app.recipe_unit_factor(w.sub_recipe_id, w.unit_id) / sr.yield_qty
             * (1 / (1 - sr.prep_loss_pct / 100)), w.depth + 1
    from walk w
    join public.recipes sr on sr.id = w.sub_recipe_id
    join public.recipe_ingredients ri on ri.recipe_id = w.sub_recipe_id
    where w.sub_recipe_id is not null and w.depth < 20 and not (p_stop_at_prepped and sr.product_id is not null)
  )
  select coalesce(w.product_id, sr.product_id) as product_id,
         sum(case when w.product_id is not null
                  then w.mult * (w.quantity / (w.yield_pct / 100)) * app.unit_factor(w.product_id, w.unit_id)
                  else w.mult * (w.quantity / (w.yield_pct / 100)) * app.recipe_unit_factor(w.sub_recipe_id, w.unit_id)
                       * app.unit_factor(sr.product_id, sr.yield_unit_id) end) as base_qty
  from walk w left join public.recipes sr on sr.id = w.sub_recipe_id
  where w.product_id is not null or (p_stop_at_prepped and sr.product_id is not null)
  group by 1
$$;

-- Cost of one yield unit, fully exploded to raw ingredients at current costs
-- (so a change in a sub-recipe ingredient cost flows into every parent recipe).
create or replace function public.recipe_unit_cost(p_recipe uuid, p_location uuid) returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce(round(sum(c.base_qty * app.current_unit_cost(p_location, c.product_id)), 6), 0)
  from app.recipe_components(p_recipe, 1, false) c
$$;

-- All recipe costs at a location in one call (recipe list, menu engineering).
create or replace function public.recipe_costs(p_location uuid)
returns table (recipe_id uuid, unit_cost numeric)
language sql stable security definer set search_path = public as $$
  select r.id, public.recipe_unit_cost(r.id, p_location)
  from public.recipes r
  where r.organization_id = app.location_org(p_location) and p_location in (select app.user_location_ids())
$$;

-- Ingredient-level cost breakdown for the recipe screen.
create or replace function public.recipe_cost_breakdown(p_recipe uuid, p_location uuid)
returns table (ingredient_id uuid, kind text, name text, quantity numeric, unit_code text, yield_pct numeric, cost numeric)
language sql stable security definer set search_path = public as $$
  select ri.id, case when ri.product_id is not null then 'product' else 'recipe' end,
         coalesce(p.name, sr.name), ri.quantity, u.code, ri.yield_pct,
         round(case when ri.product_id is not null
                    then (ri.quantity / (ri.yield_pct / 100)) * app.unit_factor(ri.product_id, ri.unit_id) * app.current_unit_cost(p_location, ri.product_id)
                    else (ri.quantity / (ri.yield_pct / 100)) * app.recipe_unit_factor(ri.sub_recipe_id, ri.unit_id) * public.recipe_unit_cost(ri.sub_recipe_id, p_location)
               end * (1 / (1 - r.prep_loss_pct / 100)), 4)
  from public.recipe_ingredients ri
  join public.recipes r on r.id = ri.recipe_id
  join public.units u on u.id = ri.unit_id
  left join public.products p on p.id = ri.product_id
  left join public.recipes sr on sr.id = ri.sub_recipe_id
  where ri.recipe_id = p_recipe and r.organization_id in (select app.user_org_ids())
  order by ri.sort, ri.created_at
$$;

-- ---------------------------------------------------------------------
-- Menu items (POS items) mapped to recipes
-- ---------------------------------------------------------------------
create table public.menu_items (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  name            text not null,
  pos_item_id     text,                       -- the POS system's item id / PLU
  menu_category   text,
  selling_price   numeric(12,2) check (selling_price is null or selling_price >= 0),
  recipe_id       uuid references public.recipes(id),
  portion_qty     numeric(18,4) not null default 1 check (portion_qty > 0),  -- recipe yield units per item sold
  active          boolean not null default true,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (organization_id, name)
);
create unique index menu_items_pos_uniq on public.menu_items (organization_id, pos_item_id) where pos_item_id is not null;
create trigger trg_menu_items_touch before update on public.menu_items for each row execute function app.touch_updated_at();
create trigger trg_menu_items_audit after insert or update on public.menu_items for each row execute function app.audit_row();

alter table public.waste_logs add constraint waste_logs_recipe_fk foreign key (recipe_id) references public.recipes(id);

-- ---------------------------------------------------------------------
