-- ---------------------------------------------------------------------
-- Production: deplete ingredients (RECIPE_CONSUMPTION), create output (PRODUCTION)
-- ---------------------------------------------------------------------
create or replace function public.record_production(
  p_location uuid, p_recipe uuid, p_expected_qty numeric, p_actual_qty numeric, p_storage uuid default null,
  p_notes text default null, p_at timestamptz default null, p_client_key uuid default null
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_r public.recipes; v_org uuid := app.location_org(p_location); v_id uuid; v_at timestamptz := least(coalesce(p_at, now()), now());
  c record; v_cost numeric := 0; v_unit_cost numeric; v_out_base numeric; v_lp public.location_products; v_on numeric;
begin
  perform app.require_permission('production.log', p_location);
  if p_client_key is not null then
    select id into v_id from public.production_batches where client_key = p_client_key;
    if v_id is not null then return jsonb_build_object('id', v_id, 'duplicate', true); end if;
  end if;
  select * into v_r from public.recipes where id = p_recipe and organization_id = v_org and active;
  if v_r.id is null then raise exception 'Recipe not found'; end if;
  if v_r.product_id is null then raise exception '% does not produce an inventory item. Link it to a prepped product first.', v_r.name; end if;
  if coalesce(p_expected_qty, 0) <= 0 then raise exception 'Enter the batch size'; end if;
  if p_actual_qty is null or p_actual_qty < 0 then raise exception 'Enter the actual yield'; end if;

  v_id := gen_random_uuid();
  -- ingredients are depleted for the expected batch; prepped sub-recipes deplete their own inventory
  for c in select * from app.recipe_components(p_recipe, p_expected_qty, true) loop
    v_unit_cost := app.current_unit_cost(p_location, c.product_id);
    v_cost := v_cost + c.base_qty * v_unit_cost;
    perform app.post_inventory_txn(p_location, c.product_id, 'RECIPE_CONSUMPTION', -round(c.base_qty, 4), v_unit_cost, v_at, 'production', v_id,
                                   null, null, null, v_r.name);
  end loop;
  v_out_base := round(p_actual_qty * app.unit_factor(v_r.product_id, v_r.yield_unit_id), 4);
  v_unit_cost := case when v_out_base > 0 then round(v_cost / v_out_base, 6) else 0 end;
  if v_out_base > 0 then
    select * into v_lp from public.location_products where location_id = p_location and product_id = v_r.product_id for update;
    select greatest(coalesce(on_hand, 0), 0) into v_on from public.inventory_balances where location_id = p_location and product_id = v_r.product_id;
    v_on := coalesce(v_on, 0);
    update public.location_products set
      avg_cost = case when v_on + v_out_base > 0 and avg_cost > 0 then round((v_on * avg_cost + v_out_base * v_unit_cost) / (v_on + v_out_base), 6) else v_unit_cost end,
      last_cost = v_unit_cost, last_cost_at = v_at
    where id = v_lp.id;
    perform app.post_inventory_txn(p_location, v_r.product_id, 'PRODUCTION', v_out_base, v_unit_cost, v_at, 'production', v_id, null, p_storage, null, v_r.name);
  end if;
  insert into public.production_batches (id, organization_id, location_id, recipe_id, product_id, expected_qty, actual_qty, yield_unit_id, ingredient_cost,
                                         storage_location_id, produced_at, business_date, produced_by, notes, client_key)
  values (v_id, v_org, p_location, p_recipe, v_r.product_id, p_expected_qty, p_actual_qty, v_r.yield_unit_id, round(v_cost, 4), p_storage, v_at,
          app.business_date(p_location, v_at), auth.uid(), p_notes, p_client_key);
  perform app.audit(v_org, p_location, 'produce', 'recipe', p_recipe::text,
    format('Produced %s (expected %s, actual %s)', v_r.name, p_expected_qty, p_actual_qty), null,
    jsonb_build_object('batch', v_id, 'cost', round(v_cost, 2), 'yield_variance', p_actual_qty - p_expected_qty));
  return jsonb_build_object('id', v_id, 'ingredient_cost', round(v_cost, 2), 'unit_cost', v_unit_cost, 'yield_variance', p_actual_qty - p_expected_qty);
end $$;

-- ---------------------------------------------------------------------
-- Waste (now supports prepared items / menu items: recipe waste)
-- ---------------------------------------------------------------------
create or replace function public.log_waste(
  p_location uuid, p_product uuid, p_qty numeric, p_unit uuid, p_reason text,
  p_storage uuid default null, p_comment text default null, p_photo text default null,
  p_at timestamptz default null, p_client_key uuid default null, p_recipe uuid default null
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_org uuid := app.location_org(p_location);
  v_id uuid; v_base numeric; v_cost numeric; v_total numeric := 0; v_at timestamptz := least(coalesce(p_at, now()), now());
  v_reason public.adjustment_reasons; v_r public.recipes; v_mult numeric; c record; v_name text;
begin
  perform app.require_permission('waste.log', p_location);
  if p_client_key is not null then
    select id into v_id from public.waste_logs where client_key = p_client_key;
    if v_id is not null then return jsonb_build_object('id', v_id, 'duplicate', true); end if;
  end if;
  if (p_product is null) = (p_recipe is null) then raise exception 'Choose a product or a prepared item'; end if;
  select * into v_reason from public.adjustment_reasons where organization_id = v_org and kind = 'waste' and code = p_reason and active;
  if v_reason.id is null then raise exception 'Unknown waste reason'; end if;
  if v_reason.requires_comment and coalesce(btrim(p_comment), '') = '' then raise exception 'A comment is required for "%"', v_reason.name; end if;
  if coalesce(p_qty, 0) <= 0 then raise exception 'Waste quantity must be greater than zero'; end if;
  if v_at < now() - interval '7 days' and not app.has_permission('inventory.adjust', p_location) then
    raise exception 'Waste older than 7 days must be entered by a manager';
  end if;
  v_id := gen_random_uuid();
  if p_product is not null then
    v_base := app.to_base_qty(p_product, p_qty, p_unit);
    v_cost := app.current_unit_cost(p_location, p_product);
    v_total := v_base * v_cost;
    perform app.post_inventory_txn(p_location, p_product, 'WASTE', -v_base, v_cost, v_at, 'waste', v_id, null, p_storage, p_reason, null, p_comment);
    v_name := (select name from public.products where id = p_product);
  else
    select * into v_r from public.recipes where id = p_recipe and organization_id = v_org;
    if v_r.id is null then raise exception 'Recipe not found'; end if;
    v_name := v_r.name;
    v_mult := p_qty * app.recipe_unit_factor(p_recipe, p_unit);
    if v_mult is null then raise exception 'Unit has no conversion for %', v_r.name using errcode = '22023'; end if;
    -- A prepped item that is itself inventoried is wasted as that product; otherwise deplete components.
    if v_r.product_id is not null then
      v_base := round(v_mult * app.unit_factor(v_r.product_id, v_r.yield_unit_id), 4);
      v_cost := app.current_unit_cost(p_location, v_r.product_id);
      v_total := v_base * v_cost;
      perform app.post_inventory_txn(p_location, v_r.product_id, 'WASTE', -v_base, v_cost, v_at, 'waste', v_id, null, p_storage, p_reason, v_r.name, p_comment);
    else
      for c in select * from app.recipe_components(p_recipe, v_mult, true) loop
        v_cost := app.current_unit_cost(p_location, c.product_id);
        v_total := v_total + c.base_qty * v_cost;
        perform app.post_inventory_txn(p_location, c.product_id, 'WASTE', -round(c.base_qty, 4), v_cost, v_at, 'waste', v_id, null, p_storage, p_reason, v_r.name, p_comment);
      end loop;
    end if;
  end if;
  insert into public.waste_logs (id, organization_id, location_id, product_id, recipe_id, quantity, unit_id, storage_location_id, reason_code, comment, photo_url,
                                 total_cost, wasted_at, business_date, logged_by, client_key)
  values (v_id, v_org, p_location, p_product, p_recipe, p_qty, p_unit, p_storage, p_reason, p_comment, p_photo, round(v_total, 4), v_at,
          app.business_date(p_location, v_at), auth.uid(), p_client_key);
  perform app.audit(v_org, p_location, 'waste', coalesce(case when p_product is not null then 'product' end, 'recipe'), coalesce(p_product, p_recipe)::text,
    format('Wasted %s %s %s (%s)', p_qty, (select code from public.units where id = p_unit), v_name, v_reason.name), null,
    jsonb_build_object('waste_id', v_id, 'cost', round(v_total, 2)));
  return jsonb_build_object('id', v_id, 'cost', round(v_total, 2));
end $$;

-- ---------------------------------------------------------------------
-- POS import: records sales and posts theoretical consumption (POS_CONSUMPTION)
-- p_summary: {net_sales, gross_sales, discounts, voids, refunds, guest_count, check_count}
-- p_lines:   [{pos_item_id, item_name, quantity, net_sales, discounts, voids, refunds, daypart}]
-- Consumption is timestamped at 12:00 local on the business date so an evening
-- count on that date includes the day's sales, and a morning count does not.
-- ---------------------------------------------------------------------
create or replace function public.import_sales(
  p_location uuid, p_business_date date, p_source text, p_file_name text, p_summary jsonb, p_lines jsonb
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_org uuid := app.location_org(p_location);
  v_id uuid; r jsonb; v_mi public.menu_items; v_unmapped int := 0; v_theo numeric := 0; v_cost numeric;
  v_at timestamptz; c record; v_net numeric := 0;
begin
  perform app.require_permission('sales.import', p_location);
  if p_business_date > (now() at time zone (select timezone from public.locations where id = p_location))::date then
    raise exception 'Sales cannot be imported for a future date';
  end if;
  if exists (select 1 from public.sales_imports where location_id = p_location and business_date = p_business_date and status = 'posted') then
    raise exception 'Sales for % were already imported. Reverse that import first to replace it.', p_business_date using errcode = '23505';
  end if;
  v_at := (p_business_date::timestamp + time '12:00') at time zone (select timezone from public.locations where id = p_location);
  insert into public.sales_imports (organization_id, location_id, business_date, source, file_name, gross_sales, discounts, voids, refunds,
                                    guest_count, check_count, imported_by)
  values (v_org, p_location, p_business_date, coalesce(p_source, 'csv'), p_file_name,
          coalesce((p_summary ->> 'gross_sales')::numeric, 0), coalesce((p_summary ->> 'discounts')::numeric, 0),
          coalesce((p_summary ->> 'voids')::numeric, 0), coalesce((p_summary ->> 'refunds')::numeric, 0),
          coalesce((p_summary ->> 'guest_count')::int, 0), coalesce((p_summary ->> 'check_count')::int, 0), auth.uid())
  returning id into v_id;

  create temporary table if not exists tmp_usage (product_id uuid, base_qty numeric) on commit drop;
  truncate tmp_usage;
  for r in select * from jsonb_array_elements(p_lines) loop
    v_mi := null;
    select * into v_mi from public.menu_items
     where organization_id = v_org and active
       and ((nullif(r ->> 'pos_item_id', '') is not null and pos_item_id = r ->> 'pos_item_id') or lower(name) = lower(btrim(r ->> 'item_name')))
     order by (pos_item_id = r ->> 'pos_item_id') desc nulls last limit 1;
    v_cost := case when v_mi.recipe_id is not null then public.recipe_unit_cost(v_mi.recipe_id, p_location) * v_mi.portion_qty end;
    insert into public.sales_lines (import_id, menu_item_id, pos_item_id, item_name, quantity, net_sales, discounts, voids, refunds, daypart, recipe_cost)
    values (v_id, v_mi.id, nullif(r ->> 'pos_item_id', ''), coalesce(nullif(btrim(r ->> 'item_name'), ''), r ->> 'pos_item_id'),
            coalesce((r ->> 'quantity')::numeric, 0), coalesce((r ->> 'net_sales')::numeric, 0), coalesce((r ->> 'discounts')::numeric, 0),
            coalesce((r ->> 'voids')::numeric, 0), coalesce((r ->> 'refunds')::numeric, 0), r ->> 'daypart', v_cost);
    v_net := v_net + coalesce((r ->> 'net_sales')::numeric, 0);
    if v_mi.recipe_id is null then
      v_unmapped := v_unmapped + 1;
    elsif coalesce((r ->> 'quantity')::numeric, 0) <> 0 then
      v_theo := v_theo + v_cost * (r ->> 'quantity')::numeric;
      insert into tmp_usage select * from app.recipe_components(v_mi.recipe_id, v_mi.portion_qty * (r ->> 'quantity')::numeric, true);
    end if;
  end loop;

  for c in select product_id, sum(base_qty) as q from tmp_usage group by product_id loop
    continue when round(c.q, 4) = 0;
    perform app.post_inventory_txn(p_location, c.product_id, 'POS_CONSUMPTION', -round(c.q, 4), app.current_unit_cost(p_location, c.product_id),
                                   v_at, 'sales_import', v_id, null, null, null, 'POS ' || p_business_date);
  end loop;

  update public.sales_imports set net_sales = coalesce((p_summary ->> 'net_sales')::numeric, v_net), unmapped_lines = v_unmapped,
         theoretical_cost = round(v_theo, 4) where id = v_id;
  perform app.audit(v_org, p_location, 'import', 'sales_import', v_id::text,
    format('POS sales %s imported (%s lines, %s unmapped)', p_business_date, jsonb_array_length(p_lines), v_unmapped), null, p_summary);
  if v_unmapped > 0 then
    perform app.create_task(p_location, format('Map %s POS item(s) to recipes', v_unmapped), 'custom', now() + interval '1 day',
      'Unmapped items do not deplete inventory, which understates theoretical usage.', 'sales_import', v_id, 'unmapped:' || v_id);
  end if;
  return jsonb_build_object('id', v_id, 'unmapped', v_unmapped, 'theoretical_cost', round(v_theo, 2), 'net_sales', coalesce((p_summary ->> 'net_sales')::numeric, v_net));
end $$;

create or replace function public.reverse_sales_import(p_import uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare v_i public.sales_imports; t record;
begin
  select * into v_i from public.sales_imports where id = p_import for update;
  if v_i.id is null then raise exception 'Import not found'; end if;
  perform app.require_permission('sales.import', v_i.location_id);
  if v_i.status <> 'posted' then raise exception 'Import is already reversed'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'A reason is required'; end if;
  if exists (select 1 from public.count_sessions where location_id = v_i.location_id and status = 'posted'
             and count_at > (v_i.business_date::timestamp + time '12:00') at time zone (select timezone from public.locations where id = v_i.location_id)) then
    raise exception 'A physical count was posted after these sales. Reversing would change posted variances.';
  end if;
  for t in select * from public.inventory_transactions where source_type = 'sales_import' and source_id = p_import loop
    perform app.post_inventory_txn(t.location_id, t.product_id, 'CORRECTION', -t.quantity, t.unit_cost, t.txn_at, 'sales_import_reversal', p_import,
                                   null, null, 'REVERSAL', 'Reversal of POS ' || v_i.business_date, p_reason);
  end loop;
  update public.sales_imports set status = 'reversed', reversed_at = now(), reversed_by = auth.uid() where id = p_import;
  perform app.audit(v_i.organization_id, v_i.location_id, 'reverse', 'sales_import', p_import::text, 'POS import reversed: ' || p_reason, null, null);
end $$;

-- Remap an unmapped POS item going forward (creates/updates the menu item link).
create or replace function public.map_pos_item(p_org uuid, p_pos_item_id text, p_item_name text, p_recipe uuid, p_price numeric default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  perform app.require_org_permission('recipes.edit', p_org);
  select id into v_id from public.menu_items where organization_id = p_org and ((p_pos_item_id is not null and pos_item_id = p_pos_item_id) or lower(name) = lower(p_item_name)) limit 1;
  if v_id is null then
    insert into public.menu_items (organization_id, name, pos_item_id, recipe_id, selling_price) values (p_org, p_item_name, p_pos_item_id, p_recipe, p_price) returning id into v_id;
  else
    update public.menu_items set recipe_id = p_recipe, pos_item_id = coalesce(pos_item_id, p_pos_item_id) where id = v_id;
  end if;
  return v_id;
end $$;

-- ---------------------------------------------------------------------
-- FOOD COST: actual vs theoretical for a period
--   Actual usage  = BEGIN + PURCHASES +/- TRANSFERS - END  (valued from the ledger)
--   Theoretical   = menu items sold x recipe cost (POS)
--   Variance      = actual - theoretical  (waste + unexplained loss + adjustments)
-- p_cost_groups filters categories (default: food).
-- ---------------------------------------------------------------------
create or replace function public.food_cost_summary(p_location uuid, p_from timestamptz, p_to timestamptz, p_cost_groups text[] default array['food'])
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v jsonb;
begin
  if not (p_location in (select app.user_location_ids())) then raise exception 'Location not found' using errcode = '42501'; end if;
  with prods as (
    select p.id from public.products p left join public.categories c on c.id = p.category_id
    where p.organization_id = app.location_org(p_location) and coalesce(c.cost_group, 'food') = any(p_cost_groups)
  ),
  t as (
    select t.* from public.inventory_transactions t join prods on prods.id = t.product_id
    where t.location_id = p_location
  ),
  agg as (
    select
      coalesce(sum(extended_cost) filter (where txn_at <= p_from), 0) as begin_value,
      coalesce(sum(extended_cost) filter (where txn_at <= p_to), 0) as end_value,
      coalesce(sum(extended_cost) filter (where txn_at > p_from and txn_at <= p_to and txn_type in ('RECEIPT', 'RETURN_TO_VENDOR')), 0) as purchases,
      coalesce(sum(extended_cost) filter (where txn_at > p_from and txn_at <= p_to and txn_type in ('TRANSFER_IN', 'TRANSFER_OUT')), 0) as transfers,
      coalesce(-sum(extended_cost) filter (where txn_at > p_from and txn_at <= p_to and txn_type = 'POS_CONSUMPTION'), 0) as pos_usage,
      coalesce(-sum(extended_cost) filter (where txn_at > p_from and txn_at <= p_to and txn_type = 'WASTE'), 0) as waste,
      coalesce(-sum(extended_cost) filter (where txn_at > p_from and txn_at <= p_to and txn_type = 'PHYSICAL_VARIANCE'), 0) as count_variance,
      coalesce(-sum(extended_cost) filter (where txn_at > p_from and txn_at <= p_to and txn_type in ('MANUAL_ADJUSTMENT', 'CORRECTION')), 0) as adjustments,
      coalesce(-sum(extended_cost) filter (where txn_at > p_from and txn_at <= p_to and txn_type in ('RECIPE_CONSUMPTION', 'PRODUCTION')), 0) as production_net
    from t
  ),
  sales as (
    select coalesce(sum(s.net_sales), 0) as net_sales, coalesce(sum(s.guest_count), 0) as guests, coalesce(sum(s.check_count), 0) as checks,
           count(*) as days
    from public.sales_imports s
    where s.location_id = p_location and s.status = 'posted'
      and (s.business_date::timestamp + time '12:00') at time zone (select timezone from public.locations where id = p_location) > p_from
      and (s.business_date::timestamp + time '12:00') at time zone (select timezone from public.locations where id = p_location) <= p_to
  ),
  theo as (  -- menu items sold x CURRENT recipe cost (limited to the requested cost groups)
    select coalesce(sum(sl.quantity * mi.portion_qty * (
             select coalesce(sum(c.base_qty * app.current_unit_cost(p_location, c.product_id)), 0)
             from app.recipe_components(mi.recipe_id, 1, false) c join prods on prods.id = c.product_id)), 0) as theoretical
    from public.sales_imports s
    join public.sales_lines sl on sl.import_id = s.id
    join public.menu_items mi on mi.id = sl.menu_item_id and mi.recipe_id is not null
    where s.location_id = p_location and s.status = 'posted'
      and (s.business_date::timestamp + time '12:00') at time zone (select timezone from public.locations where id = p_location) > p_from
      and (s.business_date::timestamp + time '12:00') at time zone (select timezone from public.locations where id = p_location) <= p_to
  )
  select jsonb_build_object(
    'from', p_from, 'to', p_to, 'cost_groups', p_cost_groups,
    'net_sales', s.net_sales, 'guests', s.guests, 'checks', s.checks, 'sales_days', s.days,
    'begin_inventory', round(a.begin_value, 2), 'purchases', round(a.purchases, 2), 'transfers', round(a.transfers, 2),
    'end_inventory', round(a.end_value, 2),
    'actual_cost', round(a.begin_value + a.purchases + a.transfers - a.end_value, 2),
    'theoretical_cost', round(th.theoretical, 2),
    'pos_usage_at_post', round(a.pos_usage, 2),
    'waste', round(a.waste, 2), 'count_variance', round(a.count_variance, 2), 'adjustments', round(a.adjustments, 2),
    'production_net', round(a.production_net, 2),
    'variance', round(a.begin_value + a.purchases + a.transfers - a.end_value - th.theoretical, 2),
    'actual_pct', case when s.net_sales > 0 then round((a.begin_value + a.purchases + a.transfers - a.end_value) / s.net_sales * 100, 2) end,
    'theoretical_pct', case when s.net_sales > 0 then round(th.theoretical / s.net_sales * 100, 2) end,
    'waste_pct', case when s.net_sales > 0 then round(a.waste / s.net_sales * 100, 2) end
  ) into v
  from agg a, sales s, theo th;
  return v || jsonb_build_object('variance_pct_points',
    case when (v ->> 'actual_pct') is not null then round((v ->> 'actual_pct')::numeric - (v ->> 'theoretical_pct')::numeric, 2) end);
end $$;

-- Product-level AvT between two moments (normally two posted counts).
create or replace function public.avt_by_product(p_location uuid, p_from timestamptz, p_to timestamptz)
returns table (
  product_id uuid, product_name text, category_name text, cost_group text, inventory_unit text,
  begin_qty numeric, received_qty numeric, transfer_qty numeric, produced_qty numeric, theoretical_qty numeric, waste_qty numeric,
  adjusted_qty numeric, expected_end_qty numeric, physical_end_qty numeric, variance_qty numeric, unit_cost numeric,
  variance_value numeric, theoretical_value numeric, counted boolean
)
language sql stable security definer set search_path = public as $$
  with allowed as (select 1 where p_location in (select app.user_location_ids())),
  t as (
    select t.product_id,
      coalesce(sum(t.quantity) filter (where t.txn_at <= p_from), 0) as begin_qty,
      coalesce(sum(t.quantity) filter (where t.txn_at > p_from and t.txn_at <= p_to and t.txn_type in ('RECEIPT', 'RETURN_TO_VENDOR')), 0) as received,
      coalesce(sum(t.quantity) filter (where t.txn_at > p_from and t.txn_at <= p_to and t.txn_type in ('TRANSFER_IN', 'TRANSFER_OUT')), 0) as transfers,
      coalesce(sum(t.quantity) filter (where t.txn_at > p_from and t.txn_at <= p_to and t.txn_type = 'PRODUCTION'), 0) as produced,
      coalesce(-sum(t.quantity) filter (where t.txn_at > p_from and t.txn_at <= p_to and t.txn_type in ('POS_CONSUMPTION', 'RECIPE_CONSUMPTION')), 0) as theo,
      coalesce(-sum(t.extended_cost) filter (where t.txn_at > p_from and t.txn_at <= p_to and t.txn_type in ('POS_CONSUMPTION', 'RECIPE_CONSUMPTION')), 0) as theo_value,
      coalesce(-sum(t.quantity) filter (where t.txn_at > p_from and t.txn_at <= p_to and t.txn_type = 'WASTE'), 0) as waste,
      coalesce(sum(t.quantity) filter (where t.txn_at > p_from and t.txn_at <= p_to and t.txn_type in ('MANUAL_ADJUSTMENT', 'CORRECTION')), 0) as adjusted,
      coalesce(sum(t.quantity) filter (where t.txn_at > p_from and t.txn_at <= p_to and t.txn_type = 'PHYSICAL_VARIANCE'), 0) as variance,
      coalesce(sum(t.extended_cost) filter (where t.txn_at > p_from and t.txn_at <= p_to and t.txn_type = 'PHYSICAL_VARIANCE'), 0) as variance_value,
      bool_or(t.txn_type = 'PHYSICAL_VARIANCE' and t.txn_at > p_from and t.txn_at <= p_to) as has_var,
      coalesce(sum(t.quantity) filter (where t.txn_at <= p_to), 0) as end_qty
    from public.inventory_transactions t, allowed
    where t.location_id = p_location and t.txn_at <= p_to
    group by t.product_id
  )
  select t.product_id, p.name, c.name, coalesce(c.cost_group, 'food'), u.code,
         t.begin_qty, t.received, t.transfers, t.produced, t.theo, t.waste, t.adjusted,
         t.end_qty - t.variance, t.end_qty, t.variance, app.current_unit_cost(p_location, t.product_id),
         round(t.variance_value, 2), round(t.theo_value, 2),
         coalesce(t.has_var, false) or exists (
           select 1 from public.count_posting_lines pl join public.count_sessions cs on cs.id = pl.session_id
           where pl.product_id = t.product_id and cs.location_id = p_location and cs.count_at > p_from and cs.count_at <= p_to and pl.counted)
  from t
  join public.products p on p.id = t.product_id
  join public.units u on u.id = p.inventory_unit_id
  left join public.categories c on c.id = p.category_id
$$;

select app.apply_grants();

-- Suggested prep: forecast usage of each prepped item over the horizon + safety - prepared on hand.
create or replace function public.suggested_prep(p_location uuid, p_days numeric default 1, p_safety_days numeric default 0.5)
returns table (recipe_id uuid, recipe_name text, product_id uuid, unit_code text, on_hand numeric, daily_usage numeric,
               need numeric, suggested_qty numeric, yield_qty numeric, shelf_life_hours integer)
language sql stable security definer set search_path = public as $$
  select r.id, r.name, r.product_id, u.code,
         coalesce(b.on_hand, 0), round(app.avg_daily_usage(p_location, r.product_id, 14), 4),
         round(app.avg_daily_usage(p_location, r.product_id, 14) * (p_days + p_safety_days), 4),
         greatest(0, round(app.avg_daily_usage(p_location, r.product_id, 14) * (p_days + p_safety_days) - greatest(coalesce(b.on_hand, 0), 0), 2)),
         r.yield_qty, r.shelf_life_hours
  from public.recipes r
  join public.products p on p.id = r.product_id
  join public.units u on u.id = p.inventory_unit_id
  left join public.inventory_balances b on b.location_id = p_location and b.product_id = r.product_id
  where r.organization_id = app.location_org(p_location) and r.active and p_location in (select app.user_location_ids())
  order by r.name
$$;
select app.apply_grants();

-- ============================================================================
-- 20260930001200_dashboard_reports_forecast.sql
-- ============================================================================
-- =====================================================================
-- DASHBOARD KPIs, MULTI-LOCATION SCORECARD, REPORTS, FORECASTING (Phase 7)
-- =====================================================================

-- ---------------------------------------------------------------------
-- Forecasting. Initial model: same-weekday average of the last N weeks,
-- scaled by the recent trend (last 2 weeks vs the prior 2). Stored so the
-- forecast used for a decision is reproducible; the table has room for
-- weather / holiday / event adjustments later.
-- ---------------------------------------------------------------------
create table public.sales_forecasts (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id),
  location_id     uuid not null references public.locations(id) on delete cascade,
  business_date   date not null,
  net_sales       numeric(14,2) not null,
  guest_count     integer not null,
  method          text not null,
  factors         jsonb not null default '{}'::jsonb,   -- {weekday_avg, trend, weather, holiday, event, manual}
  manual_adjustment_pct numeric(6,2) not null default 0,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (location_id, business_date)
);
create table public.demand_forecasts (
  location_id     uuid not null references public.locations(id) on delete cascade,
  product_id      uuid not null references public.products(id) on delete cascade,
  business_date   date not null,
  quantity        numeric(18,4) not null,
  method          text not null,
  created_at      timestamptz not null default now(),
  primary key (location_id, product_id, business_date)
);
insert into app.write_protected_tables values ('demand_forecasts');
alter table public.sales_forecasts enable row level security;
alter table public.demand_forecasts enable row level security;
create policy sf_select on public.sales_forecasts for select to authenticated using (location_id in (select app.user_location_ids()));
create policy sf_write on public.sales_forecasts for update to authenticated
  using (app.has_permission('forecast.edit', location_id)) with check (app.has_permission('forecast.edit', location_id));
create policy df_select on public.demand_forecasts for select to authenticated using (location_id in (select app.user_location_ids()));

create or replace function public.forecast_sales(p_location uuid, p_date date, p_weeks integer default 4) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_avg numeric; v_guests numeric; v_n int; v_recent numeric; v_prior numeric; v_trend numeric := 1; v_manual numeric;
begin
  if not (p_location in (select app.user_location_ids())) then raise exception 'Location not found' using errcode = '42501'; end if;
  select avg(net_sales), avg(guest_count), count(*) into v_avg, v_guests, v_n
  from public.sales_imports where location_id = p_location and status = 'posted'
    and extract(dow from business_date) = extract(dow from p_date) and business_date < p_date and business_date >= p_date - p_weeks * 7;
  select sum(net_sales) filter (where business_date >= p_date - 14), sum(net_sales) filter (where business_date < p_date - 14 and business_date >= p_date - 28)
    into v_recent, v_prior
  from public.sales_imports where location_id = p_location and status = 'posted' and business_date < p_date and business_date >= p_date - 28;
  if coalesce(v_prior, 0) > 0 and v_recent is not null then v_trend := greatest(0.8, least(1.2, v_recent / v_prior)); end if;
  select manual_adjustment_pct into v_manual from public.sales_forecasts where location_id = p_location and business_date = p_date;
  return jsonb_build_object('date', p_date, 'net_sales', round(coalesce(v_avg, 0) * v_trend * (1 + coalesce(v_manual, 0) / 100), 2),
    'guest_count', round(coalesce(v_guests, 0) * v_trend * (1 + coalesce(v_manual, 0) / 100)), 'weeks_used', v_n,
    'weekday_avg', round(coalesce(v_avg, 0), 2), 'trend', round(v_trend, 3), 'manual_adjustment_pct', coalesce(v_manual, 0),
    'method', format('Average of the last %s %ss × recent trend', v_n, trim(to_char(p_date, 'Day'))));
end $$;

-- Product demand by weekday: each weekday's average usage over the last 4 weeks
-- (POS + recipe consumption + waste + count variance), scaled by the sales forecast
-- ratio for that day. Replaces the flat 28-day average used by suggested orders.
create or replace function app.forecast_usage(p_location uuid, p_product uuid, p_from date, p_to date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_total numeric := 0; d date; v_day numeric; v_dow_avg numeric; v_flat numeric; v_ratio numeric; v_hist numeric; v_fc numeric;
  v_has_sales boolean;
begin
  v_flat := app.avg_daily_usage(p_location, p_product, 28);
  if p_to <= p_from then return jsonb_build_object('qty', 0, 'daily', round(v_flat, 4), 'method', 'no days'); end if;
  v_has_sales := exists (select 1 from public.sales_imports where location_id = p_location and status = 'posted' and business_date >= current_date - 28);
  d := p_from;
  while d < p_to loop
    select greatest(0, -coalesce(sum(t.quantity), 0)) / 4 into v_dow_avg
    from public.inventory_transactions t
    where t.location_id = p_location and t.product_id = p_product
      and t.txn_type in ('POS_CONSUMPTION', 'RECIPE_CONSUMPTION', 'WASTE', 'PHYSICAL_VARIANCE', 'MANUAL_ADJUSTMENT')
      and t.business_date >= current_date - 28 and t.business_date < current_date
      and extract(dow from t.business_date) = extract(dow from d);
    v_day := coalesce(v_dow_avg, v_flat);
    -- counted variance lands on count days only; blend with the flat average so it is spread across the week
    v_day := 0.6 * v_day + 0.4 * v_flat;
    if v_has_sales then
      select avg(net_sales) into v_hist from public.sales_imports where location_id = p_location and status = 'posted'
        and extract(dow from business_date) = extract(dow from d) and business_date >= current_date - 28;
      v_fc := (public.forecast_sales(p_location, d) ->> 'net_sales')::numeric;
      v_ratio := case when coalesce(v_hist, 0) > 0 then greatest(0.5, least(1.5, v_fc / v_hist)) else 1 end;
      v_day := v_day * v_ratio;
    end if;
    v_total := v_total + v_day;
    d := d + 1;
  end loop;
  return jsonb_build_object('qty', round(v_total, 4), 'daily', round(v_total / (p_to - p_from), 4),
    'method', case when v_has_sales then 'Day-of-week usage (last 4 weeks) × sales forecast' else '28-day average daily usage' end);
end $$;

-- Dynamic par = forecast usage over lead time + coverage + safety days.
create or replace function public.refresh_dynamic_pars(p_location uuid) returns integer
language plpgsql security definer set search_path = public as $$
declare r record; v_days int; v_par numeric; n int := 0;
begin
  perform app.require_permission('inventory.view', p_location);
  for r in
    select lp.id, lp.product_id, lp.safety_stock_days,
           coalesce(v.lead_time_days, 1) as lead, coalesce(array_length(coalesce(lv.delivery_days, v.delivery_days), 1), 1) as deliveries
    from public.location_products lp
    join public.products p on p.id = lp.product_id
    left join public.vendors v on v.id = coalesce(lp.local_vendor_id, p.default_vendor_id)
    left join public.location_vendors lv on lv.vendor_id = v.id and lv.location_id = p_location
    where lp.location_id = p_location and lp.par_mode = 'dynamic' and lp.active
  loop
    v_days := r.lead + ceil(7.0 / greatest(r.deliveries, 1))::int;
    v_par := (app.forecast_usage(p_location, r.product_id, current_date, current_date + v_days) ->> 'qty')::numeric
             + coalesce(r.safety_stock_days, 0) * app.avg_daily_usage(p_location, r.product_id, 28);
    update public.location_products set dynamic_par_qty = round(v_par, 2), dynamic_par_at = now() where id = r.id;
    n := n + 1;
  end loop;
  return n;
end $$;

-- ---------------------------------------------------------------------
-- Dashboard (one round trip)
-- ---------------------------------------------------------------------
create or replace function public.dashboard_kpis(p_location uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_tz text; v_today date; v_week_start date; v jsonb; v_last public.count_sessions; v_prev public.count_sessions; v_fc jsonb := null;
  v_28 jsonb; v_inv_value numeric;
begin
  if not (p_location in (select app.user_location_ids())) then raise exception 'Location not found' using errcode = '42501'; end if;
  perform public.refresh_stock_alerts(p_location);
  select timezone into v_tz from public.locations where id = p_location;
  v_today := (now() at time zone v_tz)::date;
  v_week_start := v_today - ((extract(isodow from v_today)::int) - 1);
  select * into v_last from public.count_sessions where location_id = p_location and status = 'posted' order by count_at desc limit 1;
  select * into v_prev from public.count_sessions where location_id = p_location and status = 'posted' and count_at < v_last.count_at order by count_at desc limit 1;
  if v_prev.id is not null then v_fc := public.food_cost_summary(p_location, v_prev.count_at, v_last.count_at); end if;
  v_28 := public.food_cost_summary(p_location, now() - interval '28 days', now(), array['food', 'beverage', 'alcohol', 'paper', 'supplies', 'other']);
  select coalesce(sum(extended_value), 0) into v_inv_value from public.current_inventory where location_id = p_location and active;

  select jsonb_build_object(
    'today', v_today,
    'inventory_value', v_inv_value,
    'stock', (select jsonb_build_object('low', count(*) filter (where stock_status = 'low'), 'critical', count(*) filter (where stock_status = 'critical'),
                                        'out', count(*) filter (where stock_status = 'out'), 'negative', count(*) filter (where stock_status = 'negative'))
              from public.current_inventory where location_id = p_location and active),
    'food_cost', v_fc,
    'food_cost_period', case when v_prev.id is not null then jsonb_build_object('from', v_prev.count_at, 'to', v_last.count_at, 'from_id', v_prev.id, 'to_id', v_last.id) end,
    'turns_28d', case when ((v_28 ->> 'begin_inventory')::numeric + (v_28 ->> 'end_inventory')::numeric) > 0
                      then round((v_28 ->> 'actual_cost')::numeric / (((v_28 ->> 'begin_inventory')::numeric + (v_28 ->> 'end_inventory')::numeric) / 2), 2) end,
    'waste_today', (select coalesce(sum(total_cost), 0) from public.waste_logs where location_id = p_location and business_date = v_today),
    'waste_week', (select coalesce(sum(total_cost), 0) from public.waste_logs where location_id = p_location and business_date >= v_week_start),
    'waste_7d', (select coalesce(sum(total_cost), 0) from public.waste_logs where location_id = p_location and business_date > v_today - 7),
    'sales_7d', (select coalesce(sum(net_sales), 0) from public.sales_imports where location_id = p_location and status = 'posted' and business_date > v_today - 7),
    'sales_today', (select net_sales from public.sales_imports where location_id = p_location and status = 'posted' and business_date = v_today),
    'sales_yesterday', (select jsonb_build_object('net_sales', net_sales, 'guests', guest_count, 'checks', check_count, 'theoretical_cost', theoretical_cost)
                        from public.sales_imports where location_id = p_location and status = 'posted' and business_date = v_today - 1),
    'forecast_today', public.forecast_sales(p_location, v_today),
    'forecast_week', (select jsonb_agg(public.forecast_sales(p_location, d::date) order by d) from generate_series(v_today, v_today + 6, interval '1 day') d),
    'open_pos', (select count(*) from public.purchase_orders where location_id = p_location and status in ('draft', 'ready_to_submit')),
    'pending_deliveries', (select count(*) from public.purchase_orders where location_id = p_location and status in ('submitted', 'confirmed', 'back_ordered')),
    'late_deliveries', (select count(*) from public.purchase_orders where location_id = p_location and status in ('submitted', 'confirmed') and expected_delivery_date < v_today),
    'to_reconcile', (select count(*) from public.receipts where location_id = p_location and status in ('draft', 'received')),
    'last_count', case when v_last.id is not null then jsonb_build_object('id', v_last.id, 'name', v_last.name, 'count_at', v_last.count_at,
        'variance_value', (select coalesce(sum(variance_value), 0) from public.count_posting_lines where session_id = v_last.id),
        'loss_value', (select coalesce(sum(least(variance_value, 0)), 0) from public.count_posting_lines where session_id = v_last.id)) end,
    'top_waste', (select coalesce(jsonb_agg(x order by x.cost desc), '[]'::jsonb) from (
        select coalesce(p.name, r.name) as name, sum(w.total_cost) as cost from public.waste_logs w
        left join public.products p on p.id = w.product_id left join public.recipes r on r.id = w.recipe_id
        where w.location_id = p_location and w.business_date > v_today - 7 group by 1 order by 2 desc limit 5) x),
    'largest_variances', case when v_last.id is not null then (select coalesce(jsonb_agg(x order by x.value), '[]'::jsonb) from (
        select p.id, p.name, pl.variance_qty as qty, u.code as unit, pl.variance_value as value from public.count_posting_lines pl
        join public.products p on p.id = pl.product_id join public.units u on u.id = p.inventory_unit_id
        where pl.session_id = v_last.id and pl.variance_value < 0 order by pl.variance_value limit 5) x) end,
    'price_increases', (select coalesce(jsonb_agg(x order by x.created_at desc), '[]'::jsonb) from (
        select a.title, a.message, a.product_id, a.created_at from public.alerts a
        where a.location_id = p_location and a.alert_type = 'price_increase' and a.status <> 'resolved' order by a.created_at desc limit 5) x),
    'tasks', (select jsonb_build_object(
        'due_today', count(*) filter (where status = 'open' and (due_at at time zone v_tz)::date = v_today),
        'overdue', count(*) filter (where status = 'open' and due_at < now() and (due_at at time zone v_tz)::date < v_today),
        'upcoming', count(*) filter (where status = 'open' and (due_at at time zone v_tz)::date > v_today))
        from public.tasks where location_id = p_location),
    'alerts', (select coalesce(jsonb_agg(x order by case x.severity when 'critical' then 0 when 'warning' then 1 else 2 end, x.created_at desc), '[]'::jsonb) from (
        select id, alert_type, severity, title, message, product_id, entity_type, entity_id, created_at from public.alerts
        where location_id = p_location and status = 'open' order by created_at desc limit 12) x),
    'open_counts', (select count(*) from public.count_sessions where location_id = p_location and status in ('not_started', 'in_progress', 'awaiting_review', 'reviewed'))
  ) into v;
  return v;
end $$;

-- Multi-location scorecard for the trailing N days (actual from ledger begin/end, theoretical from POS).
create or replace function public.location_scorecard(p_org uuid, p_days integer default 28)
returns table (location_id uuid, code text, name text, region text, district text, market text,
               net_sales numeric, actual_cost numeric, theoretical_cost numeric, actual_pct numeric, theoretical_pct numeric,
               variance_pts numeric, waste numeric, waste_pct numeric, count_variance numeric, inventory_value numeric, open_alerts bigint)
language plpgsql stable security definer set search_path = public as $$
declare l record; s jsonb;
begin
  for l in select loc.*, r.name as region_name, d.name as district_name from public.locations loc
           left join public.regions r on r.id = loc.region_id left join public.districts d on d.id = loc.district_id
           where loc.organization_id = p_org and loc.active and loc.id in (select app.user_location_ids()) order by loc.code
  loop
    s := public.food_cost_summary(l.id, now() - make_interval(days => p_days), now(), array['food']);
    location_id := l.id; code := l.code; name := l.name; region := l.region_name; district := l.district_name; market := l.market;
    net_sales := (s ->> 'net_sales')::numeric; actual_cost := (s ->> 'actual_cost')::numeric; theoretical_cost := (s ->> 'theoretical_cost')::numeric;
    actual_pct := (s ->> 'actual_pct')::numeric; theoretical_pct := (s ->> 'theoretical_pct')::numeric; variance_pts := (s ->> 'variance_pct_points')::numeric;
    waste := (s ->> 'waste')::numeric; waste_pct := (s ->> 'waste_pct')::numeric; count_variance := (s ->> 'count_variance')::numeric;
    select coalesce(sum(extended_value), 0) into inventory_value from public.current_inventory ci where ci.location_id = l.id and ci.active;
    select count(*) into open_alerts from public.alerts a where a.location_id = l.id and a.status = 'open';
    return next;
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- Reports
-- ---------------------------------------------------------------------
-- Usage, turns, days on hand and aging per product.
create or replace function public.report_inventory_efficiency(p_location uuid, p_days integer default 28)
returns table (product_id uuid, product_name text, category_name text, inventory_unit text, on_hand numeric, value numeric,
               usage_qty numeric, usage_value numeric, avg_daily_usage numeric, days_on_hand numeric, turns_annualized numeric,
               last_receipt_at timestamptz, days_since_receipt integer, last_counted_at timestamptz, shelf_life_days integer, aging_flag text)
language sql stable security definer set search_path = public as $$
  select ci.product_id, ci.product_name, ci.category_name, ci.inventory_unit, ci.on_hand, ci.extended_value,
         u.qty, u.val, round(u.qty / p_days, 4),
         case when u.qty > 0 then round(greatest(ci.on_hand, 0) / (u.qty / p_days), 1) end,
         case when ci.extended_value > 0 then round(u.val / ci.extended_value * (365.0 / p_days), 1) end,
         r.last_at, (now()::date - r.last_at::date), ci.last_counted_at, p.shelf_life_days,
         case when p.shelf_life_days is not null and r.last_at is not null and now()::date - r.last_at::date > p.shelf_life_days and ci.on_hand > 0 then 'past shelf life'
              when u.qty = 0 and ci.on_hand > 0 then 'no movement'
              when u.qty > 0 and greatest(ci.on_hand, 0) / (u.qty / p_days) > 30 then 'overstocked' else 'ok' end
  from public.current_inventory ci
  join public.products p on p.id = ci.product_id
  left join lateral (
    select coalesce(-sum(t.quantity), 0) as qty, coalesce(-sum(t.extended_cost), 0) as val from public.inventory_transactions t
    where t.location_id = p_location and t.product_id = ci.product_id and t.txn_at > now() - make_interval(days => p_days)
      and t.txn_type in ('POS_CONSUMPTION', 'RECIPE_CONSUMPTION', 'WASTE', 'PHYSICAL_VARIANCE', 'MANUAL_ADJUSTMENT')) u on true
  left join lateral (select max(t.txn_at) as last_at from public.inventory_transactions t where t.location_id = p_location and t.product_id = ci.product_id and t.txn_type = 'RECEIPT') r on true
  where ci.location_id = p_location and ci.active and p_location in (select app.user_location_ids())
$$;

-- Every received invoice line in a period (purchases by vendor/product/category, price variance).
create or replace function public.report_purchases(p_location uuid, p_from date, p_to date)
returns table (receipt_id uuid, receipt_number text, invoice_number text, delivery_date date, vendor_name text, product_id uuid, product_name text,
               category_name text, unit_code text, ordered_qty numeric, received_qty numeric, invoiced_qty numeric, contract_price numeric,
               invoice_price numeric, price_variance numeric, extended numeric, exceptions text)
language sql stable security definer set search_path = public as $$
  select r.id, r.receipt_number, r.invoice_number, r.delivery_date, v.name, p.id, p.name, c.name, u.code,
         ri.ordered_qty, ri.received_qty, ri.invoiced_qty, ri.contract_price, ri.invoice_price,
         case when ri.contract_price is not null and ri.invoice_price is not null then round((ri.invoice_price - ri.contract_price) * coalesce(ri.invoiced_qty, 0), 2) end,
         coalesce(ri.invoice_extended, round(coalesce(ri.invoiced_qty, 0) * coalesce(ri.invoice_price, 0), 2)),
         array_to_string(ri.exception_codes, ', ')
  from public.receipts r
  join public.vendors v on v.id = r.vendor_id
  join public.receipt_items ri on ri.receipt_id = r.id
  join public.products p on p.id = ri.product_id
  join public.units u on u.id = ri.unit_id
  left join public.categories c on c.id = p.category_id
  where r.location_id = p_location and r.status = 'posted' and r.delivery_date between p_from and p_to
    and p_location in (select app.user_location_ids())
$$;

-- Vendor delivery & invoice accuracy.
create or replace function public.report_vendor_performance(p_location uuid, p_from date, p_to date)
returns table (vendor_name text, receipts bigint, lines bigint, short_lines bigint, over_lines bigint, back_orders bigint, substitutions bigint,
               price_variance_lines bigint, rejected_lines bigint, temp_failures bigint, fill_rate_pct numeric, late_deliveries bigint,
               invoice_over_short numeric, purchases numeric)
language sql stable security definer set search_path = public as $$
  select v.name, count(distinct r.id), count(ri.id),
         count(*) filter (where 'short' = any(ri.exception_codes) or 'missing' = any(ri.exception_codes)),
         count(*) filter (where 'over' = any(ri.exception_codes)),
         count(*) filter (where 'back_order' = any(ri.exception_codes)),
         count(*) filter (where 'substitution' = any(ri.exception_codes)),
         count(*) filter (where 'price_variance' = any(ri.exception_codes)),
         count(*) filter (where 'rejected' = any(ri.exception_codes)),
         count(*) filter (where 'temp_out_of_range' = any(ri.exception_codes)),
         round(100.0 * sum(least(coalesce(ri.received_qty, 0), ri.ordered_qty)) filter (where ri.ordered_qty > 0) / nullif(sum(ri.ordered_qty) filter (where ri.ordered_qty > 0), 0), 1),
         count(distinct r.id) filter (where po.expected_delivery_date < r.delivery_date),
         (select coalesce(sum(r2.invoice_total), 0) - coalesce(sum((public.receipt_totals(r2.id) ->> 'calculated_total')::numeric), 0)
            from public.receipts r2 where r2.vendor_id = v.id and r2.location_id = p_location and r2.status = 'posted' and r2.delivery_date between p_from and p_to),
         sum(coalesce(ri.invoice_extended, coalesce(ri.invoiced_qty, 0) * coalesce(ri.invoice_price, 0)))
  from public.receipts r
  join public.vendors v on v.id = r.vendor_id
  join public.receipt_items ri on ri.receipt_id = r.id
  left join public.purchase_orders po on po.id = r.purchase_order_id
  where r.location_id = p_location and r.status = 'posted' and r.delivery_date between p_from and p_to
    and p_location in (select app.user_location_ids())
  group by v.id, v.name
$$;

-- System suggestion vs manager order (ordering behaviour analysis).
create or replace function public.report_order_accuracy(p_location uuid, p_from date, p_to date)
returns table (po_id uuid, po_number text, vendor_name text, delivery_date date, product_name text, unit_code text,
               suggested_qty numeric, ordered_qty numeric, difference numeric, difference_value numeric)
language sql stable security definer set search_path = public as $$
  select po.id, po.po_number, v.name, po.expected_delivery_date, p.name, u.code, i.suggested_qty, i.order_qty,
         i.order_qty - i.suggested_qty, round((i.order_qty - i.suggested_qty) * i.unit_price, 2)
  from public.purchase_orders po
  join public.vendors v on v.id = po.vendor_id
  join public.purchase_order_items i on i.po_id = po.id
  join public.products p on p.id = i.product_id
  join public.units u on u.id = i.unit_id
  where po.location_id = p_location and po.status not in ('draft', 'ready_to_submit', 'cancelled') and i.suggested_qty is not null
    and po.expected_delivery_date between p_from and p_to and p_location in (select app.user_location_ids())
$$;

select app.apply_grants();

-- ============================================================================
-- 20260930001300_invoice_scans.sql
-- ============================================================================
-- Phase 8: invoice scanning. Stores what was extracted (never the posting itself):
-- a person reviews it, applies it to the receipt, saves, and reconciles as usual.
create table public.invoice_scans (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id),
  location_id     uuid not null references public.locations(id),
  receipt_id      uuid references public.receipts(id),
  file_name       text,
  media_type      text,
  extracted       jsonb not null,
  model           text,
  applied         boolean not null default false,
  created_by      uuid references public.profiles(id) default auth.uid(),
  created_at      timestamptz not null default now()
);
create index on public.invoice_scans (receipt_id);
alter table public.invoice_scans enable row level security;
create policy invoice_scans_select on public.invoice_scans for select to authenticated using (location_id in (select app.user_location_ids()));
create policy invoice_scans_insert on public.invoice_scans for insert to authenticated
  with check (app.has_permission('orders.receive', location_id) and organization_id = app.location_org(location_id));
create policy invoice_scans_update on public.invoice_scans for update to authenticated
  using (app.has_permission('orders.receive', location_id)) with check (app.has_permission('orders.receive', location_id));
select app.apply_grants();

-- ============================================================================
-- 20260930001400_operational_alerts.sql
-- ============================================================================
-- =====================================================================
-- Operational alerts beyond stock levels. Each alert has a stable dedupe
-- key, so refreshing is idempotent and alerts resolve themselves when the
-- condition clears.
-- =====================================================================
create or replace function public.refresh_operational_alerts(p_location uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_tz text; v_today date; v_keep text[]; r record; v_last public.count_sessions; v_loc public.locations;
begin
  if not (p_location in (select app.user_location_ids())) then raise exception 'Location not found' using errcode = '42501'; end if;
  select * into v_loc from public.locations where id = p_location;
  v_tz := v_loc.timezone;
  v_today := (now() at time zone v_tz)::date;

  -- Late deliveries: submitted/confirmed orders past their expected date
  select array_agg('late:' || id) into v_keep from public.purchase_orders
   where location_id = p_location and status in ('submitted', 'confirmed') and expected_delivery_date < v_today;
  for r in select po.*, v.name as vendor from public.purchase_orders po join public.vendors v on v.id = po.vendor_id
           where po.location_id = p_location and po.status in ('submitted', 'confirmed') and po.expected_delivery_date < v_today loop
    perform app.raise_alert(p_location, 'late_delivery', 'warning', format('Late delivery: %s %s', r.vendor, r.po_number),
      format('Expected %s and not received yet.', to_char(r.expected_delivery_date, 'Mon DD')), 'late:' || r.id, null, 'purchase_order', r.id);
  end loop;
  perform app.resolve_alerts(p_location, 'late:', v_keep);

  -- Orders not submitted: drafts whose delivery is tomorrow or earlier
  select array_agg('unsubmitted:' || id) into v_keep from public.purchase_orders
   where location_id = p_location and status in ('draft', 'ready_to_submit') and expected_delivery_date <= v_today + 1;
  for r in select po.*, v.name as vendor from public.purchase_orders po join public.vendors v on v.id = po.vendor_id
           where po.location_id = p_location and po.status in ('draft', 'ready_to_submit') and po.expected_delivery_date <= v_today + 1 loop
    perform app.raise_alert(p_location, 'order_not_submitted', 'critical', format('Order not submitted: %s %s', r.vendor, r.po_number),
      format('Delivery is %s but the order is still %s.', to_char(r.expected_delivery_date, 'Mon DD'), replace(r.status::text, '_', ' ')), 'unsubmitted:' || r.id, null, 'purchase_order', r.id);
  end loop;
  perform app.resolve_alerts(p_location, 'unsubmitted:', v_keep);

  -- Expiring lots still likely on hand (received in the last 60 days, expiring within 2 days)
  select array_agg(distinct 'expiring:' || l.id) into v_keep
  from public.lots l join public.lot_receipts lr on lr.lot_id = l.id
  where lr.location_id = p_location and l.expiration_date between v_today - 1 and v_today + 2 and lr.received_at > now() - interval '60 days';
  for r in select distinct l.id, l.lot_number, l.expiration_date, l.product_id, p.name
           from public.lots l join public.lot_receipts lr on lr.lot_id = l.id join public.products p on p.id = l.product_id
           where lr.location_id = p_location and l.expiration_date between v_today - 1 and v_today + 2 and lr.received_at > now() - interval '60 days' loop
    perform app.raise_alert(p_location, 'expiring_product', 'warning', format('Expiring: %s lot %s', r.name, r.lot_number),
      format('Expires %s. Use first or log it as waste.', to_char(r.expiration_date, 'Mon DD')), 'expiring:' || r.id, r.product_id, 'lot', r.id);
  end loop;
  perform app.resolve_alerts(p_location, 'expiring:', v_keep);

  -- High waste: last 7 days above 2% of sales (or above $150 without sales data)
  declare v_waste numeric; v_sales numeric;
  begin
    select coalesce(sum(total_cost), 0) into v_waste from public.waste_logs where location_id = p_location and business_date > v_today - 7;
    select coalesce(sum(net_sales), 0) into v_sales from public.sales_imports where location_id = p_location and status = 'posted' and business_date > v_today - 7;
    if (v_sales > 0 and v_waste / v_sales > 0.02) or (v_sales = 0 and v_waste > 150) then
      perform app.raise_alert(p_location, 'high_waste', 'warning', 'High waste this week',
        format('$%s of waste in 7 days%s.', round(v_waste, 2), case when v_sales > 0 then format(' (%s%% of sales)', round(v_waste / v_sales * 100, 1)) else '' end), 'high_waste');
    else
      perform app.resolve_alerts(p_location, 'high_waste', null);
    end if;
  end;

  -- High variance: lines over tolerance on the most recent posted count (last 7 days)
  select * into v_last from public.count_sessions where location_id = p_location and status = 'posted' and count_at > now() - interval '7 days' order by count_at desc limit 1;
  v_keep := null;
  if v_last.id is not null then
    select array_agg('variance:' || v_last.id || ':' || pl.product_id) into v_keep
    from public.count_posting_lines pl where pl.session_id = v_last.id and pl.variance_value < -v_loc.count_variance_value_tolerance;
    for r in select pl.*, p.name, u.code from public.count_posting_lines pl join public.products p on p.id = pl.product_id join public.units u on u.id = p.inventory_unit_id
             where pl.session_id = v_last.id and pl.variance_value < -v_loc.count_variance_value_tolerance loop
      perform app.raise_alert(p_location, 'high_variance', 'warning', format('High inventory variance: %s', r.name),
        format('%s %s (%s) on %s.', round(r.variance_qty, 2), r.code, to_char(r.variance_value, 'FM$999,990.00'), v_last.name),
        'variance:' || v_last.id || ':' || r.product_id, r.product_id, 'count_session', v_last.id);
    end loop;
  end if;
  perform app.resolve_alerts(p_location, 'variance:', v_keep);

  -- Unexpected consumption: yesterday's theoretical usage of an item is > 3x its daily average
  select array_agg('unexpected:' || x.product_id) into v_keep from (
    select t.product_id from public.inventory_transactions t
    where t.location_id = p_location and t.business_date = v_today - 1 and t.txn_type in ('POS_CONSUMPTION', 'RECIPE_CONSUMPTION')
    group by t.product_id
    having -sum(t.quantity) > 3 * greatest(app.avg_daily_usage(p_location, t.product_id, 28), 0.0001) and app.avg_daily_usage(p_location, t.product_id, 28) > 0) x;
  for r in select t.product_id, p.name, -sum(t.quantity) as used, u.code from public.inventory_transactions t join public.products p on p.id = t.product_id join public.units u on u.id = p.inventory_unit_id
           where t.location_id = p_location and t.business_date = v_today - 1 and t.txn_type in ('POS_CONSUMPTION', 'RECIPE_CONSUMPTION')
           group by t.product_id, p.name, u.code
           having -sum(t.quantity) > 3 * greatest(app.avg_daily_usage(p_location, t.product_id, 28), 0.0001) and app.avg_daily_usage(p_location, t.product_id, 28) > 0 loop
    perform app.raise_alert(p_location, 'unexpected_consumption', 'info', format('Unusual usage: %s', r.name),
      format('%s %s used yesterday, more than 3× the daily average. Check the POS mapping or recipe.', round(r.used, 2), r.code), 'unexpected:' || r.product_id, r.product_id);
  end loop;
  perform app.resolve_alerts(p_location, 'unexpected:', v_keep);
end $$;

-- Dashboard refreshes operational alerts along with stock alerts.
create or replace function public.refresh_stock_alerts_all(p_location uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform public.refresh_stock_alerts(p_location);
  perform public.refresh_operational_alerts(p_location);
end $$;

select app.apply_grants();

-- ============================================================================
-- 20260930001500_scheduled_alerts.sql
-- ============================================================================
-- =====================================================================
-- Scheduled alert refresh. Alerts normally refresh when someone opens the
-- dashboard; this lets a database job (pg_cron) refresh every active
-- location so alerts exist even if nobody has visited.
--
-- A "system caller" is a direct database session with no signed-in user
-- (pg_cron, psql as the owner). Requests through the API always arrive as
-- the `authenticator` login role, so they can never qualify.
-- =====================================================================
create or replace function app.is_system_caller() returns boolean
language sql stable as $$
  select auth.uid() is null and session_user <> 'authenticator'
$$;

create or replace function app.require_location_access(p_location uuid) returns void
language plpgsql stable security definer set search_path = public as $$
begin
  if app.is_system_caller() then return; end if;
  if not (p_location in (select app.user_location_ids())) then raise exception 'Location not found' using errcode = '42501'; end if;
end $$;

create or replace function public.refresh_stock_alerts(p_location uuid) returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_keep text[];
  v_n integer;
begin
  perform app.require_location_access(p_location);

  with st as (
    select ci.* from public.current_inventory ci where ci.location_id = p_location and ci.active
  ),
  raised as (
    select app.raise_alert(p_location,
             case st.stock_status when 'negative' then 'negative_inventory'::public.alert_type
                                  when 'out' then 'out_of_stock'::public.alert_type
                                  when 'critical' then 'critical_stock'::public.alert_type
                                  else 'low_stock'::public.alert_type end,
             case when st.stock_status in ('negative', 'out', 'critical') then 'critical' else 'warning' end,
             case st.stock_status when 'negative' then 'Negative inventory: ' || st.product_name
                                  when 'out' then 'Out of stock: ' || st.product_name
                                  when 'critical' then 'Critical stock: ' || st.product_name
                                  else 'Low stock: ' || st.product_name end,
             case when st.stock_status = 'negative'
                  then format('Book inventory is %s %s. Possible causes: missing receipt, incorrect recipe, missing production, wrong unit conversion, unrecorded transfer or a bad count.', st.on_hand, st.inventory_unit)
                  else format('On hand %s %s (par %s)', st.on_hand, st.inventory_unit, coalesce(st.effective_par::text, 'not set')) end,
             'stock:' || st.product_id || ':' || st.stock_status, st.product_id, 'product', st.product_id,
             jsonb_build_object('on_hand', st.on_hand, 'par', st.effective_par)) as x,
           'stock:' || st.product_id || ':' || st.stock_status as k
    from st
    where st.stock_status <> 'ok'
      and (st.stock_status = 'negative' or st.effective_par is not null or st.min_qty is not null or st.last_txn_at is not null)
  )
  select array_agg(k) into v_keep from raised;
  perform app.resolve_alerts(p_location, 'stock:', v_keep);

  -- Inventory due: no posted count in 7 days
  if not exists (select 1 from public.count_sessions where location_id = p_location and status = 'posted' and count_at > now() - interval '7 days') then
    perform app.raise_alert(p_location, 'inventory_due', 'warning', 'Weekly inventory is due',
      'No inventory count has been posted in the last 7 days.', 'inventory_due');
  else
    perform app.resolve_alerts(p_location, 'inventory_due', null);
  end if;

  -- Counts waiting too long for posting
  select array_agg('count_unposted:' || id) into v_keep from public.count_sessions
   where location_id = p_location and status in ('awaiting_review', 'reviewed') and submitted_at < now() - interval '24 hours';
  perform app.raise_alert(p_location, 'inventory_not_posted', 'warning', 'Inventory not posted: ' || s.name,
    'Submitted ' || to_char(s.submitted_at, 'Mon DD HH24:MI') || ' and still not posted.', 'count_unposted:' || s.id, null, 'count_session', s.id)
  from public.count_sessions s
  where s.location_id = p_location and s.status in ('awaiting_review', 'reviewed') and s.submitted_at < now() - interval '24 hours';
  perform app.resolve_alerts(p_location, 'count_unposted:', v_keep);

  select count(*) into v_n from public.alerts where location_id = p_location and status <> 'resolved';
  return v_n;
end $$;

create or replace function public.refresh_operational_alerts(p_location uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_tz text; v_today date; v_keep text[]; r record; v_last public.count_sessions; v_loc public.locations;
begin
  perform app.require_location_access(p_location);
  select * into v_loc from public.locations where id = p_location;
  v_tz := v_loc.timezone;
  v_today := (now() at time zone v_tz)::date;

  -- Late deliveries: submitted/confirmed orders past their expected date
  select array_agg('late:' || id) into v_keep from public.purchase_orders
   where location_id = p_location and status in ('submitted', 'confirmed') and expected_delivery_date < v_today;
  for r in select po.*, v.name as vendor from public.purchase_orders po join public.vendors v on v.id = po.vendor_id
           where po.location_id = p_location and po.status in ('submitted', 'confirmed') and po.expected_delivery_date < v_today loop
    perform app.raise_alert(p_location, 'late_delivery', 'warning', format('Late delivery: %s %s', r.vendor, r.po_number),
      format('Expected %s and not received yet.', to_char(r.expected_delivery_date, 'Mon DD')), 'late:' || r.id, null, 'purchase_order', r.id);
  end loop;
  perform app.resolve_alerts(p_location, 'late:', v_keep);

  -- Orders not submitted: drafts whose delivery is tomorrow or earlier
  select array_agg('unsubmitted:' || id) into v_keep from public.purchase_orders
   where location_id = p_location and status in ('draft', 'ready_to_submit') and expected_delivery_date <= v_today + 1;
  for r in select po.*, v.name as vendor from public.purchase_orders po join public.vendors v on v.id = po.vendor_id
           where po.location_id = p_location and po.status in ('draft', 'ready_to_submit') and po.expected_delivery_date <= v_today + 1 loop
    perform app.raise_alert(p_location, 'order_not_submitted', 'critical', format('Order not submitted: %s %s', r.vendor, r.po_number),
      format('Delivery is %s but the order is still %s.', to_char(r.expected_delivery_date, 'Mon DD'), replace(r.status::text, '_', ' ')), 'unsubmitted:' || r.id, null, 'purchase_order', r.id);
  end loop;
  perform app.resolve_alerts(p_location, 'unsubmitted:', v_keep);

  -- Expiring lots still likely on hand (received in the last 60 days, expiring within 2 days)
  select array_agg(distinct 'expiring:' || l.id) into v_keep
  from public.lots l join public.lot_receipts lr on lr.lot_id = l.id
  where lr.location_id = p_location and l.expiration_date between v_today - 1 and v_today + 2 and lr.received_at > now() - interval '60 days';
  for r in select distinct l.id, l.lot_number, l.expiration_date, l.product_id, p.name
           from public.lots l join public.lot_receipts lr on lr.lot_id = l.id join public.products p on p.id = l.product_id
           where lr.location_id = p_location and l.expiration_date between v_today - 1 and v_today + 2 and lr.received_at > now() - interval '60 days' loop
    perform app.raise_alert(p_location, 'expiring_product', 'warning', format('Expiring: %s lot %s', r.name, r.lot_number),
      format('Expires %s. Use first or log it as waste.', to_char(r.expiration_date, 'Mon DD')), 'expiring:' || r.id, r.product_id, 'lot', r.id);
  end loop;
  perform app.resolve_alerts(p_location, 'expiring:', v_keep);

  -- High waste: last 7 days above 2% of sales (or above $150 without sales data)
  declare v_waste numeric; v_sales numeric;
  begin
    select coalesce(sum(total_cost), 0) into v_waste from public.waste_logs where location_id = p_location and business_date > v_today - 7;
    select coalesce(sum(net_sales), 0) into v_sales from public.sales_imports where location_id = p_location and status = 'posted' and business_date > v_today - 7;
    if (v_sales > 0 and v_waste / v_sales > 0.02) or (v_sales = 0 and v_waste > 150) then
      perform app.raise_alert(p_location, 'high_waste', 'warning', 'High waste this week',
        format('$%s of waste in 7 days%s.', round(v_waste, 2), case when v_sales > 0 then format(' (%s%% of sales)', round(v_waste / v_sales * 100, 1)) else '' end), 'high_waste');
    else
      perform app.resolve_alerts(p_location, 'high_waste', null);
    end if;
  end;

  -- High variance: lines over tolerance on the most recent posted count (last 7 days)
  select * into v_last from public.count_sessions where location_id = p_location and status = 'posted' and count_at > now() - interval '7 days' order by count_at desc limit 1;
  v_keep := null;
  if v_last.id is not null then
    select array_agg('variance:' || v_last.id || ':' || pl.product_id) into v_keep
    from public.count_posting_lines pl where pl.session_id = v_last.id and pl.variance_value < -v_loc.count_variance_value_tolerance;
    for r in select pl.*, p.name, u.code from public.count_posting_lines pl join public.products p on p.id = pl.product_id join public.units u on u.id = p.inventory_unit_id
             where pl.session_id = v_last.id and pl.variance_value < -v_loc.count_variance_value_tolerance loop
      perform app.raise_alert(p_location, 'high_variance', 'warning', format('High inventory variance: %s', r.name),
        format('%s %s (%s) on %s.', round(r.variance_qty, 2), r.code, to_char(r.variance_value, 'FM$999,990.00'), v_last.name),
        'variance:' || v_last.id || ':' || r.product_id, r.product_id, 'count_session', v_last.id);
    end loop;
  end if;
  perform app.resolve_alerts(p_location, 'variance:', v_keep);

  -- Unexpected consumption: yesterday's theoretical usage of an item is > 3x its daily average
  select array_agg('unexpected:' || x.product_id) into v_keep from (
    select t.product_id from public.inventory_transactions t
    where t.location_id = p_location and t.business_date = v_today - 1 and t.txn_type in ('POS_CONSUMPTION', 'RECIPE_CONSUMPTION')
    group by t.product_id
    having -sum(t.quantity) > 3 * greatest(app.avg_daily_usage(p_location, t.product_id, 28), 0.0001) and app.avg_daily_usage(p_location, t.product_id, 28) > 0) x;
  for r in select t.product_id, p.name, -sum(t.quantity) as used, u.code from public.inventory_transactions t join public.products p on p.id = t.product_id join public.units u on u.id = p.inventory_unit_id
           where t.location_id = p_location and t.business_date = v_today - 1 and t.txn_type in ('POS_CONSUMPTION', 'RECIPE_CONSUMPTION')
           group by t.product_id, p.name, u.code
           having -sum(t.quantity) > 3 * greatest(app.avg_daily_usage(p_location, t.product_id, 28), 0.0001) and app.avg_daily_usage(p_location, t.product_id, 28) > 0 loop
    perform app.raise_alert(p_location, 'unexpected_consumption', 'info', format('Unusual usage: %s', r.name),
      format('%s %s used yesterday, more than 3× the daily average. Check the POS mapping or recipe.', round(r.used, 2), r.code), 'unexpected:' || r.product_id, r.product_id);
  end loop;
  perform app.resolve_alerts(p_location, 'unexpected:', v_keep);
end $$;

create or replace function app.refresh_all_alerts() returns integer
language plpgsql security definer set search_path = public as $$
declare r record; n int := 0;
begin
  if not app.is_system_caller() then raise exception 'System job only' using errcode = '42501'; end if;
  for r in select id from public.locations where active loop
    begin
      perform public.refresh_stock_alerts(r.id);
      perform public.refresh_operational_alerts(r.id);
      n := n + 1;
    exception when others then
      -- one broken location must not stop the others
      raise warning 'alert refresh failed for location %: %', r.id, sqlerrm;
    end;
  end loop;
  return n;
end $$;
revoke all on function app.refresh_all_alerts() from public;

-- Schedule every 30 minutes where pg_cron is available (hosted Supabase).
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;
    perform cron.schedule('stockline-refresh-alerts', '*/30 * * * *', 'select app.refresh_all_alerts()');
  end if;
exception when others then
  raise notice 'pg_cron not scheduled (%); run app.refresh_all_alerts() from your scheduler instead', sqlerrm;
end $$;

select app.apply_grants();

-- ============================================================================
-- 20260930001600_count_assignments.sql
-- ============================================================================
-- =====================================================================
-- Count assignments: a reviewer splits a count between counters by
-- storage area ("Maria: Walk-In Cooler, John: Dry Storage"). Counters still
-- may count anything; assignments set what their screen opens to and let
-- the reviewer see which areas are still waiting on someone.
-- =====================================================================
alter table public.count_assignments add column if not exists assigned_by uuid references public.profiles(id);

-- Only these RPCs write assignments (validation + audit)
insert into app.write_protected_tables (table_name) values ('count_assignments') on conflict do nothing;
drop policy if exists ca_write on public.count_assignments;

-- People who can count at the session's location
create or replace function public.count_assignable_users(p_session uuid) returns table (user_id uuid, full_name text, email text)
language plpgsql stable security definer set search_path = public as $$
declare v_s public.count_sessions;
begin
  select * into v_s from public.count_sessions where id = p_session;
  if v_s.id is null then raise exception 'Count not found' using errcode = '42501'; end if;
  perform app.require_permission('inventory.review', v_s.location_id);
  return query
    select distinct pr.id, pr.full_name, pr.email
    from public.locations l
    join public.user_roles ur on ur.organization_id = l.organization_id
    join public.organization_members m on m.organization_id = l.organization_id and m.user_id = ur.user_id and m.active
    join public.role_permissions rp on rp.role_id = ur.role_id and rp.permission_key = 'inventory.count'
    join public.profiles pr on pr.id = ur.user_id
    where l.id = v_s.location_id
      and (   ur.scope_type = 'organization'
           or (ur.scope_type = 'region'   and ur.scope_id = l.region_id)
           or (ur.scope_type = 'district' and ur.scope_id = l.district_id)
           or (ur.scope_type = 'location' and ur.scope_id = l.id))
    order by pr.full_name;
end $$;

create or replace function app.parse_count_assignments(p jsonb) returns table (user_id uuid, storage_location_id uuid)
language sql immutable as $$
  select distinct (a->>'user_id')::uuid, nullif(sid, 'null')::uuid
  from jsonb_array_elements(coalesce(p, '[]'::jsonb)) a
  cross join lateral jsonb_array_elements_text(coalesce(a->'storage_location_ids', '[]'::jsonb)) sid
$$;

-- Replace all assignments on a session in one step.
-- p_assignments: [{"user_id": uuid, "storage_location_ids": [uuid | null, ...]}]
-- A null storage id means the "Unassigned" products (no storage area).
create or replace function public.set_count_assignments(p_session uuid, p_assignments jsonb) returns integer
language plpgsql security definer set search_path = public as $$
declare v_s public.count_sessions; v_n int;
begin
  select * into v_s from public.count_sessions where id = p_session for update;
  if v_s.id is null then raise exception 'Count not found' using errcode = '42501'; end if;
  perform app.require_permission('inventory.review', v_s.location_id);
  if v_s.status in ('posted', 'cancelled') then
    raise exception 'This count is % and can no longer be assigned', replace(v_s.status::text, '_', ' ') using errcode = 'P0001';
  end if;

  if exists (select 1 from app.parse_count_assignments(p_assignments) t
             where not exists (select 1 from public.count_assignable_users(p_session) u where u.user_id = t.user_id)) then
    raise exception 'Someone in the list cannot count at this location' using errcode = 'P0001';
  end if;
  if exists (select 1 from app.parse_count_assignments(p_assignments) t where t.storage_location_id is not null
             and not exists (select 1 from public.storage_locations sl where sl.id = t.storage_location_id and sl.location_id = v_s.location_id)) then
    raise exception 'Storage area does not belong to this location' using errcode = 'P0001';
  end if;

  delete from public.count_assignments where session_id = p_session;
  insert into public.count_assignments (session_id, user_id, storage_location_id, assigned_by)
  select p_session, t.user_id, t.storage_location_id, auth.uid() from app.parse_count_assignments(p_assignments) t;
  get diagnostics v_n = row_count;

  perform app.audit(v_s.organization_id, v_s.location_id, 'assign', 'count_session', p_session::text,
    format('%s area assignment(s) set on %s', v_n, v_s.name), null, p_assignments);
  return v_n;
end $$;

-- The count sheet carries its assignments so counters see them offline too.
do $$
begin
  if not exists (select 1 from pg_proc where proname = 'get_count_sheet_base' and pronamespace = 'public'::regnamespace) then
    alter function public.get_count_sheet(uuid) rename to get_count_sheet_base;
  end if;
end $$;

create or replace function public.get_count_sheet(p_session uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select public.get_count_sheet_base(p_session) || jsonb_build_object(
    'assignments', coalesce((
      select jsonb_agg(jsonb_build_object('user_id', a.user_id, 'name', coalesce(pr.full_name, pr.email), 'storage_location_id', a.storage_location_id)
                       order by pr.full_name)
      from public.count_assignments a join public.profiles pr on pr.id = a.user_id
      where a.session_id = p_session), '[]'::jsonb),
    'me', auth.uid())
$$;

select app.apply_grants();

-- ============================================================================
-- 20260930001700_location_vendor_settings.sql
-- ============================================================================
-- =====================================================================
-- Per-store vendor settings. The company sets a vendor's delivery days,
-- lead time, cutoff and account number; a store can override any of them
-- (e.g. Westside gets Sysco Tue/Fri on its own account) or stop using the
-- vendor. Blank override fields fall back to the company value.
-- =====================================================================
alter table public.location_vendors add column if not exists notes text;

create trigger trg_location_vendors_audit after insert or update or delete on public.location_vendors
  for each row execute function app.audit_row();

-- Effective schedule per store and vendor: what ordering screens use.
create or replace view public.location_vendor_settings with (security_invoker = true) as
select l.id as location_id, v.id as vendor_id, v.organization_id, v.name as vendor_name,
       coalesce(lv.delivery_days, v.delivery_days) as delivery_days,
       coalesce(lv.lead_time_days, v.lead_time_days) as lead_time_days,
       coalesce(lv.order_cutoff, v.order_cutoff) as order_cutoff,
       coalesce(lv.account_number, v.account_number) as account_number,
       v.minimum_order, v.ordering_email, v.active as company_active,
       (v.active and coalesce(lv.active, true)) as active,
       lv.id is not null as has_override,
       lv.delivery_days is not null as delivery_days_overridden,
       lv.lead_time_days is not null as lead_time_overridden,
       lv.order_cutoff is not null as cutoff_overridden,
       lv.account_number is not null as account_overridden
from public.locations l
join public.vendors v on v.organization_id = l.organization_id
left join public.location_vendors lv on lv.location_id = l.id and lv.vendor_id = v.id;

-- Dynamic pars honor the store's lead time as well as its delivery days.
create or replace function public.refresh_dynamic_pars(p_location uuid) returns integer
language plpgsql security definer set search_path = public as $$
declare r record; v_days int; v_par numeric; n int := 0;
begin
  perform app.require_permission('inventory.view', p_location);
  for r in
    select lp.id, lp.product_id, lp.safety_stock_days,
           coalesce(lv.lead_time_days, v.lead_time_days, 1) as lead, coalesce(array_length(coalesce(lv.delivery_days, v.delivery_days), 1), 1) as deliveries
    from public.location_products lp
    join public.products p on p.id = lp.product_id
    left join public.vendors v on v.id = coalesce(lp.local_vendor_id, p.default_vendor_id)
    left join public.location_vendors lv on lv.vendor_id = v.id and lv.location_id = p_location
    where lp.location_id = p_location and lp.par_mode = 'dynamic' and lp.active
  loop
    v_days := r.lead + ceil(7.0 / greatest(r.deliveries, 1))::int;
    v_par := (app.forecast_usage(p_location, r.product_id, current_date, current_date + v_days) ->> 'qty')::numeric
             + coalesce(r.safety_stock_days, 0) * app.avg_daily_usage(p_location, r.product_id, 28);
    update public.location_products set dynamic_par_qty = round(v_par, 2), dynamic_par_at = now() where id = r.id;
    n := n + 1;
  end loop;
  return n;
end $$;

select app.apply_grants();

-- ============================================================================
-- 20260930001800_ordering_setting.sql
-- ============================================================================
-- =====================================================================
-- Ordering is optional. Many restaurants order in each vendor's own app
-- and only record deliveries here. organizations.settings.ordering_enabled
-- (default false) switches the purchase-order screens on; receiving,
-- invoice reconciliation, costing and price history work either way.
-- =====================================================================

-- The session context carries organization settings so screens can adapt.
create or replace function public.get_session_context() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then return null; end if;
  return jsonb_build_object(
    'user', (select to_jsonb(p) from public.profiles p where p.id = v_uid),
    'organizations', coalesce((select jsonb_agg(jsonb_build_object('id', o.id, 'name', o.name, 'currency', o.currency, 'settings', o.settings) order by o.name)
                        from public.organizations o where o.id in (select app.user_org_ids())), '[]'::jsonb),
    'locations', coalesce((select jsonb_agg(jsonb_build_object(
                        'id', l.id, 'organization_id', l.organization_id, 'code', l.code, 'name', l.name,
                        'timezone', l.timezone, 'region_id', l.region_id, 'district_id', l.district_id, 'market', l.market,
                        'permissions', (select coalesce(jsonb_agg(distinct rp.permission_key), '[]'::jsonb)
                                        from public.user_roles ur
                                        join public.role_permissions rp on rp.role_id = ur.role_id
                                        join public.permissions pm on pm.key = rp.permission_key
                                        where ur.user_id = v_uid and ur.organization_id = l.organization_id
                                          and (ur.scope_type = 'organization'
                                               or (not pm.org_scope_only and (
                                                     (ur.scope_type = 'region' and ur.scope_id = l.region_id)
                                                  or (ur.scope_type = 'district' and ur.scope_id = l.district_id)
                                                  or (ur.scope_type = 'location' and ur.scope_id = l.id))))))
                        order by l.code)
                      from public.locations l where l.id in (select app.user_location_ids()) and l.active), '[]'::jsonb),
    'org_permissions', coalesce((select jsonb_agg(distinct jsonb_build_object('organization_id', ur.organization_id, 'permission', rp.permission_key))
                        from public.user_roles ur join public.role_permissions rp on rp.role_id = ur.role_id
                        join public.organization_members m on m.organization_id = ur.organization_id and m.user_id = ur.user_id and m.active
                        where ur.user_id = v_uid and ur.scope_type = 'organization'), '[]'::jsonb),
    'roles', coalesce((select jsonb_agg(jsonb_build_object('role', r.key, 'name', r.name, 'scope_type', ur.scope_type, 'scope_id', ur.scope_id))
                        from public.user_roles ur join public.roles r on r.id = ur.role_id where ur.user_id = v_uid), '[]'::jsonb)
  );
end $$;

-- Change one organization setting (merged into settings, audited).
create or replace function public.set_organization_setting(p_org uuid, p_key text, p_value jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_old jsonb; v_new jsonb;
begin
  if not app.has_org_permission('settings.manage', p_org) then
    raise exception 'You do not have permission to change organization settings' using errcode = '42501';
  end if;
  if p_key not in ('ordering_enabled') then raise exception 'Unknown setting %', p_key using errcode = 'P0001'; end if;
  if p_key = 'ordering_enabled' and jsonb_typeof(p_value) <> 'boolean' then raise exception 'ordering_enabled must be true or false' using errcode = 'P0001'; end if;
  select settings into v_old from public.organizations where id = p_org for update;
  update public.organizations set settings = settings || jsonb_build_object(p_key, p_value) where id = p_org returning settings into v_new;
  perform app.audit(p_org, null, 'update', 'organization_settings', p_org::text, format('Setting %s changed', p_key),
    jsonb_build_object(p_key, v_old -> p_key), jsonb_build_object(p_key, p_value));
  return v_new;
end $$;

select app.apply_grants();

-- ============================================================================
-- 20260930001900_product_import.sql
-- ============================================================================
-- =====================================================================
-- Product import from a spreadsheet. One function validates and applies
-- every row; with p_apply = false it runs the same code inside a
-- savepoint and rolls it back, so the preview shows exactly what an
-- import would do. Missing categories, vendors and storage areas are
-- created. Existing products (same item # or same name) are updated, never
-- duplicated, and their count unit is never changed (the ledger is stored
-- in it). Rows with problems are skipped and reported.
-- =====================================================================

-- Unit lookup that accepts what people type: "lbs", "Pounds", "each", "cs", "fl oz".
create or replace function app.resolve_unit(p_org uuid, p_text text) returns uuid
language plpgsql stable security definer set search_path = public as $$
declare
  t text := upper(regexp_replace(btrim(coalesce(p_text, '')), '[.]', '', 'g'));
  v uuid;
begin
  if t = '' then return null; end if;
  t := case
    when t in ('LBS', 'POUND', 'POUNDS', '#') then 'LB'
    when t in ('OUNCE', 'OUNCES', 'OZS') then 'OZ'
    when t in ('EACH', 'EAS', 'CT', 'COUNT', 'PC', 'PCS', 'PIECE', 'PIECES', 'UNIT', 'UNITS') then 'EA'
    when t in ('CS', 'CASES', 'CA') then 'CASE'
    when t in ('GALLON', 'GALLONS', 'GALS') then 'GAL'
    when t in ('QUART', 'QUARTS', 'QTS') then 'QT'
    when t in ('PINT', 'PINTS', 'PTS') then 'PT'
    when t in ('CUPS') then 'CUP'
    when t in ('FLOZ', 'FL-OZ', 'FLUID OUNCE', 'FLUID OUNCES') then 'FL OZ'
    when t in ('KILO', 'KILOS', 'KILOGRAM', 'KILOGRAMS', 'KGS') then 'KG'
    when t in ('GRAM', 'GRAMS', 'GR') then 'G'
    when t in ('LITER', 'LITERS', 'LITRE', 'LITRES', 'LT') then 'L'
    when t in ('MILLILITER', 'MILLILITERS', 'MLS') then 'ML'
    when t in ('DOZEN', 'DOZ') then 'DZ'
    when t in ('BAGS', 'BG') then 'BAG'
    when t in ('BOXES', 'BX') then 'BOX'
    when t in ('CARTON', 'CARTONS') then 'CTN'
    when t in ('PACK', 'PACKS', 'PKG', 'PACKAGE') then 'PK'
    when t in ('BOTTLE', 'BOTTLES', 'BTLS') then 'BTL'
    when t in ('CANS') then 'CAN'
    when t in ('JUGS') then 'JUG'
    when t in ('KEGS') then 'KEG'
    when t in ('SLEEVES', 'SLV') then 'SLEEVE'
    when t in ('TUBS') then 'TUB'
    when t in ('BUNCHES') then 'BUNCH'
    when t in ('ROLLS') then 'ROLL'
    when t in ('PANS') then 'PAN'
    else t end;
  select id into v from public.units
   where upper(code) = t and (organization_id = p_org or organization_id is null) and active
   order by organization_id nulls last limit 1;
  return v;
end $$;

-- Guess a storage kind from its name (used when the import creates the area).
create or replace function app.guess_storage_kind(p_name text) returns public.storage_kind
language sql immutable as $$
  select case
    when p_name ~* 'freez' then 'walk_in_freezer'
    when p_name ~* 'walk.?in|cooler|fridge|refrig' then 'walk_in_cooler'
    when p_name ~* 'dry|pantry|shelf' then 'dry_storage'
    when p_name ~* 'bar|liquor|beer|wine' then 'bar'
    when p_name ~* 'chem|clean|janitor' then 'chemical'
    when p_name ~* 'line' then 'line'
    when p_name ~* 'prep' then 'prep'
    when p_name ~* 'front|foh' then 'front'
    else 'other' end::public.storage_kind
$$;

-- p_rows: [{name, item_number, category, type, count_unit, case_unit, per_case, vendor, vendor_item_number,
--           case_price, storage_area, shelf, par, upc}]   (strings; blanks allowed except name and count_unit)
create or replace function app.import_products_apply(p_location uuid, p_rows jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_org uuid := app.location_org(p_location);
  r jsonb; i int := 0;
  v_name text; v_num text; v_errors text[]; v_warn text[]; v_action text;
  v_inv uuid; v_case uuid; v_per numeric; v_price numeric; v_par numeric;
  v_cat uuid; v_vendor uuid; v_storage uuid; v_prod public.products; v_type text; v_vin text;
  v_out jsonb := '[]'::jsonb;
  v_new int := 0; v_upd int := 0; v_skip int := 0;
  v_cats text[] := '{}'; v_vendors text[] := '{}'; v_areas text[] := '{}';
  v_next int;
begin
  select coalesce(max(nullif(regexp_replace(product_number, '\D', '', 'g'), '')::bigint), 1000)::int
    into v_next from public.products where organization_id = v_org and product_number ~ '^\d{1,9}$';

  for r in select * from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) loop
    i := i + 1;
    v_errors := '{}'; v_warn := '{}'; v_action := null;
    v_name := btrim(coalesce(r ->> 'name', ''));
    v_num := nullif(btrim(coalesce(r ->> 'item_number', '')), '');
    v_inv := app.resolve_unit(v_org, r ->> 'count_unit');
    v_case := app.resolve_unit(v_org, coalesce(nullif(btrim(r ->> 'case_unit'), ''), case when nullif(btrim(r ->> 'per_case'), '') is not null then 'CASE' end));
    v_type := lower(coalesce(nullif(btrim(r ->> 'type'), ''), 'food'));

    if v_name = '' then v_errors := array_append(v_errors, 'Item name is missing'); end if;
    if coalesce(btrim(r ->> 'count_unit'), '') = '' then v_errors := array_append(v_errors, 'Count unit is missing (e.g. LB, EA, OZ)');
    elsif v_inv is null then v_errors := array_append(v_errors, format('Unknown count unit "%s"', r ->> 'count_unit')); end if;
    if nullif(btrim(r ->> 'case_unit'), '') is not null and v_case is null then v_errors := array_append(v_errors, format('Unknown case unit "%s"', r ->> 'case_unit')); end if;
    begin v_per := nullif(regexp_replace(coalesce(r ->> 'per_case', ''), '[^0-9.]', '', 'g'), '')::numeric;
    exception when others then v_errors := array_append(v_errors, 'Per case is not a number'); v_per := null; end;
    begin v_price := nullif(regexp_replace(coalesce(r ->> 'case_price', ''), '[^0-9.]', '', 'g'), '')::numeric;
    exception when others then v_errors := array_append(v_errors, 'Case price is not a number'); v_price := null; end;
    begin v_par := nullif(regexp_replace(coalesce(r ->> 'par', ''), '[^0-9.]', '', 'g'), '')::numeric;
    exception when others then v_errors := array_append(v_errors, 'Par is not a number'); v_par := null; end;
    if v_per is not null and v_per <= 0 then v_errors := array_append(v_errors, 'Per case must be more than 0'); end if;
    if v_case is not null and v_case = v_inv then v_case := null; v_per := null; end if;
    if v_case is not null and v_per is null then v_errors := array_append(v_errors, 'Say how many count units are in one case (Per case)'); end if;
    if v_type not in ('food', 'beverage', 'alcohol', 'paper', 'supplies', 'other') then
      v_warn := array_append(v_warn, format('Type "%s" not recognised, using Food', r ->> 'type')); v_type := 'food';
    end if;

    if cardinality(v_errors) > 0 then
      v_skip := v_skip + 1;
      v_out := v_out || jsonb_build_object('row', i, 'name', v_name, 'action', 'skip', 'errors', to_jsonb(v_errors), 'warnings', to_jsonb(v_warn));
      continue;
    end if;

    -- Category (top level), vendor, storage area: create when missing
    v_cat := null;
    if nullif(btrim(r ->> 'category'), '') is not null then
      select id into v_cat from public.categories where organization_id = v_org and parent_id is null and lower(name) = lower(btrim(r ->> 'category'));
      if v_cat is null then
        insert into public.categories (organization_id, name, level, cost_group, is_food)
        values (v_org, btrim(r ->> 'category'), 1, v_type, v_type = 'food') returning id into v_cat;
        v_cats := array_append(v_cats, btrim(r ->> 'category'));
      end if;
    end if;
    v_vendor := null;
    if nullif(btrim(r ->> 'vendor'), '') is not null then
      select id into v_vendor from public.vendors where organization_id = v_org and lower(name) = lower(btrim(r ->> 'vendor'));
      if v_vendor is null then
        insert into public.vendors (organization_id, name) values (v_org, btrim(r ->> 'vendor')) returning id into v_vendor;
        v_vendors := array_append(v_vendors, btrim(r ->> 'vendor'));
      end if;
    end if;
    v_storage := null;
    if nullif(btrim(r ->> 'storage_area'), '') is not null then
      select id into v_storage from public.storage_locations where location_id = p_location and lower(name) = lower(btrim(r ->> 'storage_area'));
      if v_storage is null then
        insert into public.storage_locations (organization_id, location_id, name, kind, sort_order)
        values (v_org, p_location, btrim(r ->> 'storage_area'), app.guess_storage_kind(r ->> 'storage_area'),
                coalesce((select max(sort_order) + 1 from public.storage_locations where location_id = p_location), 1))
        returning id into v_storage;
        v_areas := array_append(v_areas, btrim(r ->> 'storage_area'));
      end if;
    end if;

    -- Existing product: same item #, else same name
    v_prod := null;
    if v_num is not null then select * into v_prod from public.products where organization_id = v_org and product_number = v_num and deleted_at is null; end if;
    if v_prod.id is null then select * into v_prod from public.products where organization_id = v_org and lower(name) = lower(v_name) and deleted_at is null limit 1; end if;

    if v_prod.id is null then
      if v_num is null then
        loop
          v_next := v_next + 1;
          exit when not exists (select 1 from public.products where organization_id = v_org and product_number = v_next::text);
        end loop;
        v_num := v_next::text;
      end if;
      insert into public.products (organization_id, product_number, name, category_id, inventory_unit_id, purchase_unit_id, default_vendor_id, standard_cost, created_by)
      values (v_org, v_num, v_name, v_cat, v_inv, coalesce(v_case, v_inv), v_vendor,
              case when v_price is not null then round(v_price / coalesce(v_per, 1), 6) end, auth.uid())
      returning * into v_prod;
      v_action := 'create'; v_new := v_new + 1;
    else
      if v_prod.inventory_unit_id <> v_inv then
        v_warn := array_append(v_warn, format('Already counted in %s; count unit left unchanged', (select code from public.units where id = v_prod.inventory_unit_id)));
      end if;
      update public.products set
        category_id = coalesce(v_cat, category_id),
        default_vendor_id = coalesce(v_vendor, default_vendor_id),
        purchase_unit_id = case when v_prod.inventory_unit_id = v_inv then coalesce(v_case, purchase_unit_id) else purchase_unit_id end
      where id = v_prod.id;
      v_action := 'update'; v_upd := v_upd + 1;
    end if;

    -- Case size (only when the count unit matches, so the factor means what the sheet says)
    if v_case is not null and v_prod.inventory_unit_id = v_inv then
      insert into public.product_units (organization_id, product_id, unit_id, factor, use_for_count, use_for_purchase)
      values (v_org, v_prod.id, v_case, v_per, true, true)
      on conflict (product_id, unit_id) do update set factor = excluded.factor, use_for_purchase = true;
    end if;

    -- Vendor item and price (per case, or per count unit when there is no case)
    if v_vendor is not null then
      v_vin := coalesce(nullif(btrim(r ->> 'vendor_item_number'), ''), v_prod.product_number);
      insert into public.vendor_products (organization_id, vendor_id, product_id, vendor_item_number, purchase_unit_id, pack_size, current_price, is_preferred)
      values (v_org, v_vendor, v_prod.id, v_vin, coalesce(case when v_prod.inventory_unit_id = v_inv then v_case end, v_prod.inventory_unit_id),
              case when v_per is not null then format('%s %s', trim_scale(v_per), (select code from public.units where id = v_prod.inventory_unit_id)) end,
              coalesce(v_price, 0), true)
      on conflict (vendor_id, vendor_item_number) do update set
        current_price = case when v_price is not null then excluded.current_price else vendor_products.current_price end,
        pack_size = coalesce(excluded.pack_size, vendor_products.pack_size),
        purchase_unit_id = excluded.purchase_unit_id
      where vendor_products.product_id = excluded.product_id;
      if not exists (select 1 from public.vendor_products where vendor_id = v_vendor and vendor_item_number = v_vin and product_id = v_prod.id) then
        v_warn := array_append(v_warn, format('Vendor item # %s is already used by another product; vendor link skipped', v_vin));
      end if;
    end if;

    if nullif(btrim(r ->> 'upc'), '') is not null then
      insert into public.product_barcodes (organization_id, product_id, barcode, unit_id, created_by)
      values (v_org, v_prod.id, btrim(r ->> 'upc'), null, auth.uid()) on conflict do nothing;
    end if;

    if v_storage is not null then
      insert into public.product_storage_locations (organization_id, location_id, product_id, storage_location_id, shelf, sort_order)
      values (v_org, p_location, v_prod.id, v_storage, nullif(btrim(r ->> 'shelf'), ''),
              coalesce((select max(sort_order) + 1 from public.product_storage_locations where storage_location_id = v_storage), 1))
      on conflict (storage_location_id, product_id) do update set shelf = coalesce(excluded.shelf, product_storage_locations.shelf), active = true;
    end if;

    if v_par is not null then
      update public.location_products set par_qty = v_par where location_id = p_location and product_id = v_prod.id;
    end if;

    v_out := v_out || jsonb_build_object('row', i, 'name', v_name, 'item_number', v_prod.product_number, 'action', v_action,
                                         'errors', '[]'::jsonb, 'warnings', to_jsonb(v_warn));
  end loop;

  return jsonb_build_object(
    'summary', jsonb_build_object('create', v_new, 'update', v_upd, 'skip', v_skip,
      'categories', to_jsonb(v_cats), 'vendors', to_jsonb(v_vendors), 'storage_areas', to_jsonb(v_areas)),
    'rows', v_out);
end $$;
revoke all on function app.import_products_apply(uuid, jsonb) from public;

create or replace function public.import_products(p_location uuid, p_rows jsonb, p_apply boolean default false) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_result jsonb; v_org uuid := app.location_org(p_location);
begin
  perform app.require_org_permission('products.edit', v_org);
  perform app.require_permission('inventory.settings', p_location);
  if jsonb_array_length(coalesce(p_rows, '[]'::jsonb)) > 5000 then raise exception 'Import at most 5,000 rows at a time' using errcode = 'P0001'; end if;
  begin
    v_result := app.import_products_apply(p_location, p_rows);
    if not p_apply then raise exception 'preview' using errcode = 'P0099'; end if;
  exception when sqlstate 'P0099' then
    null;  -- preview: every change above is rolled back, the report is kept
  end;
  if p_apply then
    perform app.audit(v_org, p_location, 'import', 'products', null,
      format('Imported products: %s new, %s updated, %s skipped', v_result #>> '{summary,create}', v_result #>> '{summary,update}', v_result #>> '{summary,skip}'),
      null, v_result -> 'summary');
  end if;
  return v_result || jsonb_build_object('applied', p_apply);
end $$;

select app.apply_grants();

-- ============================================================================
-- 20260930002000_setup_status.sql
-- ============================================================================
-- =====================================================================
-- Getting-started checklist: what a store has set up so far, in one call.
-- =====================================================================
create or replace function public.setup_status(p_location uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_org uuid := app.location_org(p_location);
begin
  if not (p_location in (select app.user_location_ids())) then raise exception 'Location not found' using errcode = '42501'; end if;
  return jsonb_build_object(
    'address',        (select address_line1 is not null and btrim(address_line1) <> '' from public.locations where id = p_location),
    'storage_areas',  (select count(*) from public.storage_locations where location_id = p_location and active),
    'vendors',        (select count(*) from public.vendors where organization_id = v_org and active),
    'products',       (select count(*) from public.products where organization_id = v_org and active and deleted_at is null),
    'products_placed',(select count(distinct psl.product_id) from public.product_storage_locations psl
                         join public.products p on p.id = psl.product_id
                        where psl.location_id = p_location and psl.active and p.active and p.deleted_at is null),
    'staff',          (select count(*) from public.organization_members where organization_id = v_org and active),
    'counts_posted',  (select count(*) from public.count_sessions where location_id = p_location and status = 'posted'),
    'deliveries',     (select count(*) from public.receipts where location_id = p_location and status = 'posted'),
    'recipes',        (select count(*) from public.recipes where organization_id = v_org and active),
    'menu_items',     (select count(*) from public.menu_items where organization_id = v_org and active and pos_item_id is not null),
    'sales_days',     (select count(*) from public.sales_imports where location_id = p_location and status = 'posted'));
end $$;

select app.apply_grants();

-- ============================================================================
-- 20260930002100_password_reset_guard.sql
-- ============================================================================
-- =====================================================================
-- Managers can set a new temporary password for staff who forgot theirs,
-- but only for people ranked below them (a manager can never take over an
-- owner's login). The password itself is set by the server with the
-- service key after this check passes; the check is audited.
-- =====================================================================
create or replace function public.authorize_password_reset(p_org uuid, p_user uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_mine int; v_theirs int;
begin
  if auth.uid() is null then raise exception 'Not signed in' using errcode = '42501'; end if;
  if p_user = auth.uid() then raise exception 'Change your own password under My account' using errcode = 'P0001'; end if;
  if not exists (select 1 from public.organization_members where organization_id = p_org and user_id = p_user) then
    raise exception 'That person is not in this organization' using errcode = '42501';
  end if;
  select coalesce(max(r.rank), 0) into v_mine
  from public.user_roles ur join public.roles r on r.id = ur.role_id
  join public.role_permissions rp on rp.role_id = r.id and rp.permission_key = 'users.manage'
  join public.organization_members m on m.organization_id = ur.organization_id and m.user_id = ur.user_id and m.active
  where ur.user_id = auth.uid() and ur.organization_id = p_org;
  select coalesce(max(r.rank), 0) into v_theirs
  from public.user_roles ur join public.roles r on r.id = ur.role_id
  where ur.user_id = p_user and ur.organization_id = p_org;
  if v_mine = 0 or v_theirs >= v_mine then
    raise exception 'You can only reset passwords for people below your role' using errcode = '42501';
  end if;
  perform app.audit(p_org, null, 'reset_password', 'user', p_user::text, 'Temporary password set by a manager', null, null);
end $$;

select app.apply_grants();

notify pgrst, 'reload schema';
